import { useEffect, useMemo, useState } from 'react';
import { Pressable, StyleSheet, Switch, Text, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import { Carte } from '@/components/ecran';
import { Alerte, Champ } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useNotifications } from '@/lib/notifications';
import {
  definirSemaineRituel,
  demanderPermissionRituel,
  desactiverSemaineRituel,
  HEURES_PROPOSEES,
  lireSemaineRituel,
  permissionRituel,
  type JourRituel,
} from '@/lib/rituel';
import { espace, ombre, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Le centre de notifications : une LISTE de types de notification, chacun sur sa
 * ligne avec un interrupteur. Pas de grande grille d'heures qui allonge la page.
 *
 * 🔑 Le rappel du soir est une SEMAINE, pas un bloc « chaque soir ». Un
 * interrupteur maître ouvre la section ; dessous, sept jours (lundi→dimanche),
 * chacun avec son interrupteur et son heure. La classe ne tourne pas le week-end,
 * donc le défaut est lundi→vendredi à 16:30, samedi et dimanche éteints. Une
 * seule source de vérité, `lib/rituel`, qui (re)programme un rappel hebdomadaire
 * par jour actif et qu'un écran comme la future « série » relit comme les jours
 * de travail.
 *
 * 🔑 Les deux seuls types que les libs savent vraiment gérer :
 *   1. le rappel du soir, local, via `lib/rituel` (la semaine et ses heures) ;
 *   2. la reprise d'une leçon partagée, décidée au backend : ici on ne fait que
 *      refléter l'autorisation système et ouvrir la porte quand on la demande.
 * On n'invente pas de troisième bascule pour une notification qui n'existe pas.
 *
 * 🌥️ Une seule Cloudy, en tête, pour poser le ton sans répéter la mascotte.
 */

const textes = t.notifications;

/** `09:00`, et rien d'autre. Même contrôle que le rituel et la semaine type. */
function heureValide(v: string): boolean {
  const m = v.match(/^(\d{2}):(\d{2})$/);
  if (!m) return false;
  return parseInt(m[1], 10) <= 23 && parseInt(m[2], 10) <= 59;
}

/** Force le format pendant la frappe : les deux points se posent tout seuls. */
function formaterHeure(v: string): string {
  const chiffres = v.replace(/[^0-9]/g, '').slice(0, 4);
  if (chiffres.length <= 2) return chiffres;
  return `${chiffres.slice(0, 2)}:${chiffres.slice(2)}`;
}

export default function Notifications() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  // On ne prend du hook que ce qui sert à la reprise de leçon : l'autorisation
  // système et la demande. Le rappel du soir vit dans `lib/rituel`.
  const { autorisation, demanderAutorisation } = useNotifications();

  // La semaine du rappel du soir, lue depuis `lib/rituel` : sept jours, chacun
  // avec son interrupteur et son heure. Même source que la future « série ».
  const [semaine, setSemaine] = useState<JourRituel[]>([]);
  const [ritRefus, setRitRefus] = useState(false);
  // Le jour dont on règle l'heure, et si son champ « Autre » est ouvert. Un seul
  // sélecteur d'heure déplié à la fois, pour garder l'écran calme.
  const [jourEnEdition, setJourEnEdition] = useState<number | null>(null);
  const [persoEnEdition, setPersoEnEdition] = useState(false);

  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);
  // Note affichée sous la reprise quand on tente d'éteindre : on ne peut pas
  // révoquer l'autorisation depuis l'app, on renvoie aux réglages système.
  const [repriseNote, setRepriseNote] = useState<string | null>(null);

  // Au montage : on lit la semaine et l'autorisation courante. Si les
  // notifications sont déjà autorisées, on réconcilie la réalité avec
  // l'intention (on reprogramme la semaine posée) pour que ce qui est stocké
  // sonne vraiment, sans surprendre par une pop-up de permission.
  useEffect(() => {
    let vivant = true;
    (async () => {
      const sem = await lireSemaineRituel();
      if (!vivant) return;
      const perm = await permissionRituel();
      if (!vivant) return;
      setRitRefus(perm === 'refusee');
      if (perm === 'accordee' && sem.some((j) => j.actif)) {
        const posee = await definirSemaineRituel(sem);
        if (vivant) setSemaine(posee);
      } else {
        setSemaine(sem);
      }
    })();
    return () => {
      vivant = false;
    };
  }, []);

  const master = semaine.some((j) => j.actif);
  const joursTries = useMemo(() => [...semaine].sort((a, b) => a.jour - b.jour), [semaine]);

  /** Applique une nouvelle semaine : (re)programme les rappels et met l'écran à jour. */
  async function appliquer(voulu: JourRituel[]) {
    setErreur(null);
    setOccupe(true);
    try {
      const posee = await definirSemaineRituel(voulu);
      setSemaine(posee);
    } catch {
      setErreur(textes.erreur);
    } finally {
      setOccupe(false);
    }
  }

  // L'interrupteur maître ouvre ou ferme toute la section. À l'ouverture,
  // l'autorisation d'abord : sans elle, on ne programme rien et il reste éteint.
  // On (ré)active alors les jours ouvrés par défaut. À la fermeture, on éteint
  // tout, mais on garde les heures pour la prochaine fois.
  async function basculerMaster(vers: boolean) {
    setErreur(null);
    if (!vers) {
      setJourEnEdition(null);
      setOccupe(true);
      try {
        const eteinte = await desactiverSemaineRituel();
        setSemaine(eteinte);
      } catch {
        setErreur(textes.erreur);
      } finally {
        setOccupe(false);
      }
      return;
    }
    setOccupe(true);
    try {
      const ok = await demanderPermissionRituel();
      setRitRefus(!ok);
      if (!ok) return;
      // On rallume les jours ouvrés (lundi→vendredi) en gardant leurs heures.
      const voulu = semaine.map((j) => ({ ...j, actif: j.jour <= 4 }));
      const posee = await definirSemaineRituel(voulu);
      setSemaine(posee);
    } catch {
      setErreur(textes.erreur);
    } finally {
      setOccupe(false);
    }
  }

  // Allumer ou éteindre un seul jour. À l'allumage, l'autorisation d'abord.
  async function basculerJour(jour: number, vers: boolean) {
    setErreur(null);
    if (vers) {
      setOccupe(true);
      try {
        const ok = await demanderPermissionRituel();
        setRitRefus(!ok);
        if (!ok) return;
      } catch {
        setErreur(textes.erreur);
        setOccupe(false);
        return;
      } finally {
        setOccupe(false);
      }
    } else if (jourEnEdition === jour) {
      setJourEnEdition(null);
    }
    await appliquer(semaine.map((j) => (j.jour === jour ? { ...j, actif: vers } : j)));
  }

  // Régler l'heure d'un jour. Si l'heure est bancale (frappe en cours dans
  // « Autre »), on la retient sans reprogrammer ; sinon on reprogramme aussitôt.
  async function changerHeure(jour: number, h: string) {
    if (!heureValide(h)) {
      setSemaine((s) => s.map((j) => (j.jour === jour ? { ...j, heure: h } : j)));
      return;
    }
    await appliquer(semaine.map((j) => (j.jour === jour ? { ...j, heure: h } : j)));
  }

  /** Ouvre (ou referme) le sélecteur d'heure d'un jour, en repérant si son heure est « personnalisée ». */
  function ouvrirEdition(jour: number, heure: string) {
    if (jourEnEdition === jour) {
      setJourEnEdition(null);
      return;
    }
    setPersoEnEdition(!HEURES_PROPOSEES.includes(heure as (typeof HEURES_PROPOSEES)[number]));
    setJourEnEdition(jour);
  }

  async function basculerReprise(vers: boolean) {
    setRepriseNote(null);
    if (!vers) {
      setRepriseNote(textes.repriseCoupe);
      return;
    }
    setErreur(null);
    setOccupe(true);
    try {
      await demanderAutorisation();
    } catch {
      setErreur(textes.erreur);
    } finally {
      setOccupe(false);
    }
  }

  const repriseAccordee = autorisation === 'accordee';
  const repriseRefusee = autorisation === 'refusee';

  return (
    <SousEcran titre={textes.titre}>
      <Carte>
        <View style={styles.hero}>
          {/* Une seule Cloudy sur l'écran, fixe et décorative : elle pose le ton,
              le lecteur d'écran l'ignore (l'écran a déjà son titre). */}
          <Cloudy pose="salut" taille={72} respire={false} />
          <Text style={styles.intro}>{textes.intro}</Text>
        </View>
      </Carte>

      {/* Type 1 — le rappel du soir, une semaine de sept jours. L'interrupteur
          maître ouvre la section ; dessous, un jour par ligne. */}
      <Carte>
        <View style={styles.ligne}>
          <Text style={styles.titreCarte}>{textes.ritTitre}</Text>
          <Switch
            accessibilityLabel={textes.ritTitre}
            value={master}
            onValueChange={basculerMaster}
            disabled={occupe}
            trackColor={{ false: c.bord, true: c.actif }}
            thumbColor={c.surface}
            ios_backgroundColor={c.bord}
          />
        </View>
        <Text style={styles.aide}>{textes.ritAide}</Text>

        {ritRefus ? <Alerte message={textes.ritRefus} /> : null}

        {/* Les sept jours n'apparaissent que quand la section est ouverte :
            régler des heures pour un rappel éteint n'aurait pas de sens. */}
        {master ? (
          <View style={styles.semaine}>
            {joursTries.map((j) => {
              const nomJour = textes.jours[j.jour];
              const enEdition = jourEnEdition === j.jour;
              return (
                <View key={j.jour} style={styles.jourBloc}>
                  <View style={styles.jourLigne}>
                    <Text style={styles.jourNom}>{nomJour}</Text>
                    {/* L'heure : une pastille tappable quand le jour est actif,
                        un simple libellé grisé sinon. */}
                    {j.actif ? (
                      <Pressable
                        accessibilityRole="button"
                        accessibilityLabel={textes.ritHeurePour(nomJour, j.heure)}
                        accessibilityState={{ expanded: enEdition }}
                        disabled={occupe}
                        onPress={() => ouvrirEdition(j.jour, j.heure)}
                        style={[styles.heurePastille, enEdition && styles.heurePastilleActive]}>
                        <Text style={styles.heureTexte}>{j.heure}</Text>
                      </Pressable>
                    ) : (
                      <Text style={styles.heureMuette}>{j.heure}</Text>
                    )}
                    <Switch
                      accessibilityLabel={textes.ritActiverJour(nomJour)}
                      value={j.actif}
                      onValueChange={(v) => basculerJour(j.jour, v)}
                      disabled={occupe}
                      trackColor={{ false: c.bord, true: c.actif }}
                      thumbColor={c.surface}
                      ios_backgroundColor={c.bord}
                    />
                  </View>

                  {/* Le sélecteur d'heure du jour, déplié sous sa ligne. Un
                      segmenté compact façon interrupteur iOS, plus « Autre ». */}
                  {j.actif && enEdition ? (
                    <View style={styles.editeur}>
                      <View style={styles.segmente}>
                        {HEURES_PROPOSEES.map((h) => {
                          const choisi = !persoEnEdition && j.heure === h;
                          return (
                            <Pressable
                              key={h}
                              accessibilityRole="button"
                              accessibilityLabel={`${nomJour} ${h}`}
                              accessibilityState={{ selected: choisi }}
                              disabled={occupe}
                              onPress={() => {
                                setPersoEnEdition(false);
                                void changerHeure(j.jour, h);
                              }}
                              style={[styles.segment, choisi && styles.segmentActif]}>
                              <Text style={[styles.texteSegment, choisi && styles.texteSegmentActif]}>
                                {h}
                              </Text>
                            </Pressable>
                          );
                        })}
                        <Pressable
                          accessibilityRole="button"
                          accessibilityLabel={t.rituel.personnalise}
                          accessibilityState={{ selected: persoEnEdition }}
                          disabled={occupe}
                          onPress={() => setPersoEnEdition(true)}
                          style={[styles.segment, persoEnEdition && styles.segmentActif]}>
                          <Text
                            style={[
                              styles.texteSegment,
                              persoEnEdition && styles.texteSegmentActif,
                            ]}>
                            {t.rituel.personnalise}
                          </Text>
                        </Pressable>
                      </View>

                      {persoEnEdition ? (
                        <Champ
                          etiquette={t.rituel.heureLibre}
                          value={j.heure}
                          onChangeText={(v) => void changerHeure(j.jour, formaterHeure(v))}
                          placeholder="16:30"
                          keyboardType="number-pad"
                          editable={!occupe}
                        />
                      ) : null}
                    </View>
                  ) : null}
                </View>
              );
            })}
          </View>
        ) : null}
      </Carte>

      {/* Type 2 — la reprise d'une leçon partagée. L'interrupteur reflète
          l'autorisation système : l'allumer la demande, et comme on ne sait pas
          la révoquer depuis l'app, l'éteindre renvoie aux réglages du téléphone. */}
      <Carte>
        <View style={styles.ligne}>
          <Text style={styles.titreCarte}>{textes.repriseTitre}</Text>
          <Switch
            accessibilityLabel={textes.repriseTitre}
            value={repriseAccordee}
            onValueChange={basculerReprise}
            disabled={occupe}
            trackColor={{ false: c.bord, true: c.actif }}
            thumbColor={c.surface}
            ios_backgroundColor={c.bord}
          />
        </View>
        <Text style={styles.aide}>{textes.repriseTexte}</Text>

        {repriseRefusee ? <Alerte message={textes.autorisationRefusee} /> : null}
        {repriseNote ? <Alerte message={repriseNote} /> : null}
      </Carte>

      {erreur ? <Alerte message={erreur} /> : null}
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  hero: { alignItems: 'center', gap: espace.sm },
  intro: {
    fontFamily: police.corps,
    fontSize: 15,
    lineHeight: 22,
    color: c.encreDouce,
    textAlign: 'center',
  },
  ligne: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: espace.md,
  },
  // Le titre partage la ligne avec l'interrupteur : il doit pouvoir aller à la
  // ligne sans pousser l'interrupteur hors de l'écran.
  titreCarte: { flex: 1, fontFamily: police.accent, fontSize: 16, color: c.encre },
  aide: { fontFamily: police.corps, fontSize: 14, lineHeight: 21, color: c.encreDouce },
  // La semaine : les sept jours empilés, séparés d'un souffle.
  semaine: { marginTop: espace.sm, gap: espace.xs },
  jourBloc: { gap: espace.xs },
  jourLigne: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: espace.sm,
    paddingVertical: espace.xs,
  },
  // Le nom du jour prend la place restante ; l'heure et l'interrupteur restent
  // alignés à droite.
  jourNom: { flex: 1, fontFamily: police.accent, fontSize: 15, color: c.encre },
  // L'heure d'un jour actif : une pastille sobre qu'on touche pour la régler.
  heurePastille: {
    borderRadius: rayon.pastille,
    borderWidth: 1,
    borderColor: c.bord,
    backgroundColor: c.fond,
    paddingVertical: espace.xs,
    paddingHorizontal: espace.sm,
  },
  heurePastilleActive: { borderColor: c.actif },
  heureTexte: { fontFamily: police.accent, fontSize: 14, color: c.encre },
  // L'heure d'un jour éteint : visible mais discrète, non tappable.
  heureMuette: {
    fontFamily: police.accent,
    fontSize: 14,
    color: c.encreDouce,
    paddingVertical: espace.xs,
    paddingHorizontal: espace.sm,
    opacity: 0.6,
  },
  editeur: { gap: espace.sm, marginBottom: espace.xs },
  // La piste du segmenté : un bandeau neutre arrondi, un mince liseré, et 3 px
  // de marge intérieure pour que le segment surligné respire.
  segmente: {
    flexDirection: 'row',
    backgroundColor: c.fond,
    borderRadius: rayon.pastille,
    borderWidth: 1,
    borderColor: c.bord,
    padding: 3,
    gap: 3,
  },
  // Chaque option prend la même largeur : `flex: 1` répartit la rangée à parts
  // égales, l'allure « interrupteur » vient de là.
  segment: {
    flex: 1,
    borderRadius: rayon.pastille - 3,
    paddingVertical: espace.sm,
    alignItems: 'center',
    justifyContent: 'center',
  },
  // Le segment choisi se détache en pastille blanche à ombre douce, comme le
  // segmented control d'iOS. Pas d'aplat de couleur : c'est du blanc sur neutre.
  segmentActif: { backgroundColor: c.surface, ...ombre.carte },
  texteSegment: { fontFamily: police.accent, fontSize: 13, color: c.encreDouce },
  texteSegmentActif: { color: c.encre },
});
