import { langue, type Langue } from '@/i18n';

/**
 * La locale de formatage des dates suit la langue de l'interface, pas celle de
 * l'appareil : une prof qui a choisi le français sur un téléphone en anglais
 * veut ses dates en français. Autrement le mois s'afficherait dans une langue
 * que rien d'autre dans l'écran ne parle.
 *
 * `Record<Langue, string>` est volontaire : le jour où une langue s'ajoute au
 * catalogue, `tsc` exigera sa locale ici. C'est un détecteur gratuit, qui ne
 * peut pas passer au vert en oubliant une langue, contrairement à un objet aux
 * clés optionnelles qui laisserait passer le trou en silence.
 */
const LOCALES: Record<Langue, string> = { fr: 'fr-BE', nl: 'nl-BE' };

/** La locale BCP 47 pour formater une date dans la langue courante. */
export const localeDate = (): string => LOCALES[langue] ?? 'fr-BE';
