import AsyncStorage from '@react-native-async-storage/async-storage';

/**
 * Le brouillon d'une leçon EN COURS DE CRÉATION, gardé sur l'appareil.
 *
 * Retour Sophie 24/09 : « comment récupérer une leçon qui est en cours de
 * création et qui disparaît de l'écran sans être créée ? » (appel entrant, app
 * tuée en arrière-plan, retour arrière malheureux). Le formulaire s'écrit ici au
 * fil de la frappe ; à la réouverture de « Une leçon », on propose de reprendre.
 * Effacé dès que la leçon est créée, ou quand la prof le jette.
 *
 * Local à l'appareil et à la classe : c'est un filet de frappe, pas une donnée
 * de compte. Aucun prénom n'y est transformé ni envoyé nulle part.
 */
export type BrouillonLecon = {
  titre: string;
  description: string;
  objectif: string;
  materiel: string;
  organisation: string;
  lieu: string;
  duree: string;
  groupement: string | null;
  canal: string | null;
  /** Horodatage ISO de la dernière frappe. */
  modifie: string;
};

/** Au-delà, un brouillon n'est plus proposé : la leçon n'est plus d'actualité. */
const DUREE_VIE_MS = 14 * 24 * 60 * 60 * 1000;

const cle = (classeId: string) => `educooo:lecon-brouillon:${classeId}`;

export async function ecrireBrouillonLecon(classeId: string, b: BrouillonLecon): Promise<void> {
  try {
    await AsyncStorage.setItem(cle(classeId), JSON.stringify(b));
  } catch {
    // Silencieux : un filet qui échoue ne doit jamais gêner la saisie.
  }
}

export async function lireBrouillonLecon(classeId: string): Promise<BrouillonLecon | null> {
  try {
    const brut = await AsyncStorage.getItem(cle(classeId));
    if (!brut) return null;
    const o = JSON.parse(brut) as Partial<BrouillonLecon>;
    const texte = (v: unknown) => (typeof v === 'string' ? v : '');
    const b: BrouillonLecon = {
      titre: texte(o.titre),
      description: texte(o.description),
      objectif: texte(o.objectif),
      materiel: texte(o.materiel),
      organisation: texte(o.organisation),
      lieu: texte(o.lieu),
      duree: texte(o.duree),
      groupement: typeof o.groupement === 'string' ? o.groupement : null,
      canal: typeof o.canal === 'string' ? o.canal : null,
      modifie: texte(o.modifie),
    };
    if (!b.titre.trim() && !b.description.trim()) return null;
    const age = Date.now() - Date.parse(b.modifie || '');
    if (!Number.isFinite(age) || age > DUREE_VIE_MS) return null;
    return b;
  } catch {
    return null;
  }
}

export async function effacerBrouillonLecon(classeId: string): Promise<void> {
  try {
    await AsyncStorage.removeItem(cle(classeId));
  } catch {
    // Sans gravité.
  }
}
