import { Carte } from '@/components/ecran';
import { Tuile } from '@/components/elements';
import {
  Alerte,
  BoutonSecondaire,
  Champ,
  PaireBoutons,
} from '@/components/formulaire';
import { Onglets } from '@/components/onglets';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import {
  brouillonsDe,
  creerProjet,
  projetsDe,
  type ActiviteListe,
  type Observation,
  type Projet,
} from '@/lib/donnees';
