import { espace, police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Les projets d'une classe.
 *
 * 🔑 Un projet répond à « où j'en suis dans ma séquence sur plusieurs
 * semaines », là où une activité répond à « qu'est-ce que je fais ce matin ».
 * Ce n'est pas la même question, donc ce n'est pas le même objet, et c'est
 * pourquoi il survit à la dissolution de la bibliothèque.
 *
 * ⚠️ **C'est un objet rare**, et l'écran l'assume : 12 projets pour 860
 * activités en base. Il n'a rien à faire dans le flux de création, il vit dans
 * le journal, qui est l'axe du temps. Et le texte de l'écran vide dit
 * explicitement qu'on peut s'en passer, plutôt que de pousser à en créer un.
 *
 * ⚠️ Six colonnes de la table ne sont pas portées, et ce n'est pas un oubli :
 * `global_intentions`, `moment_types`, `time_frame_types`,
 * `target_all_students`, `emoji` et `color`. Sur les 12 projets réels, une
 * seule intention au total, zéro moment, zéro cadre temporel, et `emoji`
 * contient tantôt un chemin de fichier. Porter ça serait porter du vide.
 */

/** `2026-09-15`, et rien d'autre. La colonne est une date, pas du texte. */
function dateValide(v: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(v)) return false;
  const [a, m, j] = v.split('-').map((n) => parseInt(n, 10));
  const d = new Date(a, m - 1, j);
  return d.getFullYear() === a && d.getMonth() === m - 1 && d.getDate() === j;
}

export default function Projets() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const projets = useRequete(() => projetsDe(classeId!), [classeId], { actif: !!classeId });
  const brouillons = useRequete(() => brouillonsDe(classeId!), [classeId], { actif: !!classeId });

  // Deux natures différentes, deux onglets (retour Valentin 24/08) : les
  // brouillons (ce qui est capté mais pas posé) et les projets (les séquences
  // longues), plutôt que deux listes empilées. On ouvre sur les brouillons :
  // c'est ce qu'une prof vient chercher le plus souvent.
  const [sous, setSous] = useState<'brouillons' | 'projets'>('brouillons');
  const [ouvert, setOuvert] = useState(false);
  const [nom, setNom] = useState('');
  const [debut, setDebut] = useState('');
  const [fin, setFin] = useState('');
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  async function creer() {
    if (!classeId) return;
    if ((debut && !dateValide(debut)) || (fin && !dateValide(fin))) {
      setErreur(t.projet.dateInvalide);
      return;
    }
    setErreur(null);
    setOccupe(true);
    try {
      await creerProjet({ classeId, titre: nom, debut: debut || null, fin: fin || null });
      projets.recharger();
      setOuvert(false);
      setNom('');
      setDebut('');
      setFin('');
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.projet.erreurCreation);
    } finally {
      setOccupe(false);
    }
  }

  const liste = projets.donnees ?? [];
  const draftsActivites = brouillons.donnees?.activites ?? [];
  const draftsObservations = brouillons.donnees?.observations ?? [];
  const brouillonsVides = draftsActivites.length === 0 && draftsObservations.length === 0;

  return (
    <SousEcran
      titre={t.projet.titreBrouillons}
      sousTitre={classe?.nom}
      chargement={projets.chargement || brouillons.chargement}>
      <Onglets
        options={[
          { id: 'brouillons' as const, libelle: t.projet.ongletBrouillons },
          { id: 'projets' as const, libelle: t.projet.ongletProjets },
        ]}
        choisi={sous}
        onChoisir={setSous}
      />

      {sous === 'brouillons' ? (
        <>
          {brouillons.erreur ? <Alerte message={t.projet.erreur} /> : null}
          {brouillonsVides ? (
            <Carte>
              <Text style={texte.discret}>{t.projet.brouillonsVide}</Text>
            </Carte>
          ) : (
            <>
              {draftsActivites.map((a) => (
                <LigneActiviteBrouillon key={a.id} activite={a} />
              ))}
              {draftsObservations.map((o) => (
                <LigneObservationBrouillon key={o.id} observation={o} />
              ))}
            </>
          )}
        </>
      ) : (
        <>
          <Carte>
            <Text style={styles.aide}>{t.projet.aide}</Text>
          </Carte>

          {projets.erreur ? <Alerte message={t.projet.erreur} /> : null}
          {erreur ? <Alerte message={erreur} /> : null}

          {liste.length === 0 ? (
            <Carte>
              {/* On dit qu'on peut s'en passer. Un écran vide qui pousse à remplir
                  fabrique des objets que personne ne rouvrira. */}
              <Text style={texte.discret}>{t.projet.aucun}</Text>
            </Carte>
          ) : (
            liste.map((p) => <LigneProjet key={p.id} projet={p} />)
          )}

          {!ouvert ? (
            <BoutonSecondaire libelle={t.projet.ajouter} onPress={() => setOuvert(true)} />
          ) : (
            <Carte>
              <Champ
                etiquette={t.projet.nom}
                value={nom}
                onChangeText={setNom}
                placeholder={t.projet.nomIndice}
                editable={!occupe}
              />
              <Champ
                etiquette={t.projet.debut}
                value={debut}
                onChangeText={setDebut}
                placeholder={t.projet.dateIndice}
                editable={!occupe}
              />
              <Champ
                etiquette={t.projet.fin}
                value={fin}
                onChangeText={setFin}
                placeholder={t.projet.dateIndice}
                editable={!occupe}
              />
              <PaireBoutons
                principal={{ libelle: t.projet.creer, onPress: creer, occupe, inactif: !nom.trim() }}
                secondaire={{ libelle: t.commun.annuler, onPress: () => setOuvert(false) }}
              />
            </Carte>
          )}
        </>
      )}
    </SousEcran>
  );
}

/** Une activité encore en brouillon (draft/unplanned) : saisie, pas encore posée. */
function LigneActiviteBrouillon({ activite }: { activite: ActiviteListe }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const detail = [activite.type === 'workshop' ? t.activite.atelier : null, t.activite.sansDate]
    .filter(Boolean)
    .join(' · ');

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${activite.titre}, ${detail}`}
      onPress={() => router.push({ pathname: '/activite/[id]', params: { id: activite.id } })}>
      <Carte compacte>
        <View style={styles.ligne}>
          {/* Gris tant que ce n'est pas posé : la couleur (le vert du fait)
              n'arrive que plus tard, comme dans le journal. */}
          <Tuile icone="edit-3" />
          <View style={styles.corps}>
            <Text style={texte.corps}>{activite.titre}</Text>
            <Text style={texte.discret}>{detail}</Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>
    </Pressable>
  );
}

/** Une observation encore à ranger (pending) : captée, pas encore rattachée. */
function LigneObservationBrouillon({ observation }: { observation: Observation }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={observation.texte}
      onPress={() => router.push({ pathname: '/ranger/[id]', params: { id: observation.id } })}>
      <Carte compacte>
        <View style={styles.ligne}>
          <Tuile icone="edit-3" />
          <View style={styles.corps}>
            <Text style={texte.corps}>{observation.texte}</Text>
            <Text style={texte.discret}>{t.etat.nonRattache}</Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>
    </Pressable>
  );
}

function LigneProjet({ projet }: { projet: Projet }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const periode = t.projet.periode(projet.debut, projet.fin);
  const detail = [t.projet.etats[projet.statut], t.projet.avancement(projet.faites, projet.activites), periode]
    .filter(Boolean)
    .join(' · ');

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${projet.titre}, ${detail}`}
      onPress={() => router.push({ pathname: '/projet/[id]', params: { id: projet.id } })}>
      <Carte compacte>
        <View style={styles.ligne}>
          {/* Vert quand tout est fait, jaune quand c'est en cours, gris tant
              qu'il n'y a rien : la couleur dit l'avancement, jamais de rouge. */}
          {projet.activites > 0 && projet.faites === projet.activites ? (
            <Tuile icone="check" moment="recreation" />
          ) : projet.activites > 0 ? (
            <Tuile icone="folder" moment="ateliers" />
          ) : (
            <Tuile icone="folder" />
          )}
          <View style={styles.corps}>
            <Text style={texte.corps}>{projet.titre}</Text>
            <Text style={texte.discret}>{detail}</Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>
    </Pressable>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  aide: { fontFamily: police.corps, fontSize: 14, color: c.encreDouce },
  section: { fontFamily: police.titre, fontSize: 18, color: c.encre, marginTop: espace.sm },
  ligne: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
  corps: { flex: 1, gap: espace.xs },
});
