import { Feather } from '@expo/vector-icons';
import { type Href, router, useFocusEffect } from 'expo-router';
import { useCallback, useMemo, useState } from 'react';
import { ActivityIndicator, Modal, Pressable, StyleSheet, Text, View } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { BoutonModeAide } from '@/components/aide';
import { AvatarNav } from '@/components/avatar';
import { BoiteReception } from '@/components/boite-reception';
import { CoachMark } from '@/components/coachmark';
import { Cloudy, type Pose } from '@/components/cloudy';
import { BoutonRond, Carte, Ecran } from '@/components/ecran';
import { Anneau, type Moment, Tuile } from '@/components/elements';
import { Alerte, BoutonPrincipal, BoutonSecondaire } from '@/components/formulaire';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { motDeCloudy } from '@/lib/compagnon';
import { NAV_AVATAR } from '@/lib/flags';
import { couvertureDe, observationsDe, premiersPas, SEUIL_RESISTE, type PremiersPas } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, ombre, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Le pilotage répond à une seule question : où en est mon programme ?
 *
 * C'est le tableau de bord de l'enseignante. On y découpe chaque compétence en
 * plan d'action concret — ce qui est acquis, ce qui reste, ce qui résiste — et
 * l'on part d'une compétence pour que Cloudy écrive la leçon. C'est le sens que
 * l'inspection demande : partir des compétences et non de l'activité. L'axe du
 * programme vit ici, l'axe du calendrier dans le journal.
 *
 * 🎨 En-tête au langage du témoin v9 : Cloudy (randonneuse à la carte, on
 * s'oriente), le sélecteur de classe juste à droite du titre (on bascule
 * souvent), la boîte de réception à droite (ce qui attend un geste). « Ma
 * classe » et « à ranger » ne sont plus des cartes du corps : la classe est le
 * sélecteur, l'à-ranger est la boîte.
 *
 * 🔑 Les trois tuiles de « Ta semaine » sont le SÉLECTIONNEUR du programme : un
 * tap change la liste juste en dessous. Le programme entier et l'arc de l'année
 * remontent AU-DESSUS de la carte héro (retour Valentin 24/08) : le chiffre
 * avant le tableau.
 */

/** Les trois états du programme, dans l'ordre du parcours d'une compétence. */
type Etat = 'aborder' | 'consolider' | 'valider';

export default function Accueil() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const observations = useRequete(() => observationsDe(classeId!, 100), [classeId], {
    actif: !!classeId,
  });
  const couverture = useRequete(() => couvertureDe(classe!), [classe?.id, classe?.cycle], {
    actif: !!classe,
  });
  // Les trois premiers pas de la classe : leçon, capture, clôture. Alimente la
  // petite carte d'activation. Fail-open : sur erreur, `donnees` reste indéfini
  // et la carte ne s'affiche pas, jamais un blocage de l'écran.
  const pas = useRequete(() => premiersPas(classeId!), [classeId], { actif: !!classeId });

  // 🚨 On recharge quand l'écran reprend le focus. Sans ça, capter une note dans
  // l'onglet Capter ne rafraîchit jamais ce compte-ci : le pilotage affichait « 6 »
  // pendant que le rituel du soir (qui, lui, recharge) montrait « 7 ». Le même
  // filet que dans soir.tsx, pour que les deux disent le même nombre.
  useFocusEffect(
    useCallback(() => {
      if (classeId) {
        observations.recharger();
        couverture.recharger();
        pas.recharger();
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId]),
  );

  const aRanger = (observations.donnees ?? []).filter((o) => o.statut === 'pending').length;

  const bilan = useMemo(() => {
    // Les compétences DÉLÉGUÉES à un·e collègue (immersion) restent dans la
    // couverture pour les vues élève/programme, mais elles ne sont pas à moi :
    // elles ne comptent ni dans « à aborder », ni dans « travaillées », ni dans
    // ce qui « résiste ». On les écarte du bilan d'un seul coup ici.
    const liste = (couverture.donnees ?? []).filter((c) => !c.delegue);
    if (!liste.length) return null;
    // Une compétence « résiste » quand elle a été travaillée plusieurs fois et
    // qu'une minorité d'élèves seulement l'a acquise. Sans élève évalué, on ne
    // conclut rien : non évaluée n'est pas non acquise.
    const resiste = liste
      .filter((c) => c.seances >= SEUIL_RESISTE && c.evalues > 0 && c.acquis / c.evalues < 0.5)
      .sort((a, b) => b.seances - a.seances);
    // Travaillée mais jamais évaluée : elle ne résiste pas, on n'en sait rien.
    // Ne pas confondre les deux est une demande explicite d'Anne-Charlotte.
    const pasEvalue = liste
      .filter((c) => c.seances > 0 && c.evalues === 0)
      .sort((a, b) => b.seances - a.seances);
    // Pas encore abordée : aucune séance. C'est vers là que part « écris-moi une
    // leçon » quand on veut démarrer une compétence neuve.
    const jamaisListe = liste.filter((c) => c.seances === 0);
    return {
      total: liste.length,
      travaillees: liste.length - jamaisListe.length,
      resiste,
      pasEvalue,
      jamaisListe,
      jamais: jamaisListe.length,
    };
  }, [couverture.donnees]);

  // L'état sélectionné dans les tuiles. On part sur ce qui appelle le plus une
  // action : ce qui résiste, sinon ce qui attend une évaluation, sinon ce qui
  // reste à aborder. Jamais un écran vide au premier regard s'il y a mieux à
  // montrer.
  const defautEtat: Etat = useMemo(() => {
    if (!bilan) return 'consolider';
    if (bilan.resiste.length > 0) return 'consolider';
    if (bilan.pasEvalue.length > 0) return 'valider';
    return 'aborder';
  }, [bilan]);
  const [etatChoisi, setEtatChoisi] = useState<Etat | null>(null);
  const etat = etatChoisi ?? defautEtat;

  /**
   * Le mot de Cloudy compagnon. On ne le calcule que sur des données déjà
   * chargées, jamais pendant le chargement, et jamais sur une année passée : le
   * bandeau « année passée » parle déjà, et « range ta journée » n'a pas de sens
   * dans une classe de juin. `null` = pas de carte, jamais de nudge fabriqué.
   */
  const mot = useMemo(() => {
    if (!classe || classe.archivee || observations.chargement) return null;
    const obs = observations.donnees ?? [];
    return motDeCloudy({
      heure: new Date().getHours(),
      aRanger,
      resiste: bilan?.resiste.length ?? 0,
      capteAujourdhui: obs.some((o) => estAujourdhui(o.creeLe)),
      capteCetteSemaine: obs.some((o) => estCetteSemaine(o.creeLe)),
    });
  }, [classe, observations.chargement, observations.donnees, aRanger, bilan]);

  // Les trois pas faits ? La carte d'activation s'efface alors entièrement : une
  // fois l'app prise en main, elle n'a plus rien à dire et cède la place.
  const tousLesPas =
    !!pas.donnees &&
    pas.donnees.eleve &&
    pas.donnees.lecon &&
    pas.donnees.capture &&
    pas.donnees.cloture;

  return (
    // Une seule Cloudy par écran, règle de la charte : quand le mot de Cloudy
    // s'affiche, il PORTE la mascotte, donc l'avatar d'en-tête s'efface. Sans
    // mot, l'avatar d'en-tête est la randonneuse (on s'oriente dans son programme).
    <Ecran
      titre={t.accueil.titre}
      avatarMenu={NAV_AVATAR ? <AvatarNav /> : undefined}
      selecteurClasse
      actions={
        <>
          {/* Le « ? » global : allume/éteint le mode aide pour toute l'app.
              Invisible tant que le drapeau maître AIDE_ACTIVE est éteint. */}
          <BoutonModeAide />
          <BoiteReception classeId={classeId} />
          {/* Accès aux élèves : l'icône remplace la carte « ma classe » retirée,
              à droite de la boîte de réception (retour Valentin 24/08). */}
          {classe ? (
            <BoutonRond
              icone="users"
              libelle={t.accueil.maClasse}
              onPress={() => router.push('/classe')}
            />
          ) : null}
        </>
      }>
      {/* 🚨 Avant tout le reste : dire qu'on n'est pas dans l'année en cours.
          Une année passée s'affiche sinon exactement comme l'année en cours,
          avec le même bouton pour capter. */}
      {classe?.archivee ? (
        <Carte>
          <Text style={texte.corps}>{t.accueil.anneePassee(classe.nom)}</Text>
          <Text style={texte.discret}>{t.accueil.anneePasseeAide}</Text>
        </Carte>
      ) : null}

      {/* Le mot de Cloudy, tout en haut, seulement quand il y a un état réel à
          dire. Avec une action, la carte entière est tactile et mène au geste. */}
      {mot ? (
        <Carte onPress={mot.action ? () => router.push(mot.action!.route) : undefined}>
          <View style={styles.mot}>
            <Cloudy pose={mot.pose} taille={64} anime />
            <View style={styles.motCorps}>
              <Text style={texte.corps}>{mot.message}</Text>
              {mot.action ? <Text style={styles.motAction}>{mot.action.libelle}</Text> : null}
            </View>
            {mot.action ? (
              <Feather name="chevron-right" size={20} color={c.nonRattache} />
            ) : null}
          </View>
        </Carte>
      ) : null}

      {/* Le mot d'aide du pilotage, une seule fois : la vision du menu. On ne le
          montre pas sur une année passée. */}
      {classe && !classe.archivee ? (
        <CoachMark id="pilotage" message={t.coach.pilotage} pose="loupe" />
      ) : null}

      {/* Les premiers pas : trois gestes concrets pour prendre l'app en main. La
          carte disparaît d'elle-même dès que les trois sont faits, et ne
          s'affiche pas sur une année passée. Encourageante, jamais un reproche.
          (Le tour « Prends l'app en main » se lance seul à la session, il ne vit
          plus en carte ici.) */}
      {classe && !classe.archivee && pas.donnees && !tousLesPas ? (
        <CartePremiersPas pas={pas.donnees} />
      ) : null}

      {couverture.erreur ? <Alerte message={t.accueil.couvertureVide} /> : null}

      {couverture.chargement && !bilan ? (
        <View style={styles.attente}>
          <ActivityIndicator color={c.encreDouce} />
        </View>
      ) : null}

      {bilan ? (
        <>
          {/* Le programme entier et l'arc de l'année ne mènent quelque part
              qu'avec des données : on ne les montre qu'une fois qu'au moins une
              compétence a été travaillée. */}
          {bilan.travaillees > 0 ? (
            <>
              {/* Le programme entier, remonté AU-DESSUS de « ta semaine » (retour
                  Valentin 24/08) : le chiffre avant le tableau. */}
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={t.competences.ouvrirTout}
                onPress={() => router.push('/competences')}>
                <Carte compacte>
                  <View style={styles.ligne}>
                    <Tuile icone="book" moment="dirigees" />
                    <View style={styles.corps}>
                      <Text style={texte.corps}>{t.competences.ouvrirTout}</Text>
                      <Text style={texte.discret} numberOfLines={1}>
                        {t.competences.bilan(bilan.travaillees, bilan.total)}
                      </Text>
                    </View>
                    <Feather name="chevron-right" size={20} color={c.nonRattache} />
                  </View>
                </Carte>
              </Pressable>

              {/* L'arc de l'année, juste au-dessus de « ta semaine ». La couverture
                  dit « où j'en suis cette semaine » ; l'année dit « comment ça
                  s'écrit depuis la rentrée ». */}
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={t.accueil.voirAnnee}
                onPress={() => router.push('/annee')}>
                <Carte compacte>
                  <View style={styles.ligne}>
                    <Tuile icone="trending-up" moment="dirigees" />
                    <View style={styles.corps}>
                      <Text style={texte.corps}>{t.accueil.voirAnnee}</Text>
                      <Text style={texte.discret} numberOfLines={1}>
                        {t.accueil.voirAnneeIndice}
                      </Text>
                    </View>
                    <Feather name="chevron-right" size={20} color={c.nonRattache} />
                  </View>
                </Carte>
              </Pressable>
            </>
          ) : null}

          {/* La carte héro : l'anneau de couverture et les trois tuiles-sélecteur.
              La pièce maîtresse de l'écran. Affichée MÊME À ZÉRO (retour Valentin
              24/08) : l'anneau à 0 % et une phrase de bénéfice valent mieux qu'un
              bloc caché. */}
          <Carte>
            <View style={styles.heroRangee}>
              <Anneau valeur={bilan.total > 0 ? bilan.travaillees / bilan.total : 0} />
              <View style={styles.heroTexte}>
                <Text style={texte.section}>{t.accueil.hero}</Text>
                <Text style={texte.discret}>
                  {bilan.travaillees > 0 ? t.accueil.heroSousTitre(bilan.jamais) : t.accueil.heroVide}
                </Text>
              </View>
            </View>
            <TuilesSelecteur
              choisi={etat}
              onChoisir={setEtatChoisi}
              items={[
                { id: 'aborder', valeur: bilan.jamais, libelle: t.accueil.selecteurAborder, moment: 'accueil' },
                { id: 'consolider', valeur: bilan.resiste.length, libelle: t.accueil.selecteurConsolider, moment: 'ateliers' },
                { id: 'valider', valeur: bilan.pasEvalue.length, libelle: t.accueil.selecteurValider, moment: 'dirigees' },
              ]}
            />
          </Carte>

          {/* La liste de l'état choisi, juste sous le sélectionneur. Une seule
              catégorie à la fois : plus de trois sections à scroller. */}
          <EtatChoisi etat={etat} bilan={bilan} />
        </>
      ) : null}
    </Ecran>
  );
}

/**
 * La carte « Premiers pas » : trois gestes pour prendre l'app en main, chacun
 * cochable en le faisant. Chaque ligne mène droit à l'action. Le ton est
 * encourageant, jamais culpabilisant : un pas non fait est une porte ouverte,
 * pas un retard. La carte ne s'affiche que tant qu'un pas manque (voir l'appelant).
 */
type CleePas = 'semaine' | 'classe' | 'eleve' | 'importe' | 'lecon' | 'capture' | 'cloture';

type Pas = {
  cle: CleePas;
  fait: boolean;
  libelle: string;
  route: Href;
  icone: keyof typeof import('@expo/vector-icons').Feather.glyphMap;
  pose: Pose;
};

function CartePremiersPas({ pas }: { pas: PremiersPas }) {
  const texte = useTexte();
  // Un pas ouvert dans sa fenêtre d'explication (fond ombré), ou aucun.
  const [ouvert, setOuvert] = useState<Pas | null>(null);
  // L'ordre voulu (retour Valentin 24/08), du socle vers la boucle : semaine,
  // classe, import, leçon de zéro, capture, clôture. `classe` est toujours fait
  // ici (on n'affiche les premiers pas que sur une classe qui existe), mais on
  // le montre coché pour donner le fil complet.
  const items: Pas[] = [
    { cle: 'semaine', fait: pas.semaine, libelle: t.coach.premiersPasSemaine, route: '/vous/semaine', icone: 'clock', pose: 'neutre' },
    { cle: 'classe', fait: pas.classe, libelle: t.coach.premiersPasClasse, route: '/vous/classes', icone: 'users', pose: 'salut' },
    { cle: 'eleve', fait: pas.eleve, libelle: t.coach.premiersPasEleve, route: '/classe', icone: 'user-plus', pose: 'salut' },
    { cle: 'importe', fait: pas.importe, libelle: t.coach.premiersPasImport, route: '/activite/nouvelle', icone: 'file-plus', pose: 'loupe' },
    { cle: 'lecon', fait: pas.lecon, libelle: t.coach.premiersPasLecon, route: '/activite/nouvelle', icone: 'book', pose: 'joie' },
    { cle: 'capture', fait: pas.capture, libelle: t.coach.premiersPasCapture, route: '/capter', icone: 'edit-3', pose: 'micro' },
    { cle: 'cloture', fait: pas.cloture, libelle: t.coach.premiersPasCloture, route: '/journal', icone: 'check-circle', pose: 'celebration' },
  ];
  const restants = items.filter((it) => !it.fait).length;
  return (
    <Carte>
      <Text style={texte.section}>{t.coach.premiersPasTitre}</Text>
      <Text style={texte.discret}>{t.coach.premiersPasIndice(restants)}</Text>
      {items.map((it) => (
        <PasLigne key={it.cle} pas={it} onOuvrir={() => setOuvert(it)} />
      ))}
      {ouvert ? <FenetrePas pas={ouvert} onFermer={() => setOuvert(null)} /> : null}
    </Carte>
  );
}

/** Une ligne de premier pas : une coche, un libellé, un geste. Fait = coche verte. */
function PasLigne({ pas, onOuvrir }: { pas: Pas; onOuvrir: () => void }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityState={{ checked: pas.fait }}
      accessibilityLabel={pas.libelle}
      onPress={onOuvrir}
      style={styles.pasLigne}>
      <View style={[styles.pasCoche, pas.fait && styles.pasCocheFaite]}>
        <Feather name={pas.fait ? 'check' : pas.icone} size={14} color={pas.fait ? c.surface : c.nonRattache} />
      </View>
      <Text style={[styles.pasLibelle, pas.fait && styles.pasLibelleFait]} numberOfLines={1}>
        {pas.libelle}
      </Text>
      <Feather name="chevron-right" size={20} color={c.nonRattache} />
    </Pressable>
  );
}

/**
 * La fenêtre d'explication d'un pas (retour Valentin 24/08) : fond ombré,
 * fenêtre claire, Cloudy, le comment concret et le bénéfice, puis « Y aller »
 * (qui emmène faire le pas) ou « J'ai compris » (qui referme).
 */
function FenetrePas({ pas, onFermer }: { pas: Pas; onFermer: () => void }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const expli = t.coach.premiersPasExpli[pas.cle];
  return (
    <Modal visible transparent animationType="fade" onRequestClose={onFermer}>
      <SafeAreaView style={styles.expliFond} edges={['top', 'bottom']}>
        <View style={styles.expliFenetre}>
          <Cloudy pose={pas.pose} taille={96} anime />
          <Text style={styles.expliTitre}>{expli.titre}</Text>
          <Text style={styles.expliCorps}>{expli.corps}</Text>
          <View style={styles.expliBoutons}>
            <BoutonPrincipal
              libelle={t.coach.premiersPasAller}
              onPress={() => {
                onFermer();
                router.push(pas.route);
              }}
            />
            <BoutonSecondaire libelle={t.coach.compris} onPress={onFermer} />
          </View>
        </View>
      </SafeAreaView>
    </Modal>
  );
}

/**
 * Les trois tuiles teintées, devenues sélectionneur. La tuile choisie s'entoure
 * d'un liseré d'encre : on voit d'un coup laquelle commande la liste en dessous.
 */
function TuilesSelecteur({
  items,
  choisi,
  onChoisir,
}: {
  items: { id: Etat; valeur: number; libelle: string; moment: Moment }[];
  choisi: Etat;
  onChoisir: (id: Etat) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.tuiles}>
      {items.map((it) => {
        const actif = it.id === choisi;
        return (
          <Pressable
            key={it.id}
            accessibilityRole="tab"
            accessibilityState={{ selected: actif }}
            accessibilityLabel={`${it.libelle}, ${it.valeur}`}
            onPress={() => onChoisir(it.id)}
            style={[
              styles.tuileStat,
              { backgroundColor: c.teinte[it.moment] },
              actif && styles.tuileStatActive,
            ]}>
            <Text style={styles.tuileStatValeur}>{it.valeur}</Text>
            <Text style={styles.tuileStatLibelle}>{it.libelle}</Text>
          </Pressable>
        );
      })}
    </View>
  );
}

/**
 * La liste de l'état sélectionné : une intro courte, puis jusqu'à trois
 * compétences avec leur geste. Vide, on le dit sans reproche.
 */
function EtatChoisi({
  etat,
  bilan,
}: {
  etat: Etat;
  bilan: {
    resiste: { competenceId: string; competence: string; seances: number; acquis: number; evalues: number }[];
    pasEvalue: { competenceId: string; competence: string; seances: number }[];
    jamaisListe: { competenceId: string; competence: string }[];
    total: number;
  };
}) {
  const texte = useTexte();

  if (etat === 'consolider') {
    if (bilan.resiste.length === 0) return <CarteVide message={t.accueil.consoliderVide} />;
    return (
      <>
        <Carte compacte>
          <Text style={texte.discret}>{t.accueil.resisteIndice(bilan.resiste.length)}</Text>
        </Carte>
        {bilan.resiste.slice(0, 3).map((c) => (
          <LigneCompetence
            key={c.competenceId}
            competenceId={c.competenceId}
            competence={c.competence}
            detail={t.accueil.resisteDetail(c.seances, c.acquis, c.evalues)}
            icone="alert-circle"
            moment="ateliers"
            resiste={{ seances: c.seances, acquis: c.acquis, evalues: c.evalues }}
          />
        ))}
      </>
    );
  }

  if (etat === 'valider') {
    if (bilan.pasEvalue.length === 0) return <CarteVide message={t.accueil.validerVide} />;
    return (
      <>
        <Carte compacte>
          <Text style={texte.discret}>{t.accueil.pasEvalueIndice(bilan.pasEvalue.length)}</Text>
        </Carte>
        {bilan.pasEvalue.slice(0, 3).map((c) => (
          <LigneCompetence
            key={c.competenceId}
            competenceId={c.competenceId}
            competence={c.competence}
            detail={t.accueil.pasEvalueDetail(c.seances)}
            icone="help-circle"
            moment={null}
          />
        ))}
      </>
    );
  }

  // aborder
  if (bilan.jamaisListe.length === 0) return <CarteVide message={t.accueil.aborderVide} />;
  return (
    <>
      <Carte compacte>
        <Text style={texte.discret}>{t.accueil.jamaisIndice(bilan.jamaisListe.length, bilan.total)}</Text>
      </Carte>
      {bilan.jamaisListe.slice(0, 3).map((c) => (
        <LigneCompetence
          key={c.competenceId}
          competenceId={c.competenceId}
          competence={c.competence}
          detail={t.accueil.aborderDetail}
          icone="circle"
          moment="accueil"
        />
      ))}
    </>
  );
}

/** Un état vide : une seule carte, un mot calme, pas un silence brut. */
function CarteVide({ message }: { message: string }) {
  const texte = useTexte();
  return (
    <Carte compacte>
      <Text style={texte.discret}>{message}</Text>
    </Carte>
  );
}

/**
 * Une compétence de la couverture, et le geste qu'elle permet.
 *
 * 🔑 C'est ici que « partir de la compétence » entre dans la navigation, et
 * c'est le sens que l'inspection demande. On part de ce qui résiste, on arrive
 * sur une activité dont les attendus sont déjà cochés.
 */
function LigneCompetence({
  competenceId,
  competence,
  detail,
  icone,
  moment,
  resiste,
}: {
  competenceId: string;
  competence: string;
  detail: string;
  icone: keyof typeof import('@expo/vector-icons').Feather.glyphMap;
  /** Le moment donne la teinte. `null` = gris, « pas encore », pas un échec. */
  moment: Moment | null;
  /** Fourni quand la compétence résiste : on part alors écrire une autre approche. */
  resiste?: { seances: number; acquis: number; evalues: number };
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const action = resiste ? t.accueil.autrement : t.lecon.generer;
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${competence}, ${detail}, ${action}`}
      onPress={() =>
        router.push({
          pathname: '/lecon/[competence]',
          params: {
            competence: competenceId,
            nom: competence,
            ...(resiste
              ? {
                  seances: String(resiste.seances),
                  acquis: String(resiste.acquis),
                  evalues: String(resiste.evalues),
                }
              : {}),
          },
        })
      }>
      <Carte compacte>
        <View style={styles.ligne}>
          {moment ? (
            <Tuile icone={icone} moment={moment} />
          ) : (
            <Tuile icone={icone} />
          )}
          <View style={styles.corps}>
            <Text style={texte.corps}>{competence}</Text>
            <Text style={texte.discret}>{detail}</Text>
            <Text style={styles.action} numberOfLines={1}>
              {action}
            </Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>
    </Pressable>
  );
}

/** Vrai si une date ISO tombe aujourd'hui, en heure locale. */
function estAujourdhui(iso: string): boolean {
  const d = new Date(iso);
  const n = new Date();
  return (
    d.getFullYear() === n.getFullYear() &&
    d.getMonth() === n.getMonth() &&
    d.getDate() === n.getDate()
  );
}

/** Vrai si une date ISO tombe dans la semaine courante (lundi à dimanche), en local. */
function estCetteSemaine(iso: string): boolean {
  const d = new Date(iso);
  const lundi = new Date();
  lundi.setHours(0, 0, 0, 0);
  // getDay() : 0 = dimanche. On ramène au lundi de la semaine (ISO).
  const jour = lundi.getDay() === 0 ? 7 : lundi.getDay();
  lundi.setDate(lundi.getDate() - (jour - 1));
  const lundiSuivant = new Date(lundi);
  lundiSuivant.setDate(lundi.getDate() + 7);
  return d >= lundi && d < lundiSuivant;
}

