import Constants from 'expo-constants';
import { createContext, useContext, useEffect, useMemo, type ReactNode } from 'react';
import PostHog, { PostHogProvider } from 'posthog-react-native';
import * as Sentry from '@sentry/react-native';

import { useMoi } from './session';

/**
 * L'observabilité de l'app, en un seul endroit : Sentry pour les crashs et
 * erreurs, PostHog pour l'usage. Les deux suivent EXACTEMENT le même contrat
 * que RevenueCat (voir `abonnement.tsx`) : ils ne sont JAMAIS obligatoires au
 * fonctionnement. Si leur clé manque, l'intégration reste INERTE et l'app tourne
 * sans elle, sans planter et sans bruit.
 *
 * 🔒 RGPD, la contrainte qui gouverne tout ce fichier. EducooO capte des
 * observations sur de jeunes enfants (prénoms, comportements). Rien de tout cela
 * ne doit fuiter vers un outil d'analytics ou de crash. Concrètement :
 *   - PostHog est hébergé en Union européenne (host `eu.i.posthog.com`).
 *   - On DÉSACTIVE l'autocapture des interactions (`captureTouches`), la seule
 *     voie par laquelle du texte saisi ou des libellés d'écran pourraient partir.
 *   - On n'active JAMAIS le session replay (il filmerait le contenu des écrans).
 *   - Sentry ne joint pas les données personnelles par défaut (`sendDefaultPii`).
 *   - On n'envoie que des événements NOMMÉS par nous, avec des propriétés qu'on
 *     choisit une par une. Jamais le contenu d'une observation, jamais un prénom.
 */

// Les clés arrivent par Doppler, résolues dans le bloc `extra` de app.config.ts,
// exactement comme Supabase et RevenueCat. On les lit ici directement plutôt que
// via `env.ts` pour ne pas toucher un fichier partagé, mais le pattern est le
// même : une clé absente n'est pas une erreur, elle neutralise l'intégration.
type Extra = {
  sentryDsn?: string;
  posthogKey?: string;
  posthogHost?: string;
};
const extra = (Constants.expoConfig?.extra ?? {}) as Extra;

// EU par défaut : le host n'a pas à être configuré pour rester conforme. On ne
// bascule sur un autre que si Doppler en fournit un explicitement.
const POSTHOG_HOST_DEFAUT = 'https://eu.i.posthog.com';

// ── Sentry ──────────────────────────────────────────────────────────────────

// Vrai une fois `Sentry.init` appelé. C'est un effet de bord global du process,
// pas un état React : il ne doit avoir lieu qu'une fois, et il conditionne
// `signalerErreur`. On l'initialise au chargement du module (donc très tôt,
// avant le premier écran) plutôt que dans un effet, pour attraper aussi les
// erreurs qui surviennent pendant le montage de l'arbre.
export const sentryDisponible = !!extra.sentryDsn;

if (sentryDisponible) {
  Sentry.init({
    dsn: extra.sentryDsn,
    // En prod, jamais de logs verbeux : ils encombrent la console et exposent
    // des détails d'implémentation. En dev non plus, on n'en a pas besoin.
    debug: false,
    // On distingue les erreurs de dev de celles des vraies utilisatrices, pour
    // ne pas polluer le tableau de bord avec nos propres essais.
    environment: __DEV__ ? 'development' : 'production',
    // Le tracing de performance est bruyant et coûteux : quasi nul en dev,
    // échantillonné en prod. On observe d'abord les crashs, pas la latence.
    tracesSampleRate: __DEV__ ? 0 : 0.2,
    // 🔒 RGPD : on n'attache PAS les données personnelles par défaut (IP,
    // identité de l'appareil). L'identité qu'on relie plus bas est le seul ID
    // Supabase de l'enseignant·e, jamais celle d'un enfant.
    sendDefaultPii: false,
  });
}

/**
 * Signale une erreur rattrapée à Sentry, avec un contexte optionnel (l'écran,
 * l'action en cours). À utiliser dans les `catch` là où on veut savoir qu'un
 * chemin a échoué sans faire planter l'app.
 *
 * ⚠️ Ne mets JAMAIS de contenu d'observation ni de prénom dans `contexte` :
 * c'est de la donnée d'enfant, elle n'a rien à faire dans un outil de crash.
 * Des clés utiles : `{ ecran: 'journal', action: 'cloture' }`.
 *
 * Si Sentry est inerte (pas de DSN), on retombe sur un simple avertissement
 * console pour ne pas perdre l'information en développement.
 */
export function signalerErreur(e: unknown, contexte?: Record<string, unknown>): void {
  if (!sentryDisponible) {
    console.warn('Erreur (Sentry inerte)', e, contexte);
    return;
  }
  Sentry.captureException(e, contexte ? { contexts: { educooo: contexte } } : undefined);
}

// ── PostHog ───────────────────────────────────────────────────────────────

// Le client PostHog, créé une seule fois pour tout le process s'il y a une clé,
// sinon null (intégration inerte). On l'instancie hors du composant pour ne pas
// le recréer à chaque rendu, et on l'injecte au provider via `client`.
const posthog = extra.posthogKey
  ? new PostHog(extra.posthogKey, {
      host: extra.posthogHost ?? POSTHOG_HOST_DEFAUT,
    })
  : null;

// `app: educooo` sur tous les événements : le même projet PostHog peut un jour
// recevoir plusieurs apps du studio, cette propriété permet de les distinguer
// sans se fier au nom d'événement. `register` la colle à chaque capture.
posthog?.register({ app: 'educooo' });

// Les propriétés d'un événement restent des valeurs simples : c'est une
// discipline autant qu'une contrainte de type. On ne colle pas un objet
// d'observation entier dans un event, on choisit des champs plats et anodins.
type ValeurAnalytics = string | number | boolean | null;

type Analytics = {
  /** Vrai si PostHog est utilisable (clé présente). Sinon tout est no-op. */
  disponible: boolean;
  /** Capte un événement NOMMÉ, avec des propriétés qu'on choisit une par une. */
  capter: (evenement: string, props?: Record<string, ValeurAnalytics>) => void;
  /** Relie l'identité (id Supabase). No-op si PostHog absent. */
  identifier: (id: string) => void;
};

const Contexte = createContext<Analytics | null>(null);

/**
 * Le fournisseur d'analytics. Il enveloppe l'app dans le `PostHogProvider` quand
 * une clé existe, et sinon rend juste les enfants : dans ce cas le hook renvoie
 * des no-op et rien n'est envoyé nulle part.
 *
 * Il DOIT être monté sous `FournisseurSession` (il lit `useMoi`) pour relier
 * l'identité : dès qu'une session existe, on identifie la personne côté PostHog
 * ET côté Sentry ; à la déconnexion, on remet tout à zéro pour ne pas prêter
 * l'activité d'un compte au suivant sur le même téléphone.
 */
export function FournisseurPostHog({ children }: { children: ReactNode }) {
  const moi = useMoi();
  const disponible = !!posthog;

  const valeur = useMemo<Analytics>(
    () => ({
      disponible,
      capter: (evenement, props) => {
        posthog?.capture(evenement, props);
      },
      identifier: (id) => {
        // L'id Supabase (uuid) est le seul identifiant qu'on relie : il ne
        // révèle rien sur l'enfant. On le pose des deux côtés pour qu'une erreur
        // et une trace d'usage désignent la même personne.
        posthog?.identify(id);
        if (sentryDisponible) Sentry.setUser({ id });
      },
    }),
    [disponible],
  );

  // Relie automatiquement l'identité à la session. On ne recombine pas cette
  // logique dans les écrans : ils appellent `capter`, l'identité suit toute
  // seule les connexions et déconnexions.
  useEffect(() => {
    if (moi) {
      posthog?.identify(moi);
      if (sentryDisponible) Sentry.setUser({ id: moi });
    } else {
      // Déconnexion : PostHog repasse en anonyme (nouvel id de device), Sentry
      // oublie l'utilisateur. Sans ça, l'activité suivante serait attribuée à la
      // personne précédente.
      posthog?.reset();
      if (sentryDisponible) Sentry.setUser(null);
    }
  }, [moi]);

  // Pas de clé : on ne monte pas le provider, on rend juste les enfants sous un
  // contexte no-op. L'app ne sait même pas que PostHog aurait pu exister.
  if (!posthog) {
    return <Contexte.Provider value={valeur}>{children}</Contexte.Provider>;
  }

  return (
    <PostHogProvider
      client={posthog}
      // 🔒 RGPD : on garde les vues d'écran (des noms de routes, sans donnée
      // sensible) mais on COUPE l'autocapture des interactions. C'est elle qui
      // remonterait des libellés et du texte tapés à l'écran, donc potentiellement
      // des prénoms d'enfants. On ne veut que des événements nommés par nous.
      autocapture={{ captureTouches: false, captureScreens: true }}
    >
      <Contexte.Provider value={valeur}>{children}</Contexte.Provider>
    </PostHogProvider>
  );
}

/**
 * Le hook d'usage. `capter('journal_ouvert')` pour un événement, `identifier(id)`
 * pour relier une identité à la main (rarement utile, l'identité suit déjà la
 * session). Tout est no-op si PostHog est inerte, donc les écrans n'ont jamais
 * à vérifier sa présence.
 */
export function useAnalytics(): Analytics {
  const valeur = useContext(Contexte);
  if (!valeur) throw new Error('useAnalytics doit être appelé sous FournisseurPostHog.');
  return valeur;
}
