import AsyncStorage from '@react-native-async-storage/async-storage';

/**
 * La page sur laquelle l'app s'ouvre (retour Valentin 24/08).
 *
 * Par défaut « Capter » : le geste le plus fréquent d'une enseignante en classe,
 * c'est de capter une observation, pas de consulter son pilotage. La première
 * fois est traitée à part (on suit les premiers pas sur le Pilotage) — voir le
 * layout des onglets. On mémorise le choix par appareil, comme le thème.
 */
export type PageAccueil = 'index' | 'journal' | 'capter' | 'groupes' | 'vous';

const CLE = 'educooo:page-accueil';
const DEFAUT: PageAccueil = 'capter';

/** Toutes les valeurs, pour le sélecteur des réglages, dans l'ordre des onglets. */
export const PAGES_ACCUEIL: PageAccueil[] = ['index', 'journal', 'capter', 'groupes', 'vous'];

/** La page préférée, ou « Capter » par défaut (et sur erreur de lecture). */
export async function pageAccueil(): Promise<PageAccueil> {
  try {
    const v = await AsyncStorage.getItem(CLE);
    return v && (PAGES_ACCUEIL as string[]).includes(v) ? (v as PageAccueil) : DEFAUT;
  } catch {
    return DEFAUT;
  }
}

/** Range le choix. L'échec n'est pas bloquant : au pire on rouvre sur le défaut. */
export async function definirPageAccueil(page: PageAccueil): Promise<void> {
  try {
    await AsyncStorage.setItem(CLE, page);
  } catch {
    // Rien à faire : le choix reprendra au prochain passage.
  }
}
