import { router, useFocusEffect } from 'expo-router';
import { useCallback } from 'react';

import { BibliothequeListe } from '@/components/bibliotheque-liste';
import { Alerte } from '@/components/formulaire';
import { t } from '@/i18n';
import { bibliotheque } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';

/**
 * L'onglet « Bibliothèque » du profil : les leçons du prof, dédupliquées et
 * rangées par domaine comme des classeurs. Toute l'UI (recherche, filtres,
 * intercalaires) vit dans `BibliothequeListe`, partagée avec « Reprendre une
 * leçon » à la création. Ici, un tap ouvre la fiche de la leçon.
 */
export function MoiActivites() {
  const lecons = useRequete(() => bibliotheque(), []);

  useFocusEffect(
    useCallback(() => {
      lecons.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []),
  );

  if (lecons.erreur) return <Alerte message={lecons.erreur} />;

  return (
    <BibliothequeListe
      lecons={lecons.donnees ?? []}
      chargement={lecons.chargement}
      vide={t.moi.activitesVide}
      onChoisir={(l) => router.push({ pathname: '/activite/[id]', params: { id: l.id } })}
    />
  );
}
