import type { Session } from '@supabase/supabase-js';
import { createContext, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';

import { rejouerObservationsEnAttente } from './donnees';
import { estEnLigne, surRetourEnLigne } from './reseau';
import { supabase } from './supabase';

type EtatSession = {
  session: Session | null;
  /** Vrai tant qu'on ne sait pas encore s'il y a une session en mémoire. */
  chargement: boolean;
  deconnecter: () => Promise<void>;
};

const Contexte = createContext<EtatSession | null>(null);

/**
 * Une seule source de vérité pour la session, parce que toute la base est
 * protégée par ligne : sans session, une requête ne renvoie pas une erreur mais
 * zéro ligne, ce qui se confond avec « la base est vide ». Mieux vaut savoir.
 */
export function FournisseurSession({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<Session | null>(null);
  const [chargement, setChargement] = useState(true);
  // Vrai le temps d'une déconnexion voulue par l'utilisatrice. Sert à distinguer
  // un `SIGNED_OUT` demandé (on obéit) d'un `null` subi hors-ligne (on garde).
  const signOutVoulu = useRef(false);

  useEffect(() => {
    // La session vit dans AsyncStorage, donc sa lecture est asynchrone : on
    // attend de savoir avant de décider quel écran montrer, sinon l'app
    // affiche la connexion pendant une fraction de seconde à chaque ouverture.
    // ⚠️ `getSession` ne déconnecte PAS hors-ligne : le client Supabase installé
    // (auth-js 2.112.3) applique le « proactive-preserve » — tant que le jeton
    // d'accès n'est pas réellement expiré, un refresh réseau qui échoue rend
    // quand même la session en cache. Avec `jwt_exp` à 1 jour, une journée de
    // classe sans réseau reste connectée.
    supabase.auth.getSession().then(({ data }) => {
      setSession(data.session);
      setChargement(false);
    });

    // Résilience hors-ligne (le point le plus sensible). auth-js n'émet un
    // `SIGNED_OUT` (session = null) que dans trois cas : déconnexion explicite,
    // jeton réellement expiré ET refresh rejeté par le serveur, ou session
    // corrompue en stockage. Un simple échec réseau de refresh ne déclenche
    // JAMAIS de déconnexion (vérifié dans le code d'auth-js). On ajoute ici une
    // ceinture de sécurité en plus de cette garantie : un `null` non demandé
    // n'est honoré que si l'on est EN LIGNE. Hors-ligne, une vraie révocation
    // est de toute façon inobservable (elle exige une réponse du serveur), donc
    // garder la session en cache ne prolonge aucune session révoquée — au
    // premier retour du réseau, un vrai refresh tranche et déconnecte si besoin.
    const { data: abonnement } = supabase.auth.onAuthStateChange((_evenement, s) => {
      if (s) {
        // Session présente (connexion, refresh réussi) : on l'adopte toujours.
        setSession(s);
        setChargement(false);
        return;
      }
      if (signOutVoulu.current) {
        // Déconnexion explicite : honorée sans condition.
        signOutVoulu.current = false;
        setSession(null);
        setChargement(false);
        return;
      }
      // `null` non demandé : on ne renvoie à la connexion que si l'on est en
      // ligne. Sinon on garde la session en cache et on ne bascule pas d'écran.
      estEnLigne().then((enLigne) => {
        setChargement(false);
        if (enLigne) setSession(null);
      });
    });

    return () => abonnement.subscription.unsubscribe();
  }, []);

  const valeur = useMemo<EtatSession>(
    () => ({
      session,
      chargement,
      deconnecter: async () => {
        signOutVoulu.current = true;
        // On coupe la session LOCALEMENT d'abord : le garde bascule sur la
        // connexion immédiatement, sans attendre la révocation réseau. Sur un
        // compte qui vient d'être supprimé, cet appel `signOut` pouvait pendre
        // (le serveur ne reconnaît plus le jeton) et laisser un spinner tourner
        // sans fin. La révocation part maintenant en arrière-plan, sans bloquer
        // l'écran ; une déconnexion voulue aboutit donc toujours, tout de suite.
        setSession(null);
        void supabase.auth.signOut().catch(() => {});
      },
    }),
    [session, chargement],
  );

  // Le rejeu de la file hors-ligne est branché ici même : dès qu'il y a une
  // session, au montage et à chaque retour du réseau. Aucun autre fichier
  // (notamment `_layout.tsx`) n'a besoin de changer pour ça.
  useRejeuObservations(!!session);

  return <Contexte.Provider value={valeur}>{children}</Contexte.Provider>;
}

/**
 * Rejoue la file des observations captées hors-ligne, dès qu'il y a une session
 * (le rejeu insère via Supabase authentifié, donc la protection par ligne
 * s'applique) : une fois au montage si l'on est en ligne, puis à chaque retour
 * du réseau. Posé dans le fournisseur de session parce que c'est le seul endroit
 * qui sait, à la fois, qu'on est connecté·e et depuis quand.
 */
function useRejeuObservations(connecte: boolean) {
  useEffect(() => {
    if (!connecte) return;
    // Au démarrage / après connexion : on vide ce qui attend, si le réseau est là.
    rejouerObservationsEnAttente();
    // Puis à chaque bascule hors-ligne → en ligne.
    const desabonner = surRetourEnLigne(() => {
      rejouerObservationsEnAttente();
    });
    return desabonner;
  }, [connecte]);
}

export function useSession(): EtatSession {
  const valeur = useContext(Contexte);
  if (!valeur) throw new Error('useSession doit être appelé sous FournisseurSession.');
  return valeur;
}

/** L'identifiant de l'enseignant·e connecté·e, ou null. Sert de filtre partout. */
export function useMoi(): string | null {
  return useSession().session?.user.id ?? null;
}
