/** Périodes proposées. On garde deux choix simples plutôt qu'un sélecteur de
 * dates : en RDV, on veut « l'année » ou « ce mois-ci », pas un calendrier. */
type ClePeriode = 'annee' | 'mois';
function bornesPeriode(cle: ClePeriode): { debut: string; fin: string } {
  if (cle === 'mois') {
    const n = new Date();
    const debut = new Date(n.getFullYear(), n.getMonth(), 1);
    const fin = new Date(n.getFullYear(), n.getMonth() + 1, 0);
    return { debut: iso(debut), fin: iso(fin) };
  }
  return anneeScolaireCourante();
}
function iso(d: Date): string {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/** Une couleur de moment par domaine, en rotation : la charte veut de la couleur
 * dans les petites surfaces (la barre), jamais un grand aplat. */
const MOMENTS: Moment[] = ['accueil', 'ateliers', 'dirigees', 'recreation', 'sortie', 'social'];

export default function EspaceDirection() {
  const role = useRequete(monRole, []);
  const estDirection = role.donnees === 'direction' || role.donnees === 'admin';
  const estInspection = role.donnees === 'inspection' || role.donnees === 'admin';
  const autorise = estDirection || estInspection;

  // L'admin peut voir les deux vues : on lui laisse un choix. Direction par
  // défaut, c'est la vue qu'on montre aux écoles.
  const [vue, setVue] = useState<RoleApp>('direction');
  const roleActif: 'direction' | 'inspection' =
    role.donnees === 'admin' ? (vue === 'inspection' ? 'inspection' : 'direction') : estInspection ? 'inspection' : 'direction';

  // Tant qu'on ne connaît pas le rôle, on ne montre rien de définitif : afficher
  // « réservé » puis le remplacer ferait clignoter un refus au visage de la
  // bonne personne.
  if (role.chargement) {
    return <SousEcran titre={TXT.titreDirection} sousTitre={TXT.sousTitre} chargement />;
  }

  if (!autorise) {
    return (
      <SousEcran titre={TXT.titreDirection} sousTitre={TXT.sousTitre}>
        <EtatVide icone="lock" moment="recreation" titre={TXT.refuseTitre} corps={TXT.refuseCorps} />
      </SousEcran>
    );
  }

  return (
    <Ecran titre={roleActif === 'inspection' ? TXT.titreInspection : TXT.titreDirection}>
      {role.donnees === 'admin' ? (
        <Pastilles
          etiquette="Vue"
          options={[
            { id: 'direction', libelle: 'Direction' },
            { id: 'inspection', libelle: 'Inspection' },
          ]}
          choisi={vue}
          onChoisir={(id) => setVue((id as RoleApp) ?? 'direction')}
        />
      ) : null}

      {roleActif === 'inspection' ? <VueInspection /> : <VueDirection />}
    </Ecran>
  );
}

/** La vue direction : périmètre = mes écoles approuvées, agrégat école. */
function VueDirection() {
  const [periode, setPeriode] = useState<ClePeriode>('annee');
  const bornes = useMemo(() => bornesPeriode(periode), [periode]);

  const ecoles = useRequete(mesEcolesApprouvees, []);
  const demandes = useRequete(mesDemandes, []);
  const synth = useRequete(() => syntheseDirection(bornes.debut, bornes.fin), [bornes.debut, bornes.fin]);
  const absences = useRequete(
    () => syntheseAbsencesDirection(bornes.debut, bornes.fin),
    [bornes.debut, bornes.fin],
  );

  const nbEnAttente = (demandes.donnees ?? []).filter((d) => d.statut === 'pending').length;

  // Aucune école approuvée : on n'appelle même pas la synthèse pour rien, on
  // explique l'attente. (La synthèse renverrait vide de toute façon.)
  if (!ecoles.chargement && (ecoles.donnees ?? []).length === 0) {
    return (
      <EtatAttente titre={TXT.sansEcoleTitre} corps={TXT.sansEcoleCorps} nbEnAttente={nbEnAttente} />
    );
  }

  return (
    <>
      <SelecteurPeriode periode={periode} onChoisir={setPeriode} />
      <ListeEcoles ecoles={ecoles.donnees ?? []} />
      <CouvertureDirection synth={synth} />
      <AbsencesDirection absences={absences} />
    </>
  );
}

/** Absences AGRÉGÉES par motif — jamais nominatif (garde-fou côté base). */
function AbsencesDirection({
  absences,
}: {
  absences: { donnees: LigneAbsenceAgregee[] | null; chargement: boolean; erreur?: string | null };
}) {
  const texte = useTexte();
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const lignes = absences.donnees ?? [];
  const total = lignes.reduce((s, l) => s + l.nombre, 0);
  // Backend pas encore déployé : on le DIT (« bientôt »), on ne fait pas passer
  // ça pour « aucune absence » — un zéro faussement rassurant à la direction.
  const backendAbsent = absences.erreur === BACKEND_ABSENT;
  return (
    <Carte>
      <EnteteSection titre={TXT.absencesTitre} />
      <Text style={texte.discret}>{TXT.absencesAide}</Text>
      {absences.chargement ? null : backendAbsent ? (
        <Text style={texte.discret}>{TXT.backendCorps}</Text>
      ) : lignes.length === 0 ? (
        <Text style={texte.discret}>{TXT.absencesVide}</Text>
      ) : (
        <View style={styles.absListe}>
          {lignes.map((l) => (
            <View key={l.type} style={styles.absLigne}>
              <Text style={styles.absNom}>{labelTypeAbsence(l.type)}</Text>
              <Text style={styles.absChiffre}>{TXT.absencesCompte(l.nombre, l.jours)}</Text>
            </View>
          ))}
          <View style={styles.absLigne}>
            <Text style={styles.absTotalNom}>{TXT.absencesTotal}</Text>
            <Text style={styles.absTotalChiffre}>{total}</Text>
          </View>
        </View>
      )}
    </Carte>
  );
}

/** Le motif en clair. Les six valeurs de la base, plus un repli neutre. */
function labelTypeAbsence(type: string): string {
  return (TXT.absencesTypes as Record<string, string>)[type] ?? TXT.absencesTypes.autre;
}

/** La vue inspection : agrégat par cycle, avec plancher d'anonymat côté serveur. */
function VueInspection() {
  const [periode, setPeriode] = useState<ClePeriode>('annee');
  const bornes = useMemo(() => bornesPeriode(periode), [periode]);
  const cycles = useRequete(cyclesInspection, []);
  const [cycle, setCycle] = useState<string | null>(null);
  const cycleActif = cycle ?? cycles.donnees?.[0] ?? null;

  const synth = useRequete(
    () => syntheseInspection(cycleActif!, bornes.debut, bornes.fin),
    [cycleActif, bornes.debut, bornes.fin],
    { actif: !!cycleActif },
  );

  return (
    <>
      <SelecteurPeriode periode={periode} onChoisir={setPeriode} />
      {(cycles.donnees ?? []).length ? (
        <Pastilles
          etiquette={TXT.cycle}
          options={(cycles.donnees ?? []).map((v) => ({ id: v, libelle: v }))}
          choisi={cycleActif}
          onChoisir={(id) => setCycle(id)}
        />
      ) : null}
      <CouvertureInspectionListe synth={synth} />
    </>
  );
}

/* ── Blocs réutilisés ──────────────────────────────────────────────────────── */

function SelecteurPeriode({ periode, onChoisir }: { periode: ClePeriode; onChoisir: (p: ClePeriode) => void }) {
  return (
    <Pastilles
      etiquette={TXT.periode}
      options={[
        { id: 'annee', libelle: 'Année scolaire' },
        { id: 'mois', libelle: 'Ce mois-ci' },
      ]}
      choisi={periode}
      onChoisir={(id) => onChoisir((id as ClePeriode) ?? 'annee')}
    />
  );
}

function ListeEcoles({ ecoles }: { ecoles: { id: string; nom: string; reseau: string }[] }) {
  const texte = useTexte();
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  if (!ecoles.length) return null;
  return (
    <>
      <EnteteSection titre={TXT.ecole} />
      <Carte compacte>
        {ecoles.map((e) => (
          <View key={e.id} style={styles.ligne}>
            <Tuile icone="home" moment="accueil" />
            <View style={styles.corps}>
              <Text style={texte.corps}>{e.nom}</Text>
              <Text style={texte.discret}>{e.reseau}</Text>
            </View>
          </View>
        ))}
      </Carte>
    </>
  );
}

/** L'état renvoyé par `useRequete`, typé structurellement (le type `Etat` n'est
 * pas exporté). Suffit pour passer une requête à un bloc d'affichage. */
type Requete<T> = { donnees: T | null; chargement: boolean; erreur: string | null; recharger: () => void };

/** La couverture direction : stats en tête, puis une barre par domaine. */
function CouvertureDirection({ synth }: { synth: Requete<CouvertureDomaine[]> }) {
  const texte = useTexte();
  if (synth.erreur === BACKEND_ABSENT) return <EtatVide icone="clock" moment="ateliers" titre={TXT.backendTitre} corps={TXT.backendCorps} />;
  if (synth.chargement || synth.donnees == null) return <Chargement />;
  const lignes = synth.donnees;

  const travailles = lignes.reduce((s, r) => s + r.travailles, 0);
  const total = lignes.reduce((s, r) => s + r.total, 0);
  const pct = total > 0 ? Math.round((travailles / total) * 100) : 0;

  return (
    <>
      <TuilesStats
        items={[
          { valeur: travailles, libelle: TXT.statTravailles, moment: 'recreation' },
          { valeur: total, libelle: TXT.statTotal, moment: 'accueil' },
          { valeur: `${pct} %`, libelle: TXT.statPct, moment: 'ateliers' },
        ]}
      />
      <EnteteSection titre={TXT.couverture} />
      {lignes.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{TXT.vide}</Text>
        </Carte>
      ) : (
        lignes.map((r, i) => (
          <BarreDomaine
            key={r.code}
            titre={r.domaine}
            travailles={r.travailles}
            total={r.total}
            extra={r.planifies > 0 ? TXT.planifies(r.planifies) : undefined}
            moment={MOMENTS[i % MOMENTS.length]}
          />
        ))
      )}
    </>
  );
}

/** La couverture inspection : plancher d'anonymat respecté (lignes masquées). */
function CouvertureInspectionListe({ synth }: { synth: Requete<CouvertureInspection[]> }) {
  const texte = useTexte();
  if (synth.erreur === BACKEND_ABSENT) return <EtatVide icone="clock" moment="ateliers" titre={TXT.backendTitre} corps={TXT.backendCorps} />;
  if (synth.chargement || synth.donnees == null) return <Chargement />;
  const lignes = synth.donnees;

  const travailles = lignes.reduce((s, r) => s + (r.travailles ?? 0), 0);
  const total = lignes.reduce((s, r) => s + r.total, 0);
  const enseignants = lignes.reduce((m, r) => Math.max(m, r.enseignants ?? 0), 0);

  return (
    <>
      <TuilesStats
        items={[
          { valeur: travailles, libelle: TXT.statTravailles, moment: 'recreation' },
          { valeur: total, libelle: TXT.statTotal, moment: 'accueil' },
          { valeur: enseignants, libelle: TXT.statEnseignants, moment: 'social' },
        ]}
      />
      <EnteteSection titre={TXT.couverture} />
      {lignes.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{TXT.vide}</Text>
        </Carte>
      ) : (
        lignes.map((r, i) =>
          r.masque ? (
            <Carte key={r.code} compacte>
              <Text style={texte.corps}>{r.domaine}</Text>
              <Text style={texte.discret}>{TXT.masque}</Text>
            </Carte>
          ) : (
            <BarreDomaine
              key={r.code}
              titre={r.domaine}
              travailles={r.travailles ?? 0}
              total={r.total}
              extra={r.enseignants != null ? `${r.enseignants} ens.` : undefined}
              moment={MOMENTS[i % MOMENTS.length]}
            />
          ),
        )
      )}
    </>
  );
}

/** Une barre de couverture d'un domaine : titre, ratio, piste teintée. */
function BarreDomaine({
  titre,
  travailles,
  total,
  extra,
  moment,
}: {
  titre: string;
  travailles: number;
  total: number;
  extra?: string;
  moment: Moment;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const pct = total > 0 ? Math.round((travailles / total) * 100) : 0;
  return (
    <Carte compacte>
      <View style={styles.barreEntete}>
        <Text style={[texte.corps, styles.barreTitre]} numberOfLines={1}>
          {titre}
        </Text>
        <Text style={texte.discret}>
          {travailles}/{total}
          {extra ? ` · ${extra}` : ''}
        </Text>
      </View>
      <View style={[styles.piste, { backgroundColor: c.teinte[moment] }]}>
        <View style={[styles.remplissage, { width: `${pct}%`, backgroundColor: c.moment[moment] }]} />
      </View>
      <Text style={[texte.discret, styles.pct]}>{TXT.couvert(pct)}</Text>
    </Carte>
  );
}

function EtatAttente({ titre, corps, nbEnAttente }: { titre: string; corps: string; nbEnAttente: number }) {
  const texte = useTexte();
  return (
    <>
      <EtatVide icone="clock" moment="sortie" titre={titre} corps={corps} />
      {nbEnAttente > 0 ? (
        <Carte compacte>
          <Text style={texte.discret}>{TXT.enAttente(nbEnAttente)}</Text>
        </Carte>
      ) : null}
    </>
  );
}

function EtatVide({ icone, moment, titre, corps }: { icone: keyof typeof Feather.glyphMap; moment: Moment; titre: string; corps: string }) {
  const texte = useTexte();
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Carte>
      <View style={styles.videEntete}>
        <Tuile icone={icone} moment={moment} taille={44} />
        <Text style={texte.section}>{titre}</Text>
      </View>
      <Text style={texte.discret}>{corps}</Text>
    </Carte>
  );
}

function Chargement() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  // Trois pistes grises en attendant : moins brutal qu'un spinner seul sur une
  // liste qu'on sait bientôt pleine.
  return (
    <>
      {[0, 1, 2].map((i) => (
        <View key={i} style={[styles.piste, styles.pisteVide]} />
      ))}
    </>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    ligne: { flexDirection: 'row', gap: espace.md, alignItems: 'center', paddingVertical: espace.xs },
    corps: { flex: 1, gap: espace.xs },
    barreEntete: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'baseline', gap: espace.sm },
    barreTitre: { flex: 1 },
    piste: { height: 10, borderRadius: rayon.pastille, overflow: 'hidden' },
    pisteVide: { backgroundColor: c.bord, marginBottom: espace.sm },
    remplissage: { height: '100%', borderRadius: rayon.pastille },
    pct: { textAlign: 'right' },
    videEntete: { flexDirection: 'row', alignItems: 'center', gap: espace.md },
    // Absences agrégées.
    absListe: { gap: espace.xs, marginTop: espace.sm },
    absLigne: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'baseline', gap: espace.md, paddingVertical: 4 },
    absNom: { flex: 1, fontFamily: police.corps, fontSize: 15, color: c.encre },
    absChiffre: { fontFamily: police.accent, fontSize: 14, color: c.encreDouce },
    absTotalNom: { flex: 1, fontFamily: police.accent, fontSize: 15, color: c.encre },
    absTotalChiffre: { fontFamily: police.titre, fontSize: 16, color: c.encre },
  });
