/**
 * Export du semainier (le journal d'une semaine) en PDF, SUR LE WEB.
 *
 * POURQUOI ici et pas via `expo-print` : le module natif d'impression n'est pas
 * installé, et la demande est web d'abord. Sur le web, le navigateur sait déjà
 * tout faire : on construit un document HTML imprimable de la semaine et on
 * ouvre la boîte d'impression, où « Enregistrer en PDF » produit le fichier.
 * Aucune dépendance ajoutée, donc aucun build natif : ça part en OTA/web.
 *
 * Ce module n'a de sens que sur le web (il touche `window`). L'écran Journal ne
 * montre le bouton que là (`Platform.OS === 'web'`).
 */
import { detailActivite, type ActiviteDetail, type ActiviteListe, type Creneau } from './donnees';

const MOMENTS: Record<string, string> = {
  accueil: 'Accueil',
  ateliers: 'Ateliers',
  dirigees: 'Activités dirigées',
  recreation: 'Récréation',
  sortie: 'Sortie',
  social: 'Vie de classe',
};
const STATUTS: Record<string, string> = {
  draft: 'Brouillon',
  unplanned: 'À planifier',
  planned: 'Planifiée',
  completed: 'Clôturée',
};
const CANAUX: Record<string, string> = {
  visuel: 'visuel',
  auditif: 'auditif',
  kinesthesique: 'kinesthésique',
  mixte: 'mixte',
};
const ROLES: Record<string, string> = {
  principal: 'principal',
  secondaire: 'secondaire',
  transversal: 'transversal',
};
const JOURS = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi'];

/** Échappe le texte libre avant de l'insérer dans le HTML : titres, objectifs,
 *  libellés d'attendus viennent des enseignant·es et peuvent contenir < & ". */
function echapper(s: string | null | undefined): string {
  if (!s) return '';
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function dateFr(d: Date): string {
  return d.toLocaleDateString('fr-BE', { day: 'numeric', month: 'long', year: 'numeric' });
}

/** Le jour de la semaine (0 = lundi) d'une date ISO `AAAA-MM-JJ`. */
function indexJour(iso: string): number {
  const [a, m, j] = iso.split('-').map(Number);
  const jour = new Date(a, m - 1, j).getDay();
  return jour === 0 ? 6 : jour - 1;
}

type Seance = { detail: ActiviteDetail; creneau: Creneau | null };

function ligneDetail(etiquette: string, valeur: string | null): string {
  if (!valeur || !valeur.trim()) return '';
  return `<div class="champ"><span class="cle">${etiquette}</span> ${echapper(valeur)}</div>`;
}

function blocSeance(s: Seance): string {
  const d = s.detail;
  const heure = s.creneau ? `${s.creneau.debut}&ndash;${s.creneau.fin}` : 'Sans heure';
  const moment = s.creneau?.moment ? MOMENTS[s.creneau.moment] ?? '' : '';
  const statut = STATUTS[d.statut] ?? d.statut;

  const attendus = d.attendus.length
    ? `<div class="attendus"><div class="cle">Attendus travaillés</div><ul>${d.attendus
        .map((a) => {
          const role = a.role ? ` <em>(${ROLES[a.role] ?? a.role})</em>` : '';
          const cadre = [a.competence, a.domaine].filter(Boolean).map(echapper).join(' &middot; ');
          return `<li>${echapper(a.libelle)}${role}${cadre ? `<span class="cadre">${cadre}</span>` : ''}</li>`;
        })
        .join('')}</ul></div>`
    : '<div class="vide-attendu">Aucun attendu rattaché</div>';

  return `<div class="seance">
    <div class="tete">
      <span class="heure">${heure}</span>
      <span class="titre">${echapper(d.titre)}</span>
      <span class="statut s-${d.statut}">${statut}</span>
    </div>
    ${moment ? `<div class="moment">${moment}</div>` : ''}
    ${ligneDetail('Objectif', d.objectif)}
    ${ligneDetail('Description', d.description)}
    ${ligneDetail('Matériel', d.materiel)}
    ${ligneDetail('Organisation', d.organisation)}
    ${ligneDetail('Groupement', d.groupement)}
    ${ligneDetail('Lieu', d.lieu)}
    ${d.canal ? ligneDetail('Canal', CANAUX[d.canal] ?? d.canal) : ''}
    ${d.modalite ? ligneDetail('Évaluation', d.modalite) : ''}
    ${attendus}
  </div>`;
}

function construireHtml(params: {
  classeNom: string;
  lundi: Date;
  vendredi: Date;
  parJour: Seance[][];
}): string {
  const { classeNom, lundi, vendredi, parJour } = params;

  const jours = JOURS.map((nom, i) => {
    const seances = parJour[i] ?? [];
    const date = new Date(lundi);
    date.setDate(lundi.getDate() + i);
    const contenu = seances.length
      ? seances.map(blocSeance).join('')
      : '<div class="rien">Rien de planifié</div>';
    return `<section class="jour">
      <h2>${nom} <span class="date-jour">${dateFr(date)}</span></h2>
      ${contenu}
    </section>`;
  }).join('');

  return `<!doctype html><html lang="fr"><head><meta charset="utf-8">
<title>Journal — ${echapper(classeNom)}</title>
<style>
  @page { size: A4; margin: 16mm 14mm; }
  * { box-sizing: border-box; }
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; color: #171622; margin: 0; }
  header { border-bottom: 3px solid #FF7A59; padding-bottom: 10px; margin-bottom: 18px; }
  header h1 { margin: 0; font-size: 22px; }
  header .semaine { color: #6b6880; font-size: 14px; margin-top: 4px; }
  .jour { break-inside: avoid; margin-bottom: 20px; }
  .jour h2 { font-size: 16px; margin: 0 0 8px; padding-bottom: 4px; border-bottom: 1px solid #E5E3EE; }
  .date-jour { color: #6b6880; font-weight: 400; font-size: 13px; }
  .rien { color: #a8a6b8; font-size: 13px; font-style: italic; padding: 2px 0 6px; }
  .seance { break-inside: avoid; border: 1px solid #E5E3EE; border-radius: 10px; padding: 10px 12px; margin-bottom: 10px; }
  .tete { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
  .heure { font-variant-numeric: tabular-nums; font-weight: 700; font-size: 13px; color: #FF7A59; }
  .titre { font-weight: 700; font-size: 15px; flex: 1; }
  .statut { font-size: 11px; padding: 2px 8px; border-radius: 999px; background: #F1F0F6; color: #6b6880; }
  .statut.s-completed { background: rgba(63,196,110,.16); color: #1f8c48; }
  .statut.s-planned { background: rgba(79,141,247,.14); color: #2f66c9; }
  .moment { color: #6b6880; font-size: 12px; margin: 2px 0 6px; }
  .champ { font-size: 12.5px; line-height: 1.4; margin-top: 4px; }
  .champ .cle { font-weight: 600; color: #4a495a; }
  .attendus { margin-top: 8px; }
  .attendus .cle { font-weight: 600; color: #4a495a; font-size: 12.5px; }
  .attendus ul { margin: 4px 0 0; padding-left: 18px; }
  .attendus li { font-size: 12.5px; line-height: 1.45; margin-bottom: 3px; }
  .attendus em { color: #6b6880; font-style: italic; }
  .cadre { display: block; color: #8b889c; font-size: 11px; }
  .vide-attendu { color: #a8a6b8; font-size: 12px; font-style: italic; margin-top: 6px; }
  footer { margin-top: 12px; color: #a8a6b8; font-size: 11px; text-align: center; }
</style></head>
<body>
  <header>
    <h1>Journal de classe &middot; ${echapper(classeNom)}</h1>
    <div class="semaine">Semaine du ${dateFr(lundi)} au ${dateFr(vendredi)}</div>
  </header>
  ${jours}
  <footer>Exporté depuis EducooO</footer>
  <script>window.addEventListener('load', function(){ setTimeout(function(){ try { window.focus(); window.print(); } catch(e){} }, 350); });</script>
</body></html>`;
}

/**
 * Construit le PDF de la semaine et ouvre l'impression du navigateur.
 *
 * On récupère le détail complet de chaque séance (`detailActivite`) : la liste
 * du journal ne porte que les titres, or on veut « tout le détail » (objectif,
 * matériel, organisation, attendus rattachés…). Une poignée d'appels pour une
 * semaine, c'est le bon compromis pour un export ponctuel.
 */
export async function exporterSemainePdf(params: {
  classeNom: string;
  lundi: Date;
  activites: ActiviteListe[];
  creneaux: Creneau[];
}): Promise<void> {
  if (typeof window === 'undefined') return;

  const vendredi = new Date(params.lundi);
  vendredi.setDate(params.lundi.getDate() + 4);

  const parCreneau = new Map<string, Creneau>();
  for (const c of params.creneaux) parCreneau.set(c.id, c);

  // Détail de chaque séance datée de la semaine, en parallèle. On garde l'ordre
  // par jour puis par heure de créneau (comme le journal à l'écran).
  const datees = params.activites.filter((a) => a.date);
  const details = await Promise.all(datees.map((a) => detailActivite(a.id)));

  const parJour: Seance[][] = [[], [], [], [], []];
  details.forEach((detail, i) => {
    if (!detail || !detail.date) return;
    const idx = indexJour(detail.date);
    if (idx < 0 || idx > 4) return;
    const creneau = detail.creneauId ? parCreneau.get(detail.creneauId) ?? null : null;
    parJour[idx].push({ detail, creneau });
  });
  for (const liste of parJour) {
    liste.sort((x, y) => (x.creneau?.debut ?? '').localeCompare(y.creneau?.debut ?? ''));
  }

  const html = construireHtml({ classeNom: params.classeNom, lundi: params.lundi, vendredi, parJour });

  const fenetre = window.open('', '_blank');
  if (!fenetre) throw new Error('fenetre_bloquee');
  fenetre.document.open();
  fenetre.document.write(html);
  fenetre.document.close();
}
