import { router, useFocusEffect } from 'expo-router';
import { useCallback, useMemo } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import { Carte } from '@/components/ecran';
import { BoutonPrincipal, BoutonSecondaire } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { elevesDe, nomAffiche, observationsDe } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Le rituel du soir : ranger sa journée avec Cloudy, une note après l'autre.
 *
 * 🔑 Le rituel ne DUPLIQUE pas le rangement : il l'orchestre. Chaque note ouvre
 * l'écran `ranger/[id]` existant, qui fait tout le travail (IA, citation, niveau)
 * et rend la main. En revenant ici, la note rangée a quitté la file et la
 * suivante se présente. C'est ce qui donne le « une après l'autre » sans réécrire
 * une ligne de la logique de rangement.
 *
 * 🔑 À la fin, Cloudy ne fabrique rien : il rend UNE observation humaine tirée du
 * réel, une note vraiment écrite aujourd'hui. Faute d'en avoir, il ne l'invente
 * pas et se contente d'un mot calme.
 *
 * Charte : une seule Cloudy sur l'écran, et le dégradé d'action une seule fois
 * (le bouton « ranger celle-ci », qui n'existe que tant qu'il reste à ranger).
 */
export default function Soir() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const observations = useRequete(() => observationsDe(classeId!, 100), [classeId], {
    actif: !!classeId,
  });
  const eleves = useRequete(() => elevesDe(classeId!), [classeId], { actif: !!classeId });

  // Au retour du rangement (une modale posée par-dessus), la file a changé : on
  // recharge à chaque fois que l'écran reprend le focus, pour que la note rangée
  // disparaisse et que la suivante s'avance.
  useFocusEffect(
    useCallback(() => {
      if (classeId) observations.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId]),
  );

  const liste = observations.donnees ?? [];
  const aRanger = liste.filter((o) => o.statut === 'pending');
  const prochaine = aRanger[0] ?? null;
  const resteApres = Math.max(0, aRanger.length - 1);

  // Le mot humain de la fin : une note rangée AUJOURD'HUI, la plus récente qui
  // porte un texte. Réelle, jamais inventée. Rien tant qu'il reste à ranger.
  const bilanDuSoir = useMemo(() => {
    const obs = observations.donnees ?? [];
    if (obs.some((o) => o.statut === 'pending')) return null;
    const rangeeAuj = obs.find(
      (o) => o.statut === 'processed' && estAujourdhui(o.creeLe) && o.texte,
    );
    if (!rangeeAuj) return null;
    const eleve = (eleves.donnees ?? []).find((e) => e.id === rangeeAuj.eleveId) ?? null;
    return { texte: rangeeAuj.texte, prenom: eleve ? nomAffiche(eleve) : null };
  }, [observations.donnees, eleves.donnees]);

  return (
    <SousEcran titre={t.rituel.titre} chargement={observations.chargement}>
      {prochaine ? (
        <>
          <View style={styles.tete}>
            <Cloudy pose="loupe" taille={96} anime />
            <Text style={[texte.section, styles.centre]}>{t.rituel.aRangerTitre}</Text>
            <Text style={[texte.discret, styles.centre]}>
              {t.rituel.aRangerIndice(aRanger.length)}
            </Text>
          </View>

          <Carte>
            <Text style={texte.discret}>{t.rituel.laNote}</Text>
            <Text style={texte.corps}>{prochaine.texte}</Text>
          </Carte>

          <BoutonPrincipal
            libelle={t.rituel.rangerCelleCi}
            onPress={() => router.push({ pathname: '/ranger/[id]', params: { id: prochaine.id } })}
          />
          {resteApres > 0 ? (
            <Text style={[texte.discret, styles.centre]}>{t.rituel.resteApres(resteApres)}</Text>
          ) : null}
        </>
      ) : (
        <>
          <View style={styles.tete}>
            <Cloudy pose="serenite" taille={96} anime />
            <Text style={[texte.section, styles.centre]}>{t.rituel.termineTitre}</Text>
            <Text style={[texte.discret, styles.centre]}>{t.rituel.termineIndice}</Text>
          </View>

          {/* L'observation humaine, si elle existe vraiment. Sinon, rien : on ne
              remplit pas le silence avec une phrase fabriquée. */}
          {bilanDuSoir ? (
            <Carte>
              <Text style={texte.discret}>{t.rituel.retenu}</Text>
              {bilanDuSoir.prenom ? <Text style={styles.prenom}>{bilanDuSoir.prenom}</Text> : null}
              <Text style={texte.corps}>{bilanDuSoir.texte}</Text>
            </Carte>
          ) : null}

          <BoutonSecondaire libelle={t.rituel.revenir} onPress={() => router.back()} />
        </>
      )}
    </SousEcran>
  );
}

/** Vrai si une date ISO tombe aujourd'hui, en heure locale. */
function estAujourdhui(iso: string): boolean {
  const d = new Date(iso);
  const n = new Date();
  return (
    d.getFullYear() === n.getFullYear() &&
    d.getMonth() === n.getMonth() &&
    d.getDate() === n.getDate()
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  tete: { alignItems: 'center', gap: espace.sm, paddingVertical: espace.md },
  centre: { textAlign: 'center' },
  prenom: { fontFamily: police.accent, fontSize: 15, color: c.action[1] },
});
