import { Feather } from '@expo/vector-icons';
import { Image } from 'expo-image';
import { useMemo, useRef, useState } from 'react';
import { Alert, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';

import { Dictee } from '@/components/dictee';
import { Carte } from '@/components/ecran';
import { Alerte, BoutonPrincipal, BoutonSecondaire, Champ, Pastilles } from '@/components/formulaire';
import { Presse } from '@/components/presse';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { activiteDuMoment, activitesDe, creerObservation, elevesDe } from '@/lib/donnees';
import { choisirPhoto, joindrePhoto, prendrePhoto, type ImageChoisie } from '@/lib/media';
import { useRequete } from '@/lib/requete';
import { useMoi } from '@/lib/session';
import { espace, ombre, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * La composition d'observation : dicter ou écrire, relire, préciser, ranger.
 *
 * 🚨 C'est LE seul chemin de capture de l'app, extrait de l'écran Capter pour
 * qu'il serve aussi la capture rapide (modale ouverte de partout). Un seul
 * composant, un seul appel à `creerObservation`, donc une seule surface de
 * masquage : le texte dicté ou tapé revient AVEC les prénoms, se pose dans le
 * champ, et n'est jamais rangé ni envoyé automatiquement. Le masquage vit dans
 * la couche données, en aval de ce champ. Dupliquer cette composition, ce
 * serait ouvrir un deuxième trou à surveiller.
 *
 * La composition (champ, élève, activité, ranger) n'apparaît qu'une fois qu'il
 * y a de la matière à ranger : un texte dicté, un texte tapé, ou le mode
 * écriture demandé explicitement.
 */
export function ComposerObservation({ onEnregistre }: { onEnregistre?: () => void }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const moi = useMoi();
  const { classe, chargement } = useClasse();
  const champRef = useRef<TextInput>(null);
  const [saisie, setSaisie] = useState('');
  const [modeTexte, setModeTexte] = useState(false);
  // Les photos choisies mais pas encore jointes : elles vivent en état local et
  // ne partent qu'au « Ranger », APRÈS création de l'observation.
  const [photos, setPhotos] = useState<ImageChoisie[]>([]);
  const [eleveId, setEleveId] = useState<string | null>(null);
  const [activiteId, setActiviteId] = useState<string | null>(null);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);
  const [confirme, setConfirme] = useState(false);
  // Le sélecteur d'activité s'ouvre replié : l'activité en cours en avant, le
  // reste derrière « une autre activité » pour ne pas dérouler une liste à
  // rallonge (retour Valentin 24/08, hiérarchie des captures stores).
  const [montrerActivites, setMontrerActivites] = useState(false);

  const classeId = classe?.id ?? null;

  const eleves = useRequete(() => elevesDe(classeId!), [classeId], { actif: !!classeId });
  // On tire large (40) parce qu'un atelier récurrent crée une ligne par semaine :
  // huit lignes ne montraient parfois qu'un seul atelier répété huit fois. On
  // dédoublonne ensuite par titre pour ne proposer chaque atelier qu'une fois.
  const activites = useRequete(() => activitesDe(classeId!, 40), [classeId], { actif: !!classeId });
  // Ce qui se déroule là, maintenant : l'activité planifiée aujourd'hui sur le
  // créneau en cours de la semaine type, s'il y en a une.
  const enCours = useRequete(() => activiteDuMoment(classeId!), [classeId], { actif: !!classeId });

  const optionsEleves = useMemo(
    () =>
      (eleves.donnees ?? []).map((e) => ({
        id: e.id,
        libelle: e.initialeNom ? `${e.prenom} ${e.initialeNom}.` : e.prenom,
      })),
    [eleves.donnees],
  );

  // Un atelier récurrent existe une fois par semaine en base : « Chasse aux
  // nombres dans la cour » remontait huit fois. On ne garde qu'une entrée par
  // titre, la première (la plus récente, la liste est triée par date). Ranger
  // une observation sur « l'atelier » vaut mieux que sur une semaine précise.
  const optionsActivites = useMemo(() => {
    const vus = new Set<string>();
    const options: { id: string; libelle: string }[] = [];
    for (const a of activites.donnees ?? []) {
      const cle = a.titre.trim().toLowerCase();
      if (vus.has(cle)) continue;
      vus.add(cle);
      options.push({ id: a.id, libelle: a.titre });
    }
    return options;
  }, [activites.donnees]);

  // Présélection douce de l'activité en cours. Une seule fois, quand on la
  // connaît : l'observation captée à cet instant porte le plus souvent sur ce
  // qui se passe là. On ne la propose que si elle figure dans la liste affichée,
  // pour que la présélection soit visible ; et on n'écrase pas un choix déjà
  // fait. Un tap sur la pastille la défait, comme pour l'élève. Appliquée au
  // rendu où la condition devient vraie (le drapeau en état garantit l'unicité).
  const [activiteProposee, setActiviteProposee] = useState(false);
  if (
    !activiteProposee &&
    enCours.donnees &&
    optionsActivites.some((o) => o.id === enCours.donnees!.id)
  ) {
    setActiviteProposee(true);
    setActiviteId((choisi) => choisi ?? enCours.donnees!.id);
  }

  // La composition n'apparaît qu'avec de la matière à ranger : un texte dicté,
  // un texte tapé, une photo, ou le mode écriture demandé explicitement.
  const composer = modeTexte || saisie.trim().length > 0 || photos.length > 0;

  // Une photo seule suffit à ranger : on n'exige un texte que s'il n'y a aucune
  // photo. Le geste reste identique, la matière peut être une image.
  const rienARanger = !saisie.trim() && photos.length === 0;

  // Ouvre le choix de la source, puis garde l'image en état local. Le picker
  // gère la permission : refusée, il lève une erreur au message déjà tutoyé,
  // qu'on affiche tel quel.
  async function capterDepuis(source: () => Promise<ImageChoisie | null>) {
    setErreur(null);
    setConfirme(false);
    try {
      const image = await source();
      if (image) setPhotos((avant) => [...avant, image]);
    } catch (e) {
      setErreur(e instanceof Error ? e.message : String(e));
    }
  }

  function ajouterPhoto() {
    Alert.alert(t.capter.photoTitre, undefined, [
      { text: t.capter.photoPrendre, onPress: () => capterDepuis(prendrePhoto) },
      { text: t.capter.photoChoisir, onPress: () => capterDepuis(choisirPhoto) },
      { text: t.capter.photoAnnuler, style: 'cancel' },
    ]);
  }

  function retirerPhoto(index: number) {
    // Avant enregistrement : on retire juste de l'état local, rien n'est parti.
    setPhotos((avant) => avant.filter((_, i) => i !== index));
    setConfirme(false);
  }

  // Le texte dicté (héro ou compact) s'ajoute à ce qui est déjà là, jamais rangé
  // automatiquement : il atterrit dans le champ, comme s'il avait été tapé.
  function ajouterDicte(texteDicte: string) {
    setConfirme(false);
    setSaisie((avant) => (avant.trim() ? `${avant.trim()} ${texteDicte}` : texteDicte));
  }

  async function enregistrer() {
    if (!classeId || !moi) return;
    setErreur(null);
    setConfirme(false);
    setOccupe(true);
    try {
      // L'observation d'abord : la photo se joint à une observation qui existe.
      const observation = await creerObservation({
        classeId,
        auteurId: moi,
        texte: saisie,
        eleveId,
        activiteId,
        avecMedia: photos.length > 0,
      });
      // Chaque photo dans son propre try/catch : une qui échoue ne fait perdre
      // ni l'observation déjà créée ni les autres photos.
      let echecs = 0;
      for (const image of photos) {
        try {
          await joindrePhoto(observation.id, image);
        } catch {
          echecs += 1;
        }
      }
      // On vide la saisie et les photos mais on garde l'élève et l'activité : en
      // classe, plusieurs observations d'affilée portent sur le même moment.
      setSaisie('');
      setModeTexte(false);
      setPhotos([]);
      setConfirme(true);
      if (echecs > 0) setErreur(t.capter.photoEchec(echecs));
      onEnregistre?.();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : String(e));
    } finally {
      setOccupe(false);
    }
  }

  // Sans classe active : le même message que l'onglet, jamais un crash. On
  // n'affiche rien tant qu'on ne SAIT pas s'il y a une classe, pour ne pas
  // faire clignoter le message pendant le chargement.
  if (!chargement && !classe) {
    return (
      <Carte>
        <Text style={texte.discret}>{t.capter.sansClasse}</Text>
      </Carte>
    );
  }

  // L'activité en cours (celle du créneau du moment), pour la mettre en avant.
  const enCoursId = enCours.donnees?.id ?? null;
  const enCoursOption = optionsActivites.find((o) => o.id === enCoursId) ?? null;
  // Les autres activités : la liste sans celle en cours (déjà proposée en tête).
  const autresOptions = enCoursOption
    ? optionsActivites.filter((o) => o.id !== enCoursId)
    : optionsActivites;
  // On déroule la liste complète si on l'a demandée, ou si l'activité choisie
  // n'est pas celle en cours (il faut alors la voir cochée).
  const montreListe = montrerActivites || (!!activiteId && activiteId !== enCoursId);

  return (
    <>
      {/* Hors composition : le gros micro à halo mène l'écran, avec les deux
          gestes (écrire, photo). Dès qu'on a de la matière à ranger, il cède la
          place à un micro compact dans la carte de relecture (retour Valentin
          24/08) : le bloc « appuie et raconte » s'efface pour laisser voir le
          texte à corriger. */}
      {!composer ? (
        <Carte>
          <Dictee hero inactif={occupe} onTexte={ajouterDicte} />
          {confirme ? (
            <View style={styles.confirmeLigne}>
              <Feather name="check-circle" size={18} color={c.moment.recreation} />
              <Text style={styles.confirme}>{t.capter.enregistre}</Text>
            </View>
          ) : null}
          <View style={styles.deuxGestes}>
            <View style={styles.geste}>
              <BoutonSecondaire
                libelle={t.capter.noteEcrite}
                icone={<Feather name="edit-3" size={18} color={c.encre} />}
                onPress={() => {
                  setModeTexte(true);
                  setTimeout(() => champRef.current?.focus(), 50);
                }}
              />
            </View>
            <View style={styles.geste}>
              <BoutonSecondaire
                libelle={t.capter.photo}
                icone={<Feather name="camera" size={18} color={c.encre} />}
                onPress={ajouterPhoto}
              />
            </View>
          </View>
        </Carte>
      ) : null}

      {/* La composition : on relit, on précise, on range. */}
      {composer ? (
        <Carte>
          <Text style={texte.discret}>{t.capter.relire}</Text>
          <Champ
            ref={champRef}
            value={saisie}
            onChangeText={(v) => {
              setSaisie(v);
              setConfirme(false);
            }}
            placeholder={t.capter.indice}
            multiline
            numberOfLines={4}
            style={styles.zoneTexte}
            editable={!occupe}
          />
          {/* Le micro compact : continuer à dicter sans reprendre le gros bouton. */}
          <Dictee inactif={occupe} onTexte={ajouterDicte} />
          {/* Élève et activité : les deux précisions majeures d'une observation.
              On les pose en titres pleins juste sous le texte, plus en petite
              étiquette perdue en bas. Chacune reste facultative et se défait d'un
              tap. Le bloc ne s'affiche que s'il y a de quoi choisir. */}
          {optionsEleves.length > 0 ? (
            <View style={styles.selecteur}>
              <View style={styles.selecteurTete}>
                <Text style={texte.section}>{t.capter.eleve}</Text>
                <Text style={texte.discret}>{t.capter.facultatif}</Text>
              </View>
              <Pastilles options={optionsEleves} choisi={eleveId} onChoisir={setEleveId} />
            </View>
          ) : null}
          {optionsActivites.length > 0 ? (
            <View style={styles.selecteur}>
              <View style={styles.selecteurTete}>
                <Text style={texte.section}>{t.capter.activite}</Text>
                <Text style={texte.discret}>{t.capter.facultatif}</Text>
              </View>
              {/* Hiérarchie : l'activité en cours d'abord, en carte pleine ; le
                  reste replié derrière un geste, plutôt qu'une liste à rallonge. */}
              {enCoursOption ? (
                <Pressable
                  accessibilityRole="button"
                  accessibilityState={{ selected: activiteId === enCoursOption.id }}
                  accessibilityLabel={`${t.capter.activiteEnCours}, ${enCoursOption.libelle}`}
                  onPress={() =>
                    setActiviteId((choisi) =>
                      choisi === enCoursOption.id ? null : enCoursOption.id,
                    )
                  }
                  style={[styles.enCours, activiteId === enCoursOption.id && styles.enCoursActif]}>
                  <View style={styles.enCoursCorps}>
                    <Text style={styles.enCoursCaption}>{t.capter.activiteEnCours}</Text>
                    <Text style={styles.enCoursTitre} numberOfLines={1}>
                      {enCoursOption.libelle}
                    </Text>
                  </View>
                  {activiteId === enCoursOption.id ? (
                    <Feather name="check-circle" size={20} color={c.action[1]} />
                  ) : (
                    <Feather name="circle" size={20} color={c.nonRattache} />
                  )}
                </Pressable>
              ) : null}
              {autresOptions.length > 0 ? (
                montreListe ? (
                  <Pastilles options={autresOptions} choisi={activiteId} onChoisir={setActiviteId} />
                ) : (
                  <BoutonSecondaire
                    libelle={enCoursOption ? t.capter.activiteAutre : t.capter.activiteChoisir}
                    icone={<Feather name="list" size={18} color={c.encre} />}
                    onPress={() => setMontrerActivites(true)}
                  />
                )
              ) : null}
            </View>
          ) : null}

          {photos.length > 0 ? (
            <View style={styles.apercu}>
              {photos.map((photo, index) => (
                <View key={`${photo.uri}-${index}`} style={styles.tuile}>
                  <Image source={{ uri: photo.uri }} style={styles.image} contentFit="cover" />
                  <Presse
                    accessibilityRole="button"
                    accessibilityLabel={t.capter.photoRetirer}
                    onPress={() => retirerPhoto(index)}
                    style={styles.croix}>
                    <Feather name="x" size={14} color={c.surface} />
                  </Presse>
                </View>
              ))}
            </View>
          ) : null}
          <BoutonSecondaire
            libelle={t.capter.photoAjouter}
            icone={<Feather name="camera" size={18} color={c.encre} />}
            onPress={ajouterPhoto}
            occupe={occupe}
          />
          {erreur ? <Alerte message={erreur} /> : null}
          <BoutonPrincipal
            libelle={t.capter.enregistrer}
            onPress={enregistrer}
            occupe={occupe}
            inactif={rienARanger}
          />
        </Carte>
      ) : null}
    </>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  zoneTexte: { minHeight: 110, textAlignVertical: 'top' },
  selecteur: { gap: espace.xs },
  selecteurTete: { flexDirection: 'row', alignItems: 'baseline', justifyContent: 'space-between' },
  // La carte de l'activité en cours : mise en avant, sélectionnable d'un tap.
  enCours: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: espace.md,
    padding: espace.md,
    borderRadius: rayon.bloc,
    borderWidth: 1,
    borderColor: c.bord,
    backgroundColor: c.fond,
  },
  enCoursActif: { borderColor: c.actif, backgroundColor: c.surface, ...ombre.carte },
  enCoursCorps: { flex: 1, gap: 2 },
  enCoursCaption: { fontFamily: police.accent, fontSize: 12, color: c.encreDouce },
  enCoursTitre: { fontFamily: police.corps, fontSize: 16, color: c.encre },
  deuxGestes: { flexDirection: 'row', gap: espace.sm },
  geste: { flex: 1 },
  apercu: { flexDirection: 'row', flexWrap: 'wrap', gap: espace.sm },
  tuile: {
    width: 84,
    height: 84,
    borderRadius: rayon.tuile,
    overflow: 'hidden',
    borderWidth: 1,
    borderColor: c.bord,
  },
  image: { width: '100%', height: '100%' },
  croix: {
    position: 'absolute',
    top: espace.xs,
    right: espace.xs,
    width: 24,
    height: 24,
    borderRadius: 12,
    // Une pastille d'encre translucide pour que la croix se lise sur n'importe
    // quelle photo : un voile, pas un aplat de couleur.
    backgroundColor: 'rgba(23, 22, 34, 0.72)',
    alignItems: 'center',
    justifyContent: 'center',
  },
  confirmeLigne: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: espace.sm,
    justifyContent: 'center',
  },
  confirme: { fontFamily: police.accent, fontSize: 15, color: c.moment.recreation },
});
