import { Feather } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { Carte, EnteteSection } from '@/components/ecran';
import { Tuile } from '@/components/elements';
import { Alerte, Pastilles } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { langue, niveauxMaitrise, t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { couvertureDe, SEUIL_RESISTE, type Couverture } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Le programme en entier : l'arbre du référentiel, et où on en est dessus.
 *
 * 🔑 **Le chiffre avant le tableau.** C'est l'accueil qui répond à « qu'est-ce
 * qui m'attend » avec trois blocs courts ; cet écran-ci est le détail qu'on
 * ouvre quand on veut voir le reste. L'app héritée faisait l'inverse : l'arbre
 * s'ouvrait, et les chiffres étaient dedans.
 *
 * 🔑 **Les domaines sont repliés par défaut.** Une classe de troisième
 * maternelle porte 386 compétences réparties dans 45 domaines : tout déplier
 * fait un mur, et un mur ne se lit pas. Le domaine porte son compte, on ouvre
 * celui qu'on cherche.
 *
 * C'est aussi le seul endroit où le référentiel devient **visible** : d'où
 * viennent les compétences qu'on lui propose, et combien il en reste. Le reste
 * de l'app les sert sans jamais les montrer, ce qui est le bon réglage pour
 * ranger une observation, et le mauvais quand on veut se repérer dans l'année.
 */

/** Le tag discret des compétences déléguées, en local (règle studio i18n). */
const TAG_COLLEGUE = { fr: 'Suivi par un·e collègue', nl: 'Opgevolgd door een collega' }[langue];

type Filtre = 'tout' | 'resiste' | 'pasEvalue' | 'jamais';

const FILTRES: Filtre[] = ['tout', 'resiste', 'pasEvalue', 'jamais'];

function retenue(c: Couverture, filtre: Filtre): boolean {
  if (filtre === 'tout') return true;
  // Une compétence « résiste » quand elle a été travaillée plusieurs fois et
  // qu'une minorité d'élèves l'a acquise. Sans évalué, on ne conclut rien.
  if (filtre === 'resiste') {
    return c.seances >= SEUIL_RESISTE && c.evalues > 0 && c.acquis / c.evalues < 0.5;
  }
  // Travaillée sans évaluation : on n'en sait rien, ce n'est pas un échec.
  if (filtre === 'pasEvalue') return c.seances > 0 && c.evalues === 0;
  // « Jamais abordée » : aucune séance ET à moi. Une compétence déléguée à un·e
  // collègue n'est pas un trou dans MON programme, elle ne grise pas ce filtre.
  return c.seances === 0 && !c.delegue;
}

/** Une compétence est « travaillée » dès qu'elle a au moins une séance. */
function estTravaillee(c: Couverture): boolean {
  return c.seances > 0;
}

/**
 * « En cours » = la compétence résiste : travaillée plusieurs fois, une minorité
 * d'élèves l'a acquise. On réutilise à la lettre le seuil du filtre « À
 * consolider » et des paramètres envoyés à /lecon, pour ne pas dire deux choses
 * différentes du même état.
 */
function estEnCours(c: Couverture): boolean {
  return c.seances >= SEUIL_RESISTE && c.evalues > 0 && c.acquis / c.evalues < 0.5;
}

type Avancement = { total: number; travaillees: number; enCours: number };

function comptePour(liste: Couverture[]): Avancement {
  let travaillees = 0;
  let enCours = 0;
  for (const c of liste) {
    if (estTravaillee(c)) travaillees += 1;
    if (estEnCours(c)) enCours += 1;
  }
  return { total: liste.length, travaillees, enCours };
}

/**
 * L'avancement d'une section, lu d'un coup d'œil : la part travaillée (la même
 * jauge miel qu'en haut, en plus fin), et le nombre en cours quand il y en a.
 * Toujours calculé sur *tout* le domaine, jamais sur le sous-ensemble filtré :
 * une enseignante qui scanne veut voir ce qui avance, pas ce que le filtre laisse.
 */
function BarreAvancement({
  a,
  styles,
  surEcran,
}: {
  a: Avancement;
  styles: ReturnType<typeof creerStyles>;
  surEcran?: boolean;
}) {
  if (a.total === 0) return null;
  const part = Math.round((a.travaillees / a.total) * 100);
  return (
    <View style={styles.avancement}>
      <View style={surEcran ? styles.jaugeSectionEcran : styles.jaugeSection}>
        <View style={[styles.jaugeSectionRemplie, { width: `${part}%` }]} />
      </View>
      {a.enCours > 0 ? (
        <Text style={styles.enCours}>{`${niveauxMaitrise.in_progress} · ${a.enCours}`}</Text>
      ) : null}
    </View>
  );
}

/**
 * La tuile qui dit l'état, et n'est jamais rouge : on informe, on ne punit pas.
 * Vert acquis, jaune quand ça résiste, gris tant qu'il n'y a rien d'évaluable.
 */
function TuileEtat({ c }: { c: Couverture }) {
  // Déléguée à un·e collègue : ni un trou ni un état de maîtrise, un relais.
  if (c.delegue) return <Tuile icone="users" />;
  if (c.seances === 0 || c.evalues === 0) return <Tuile icone="book" />;
  if (c.acquis / c.evalues < 0.5) return <Tuile icone="trending-up" moment="ateliers" />;
  return <Tuile icone="check" moment="recreation" />;
}

export default function Competences() {
  const couleurs = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(couleurs), [couleurs]);
  const { classe } = useClasse();
  const [filtre, setFiltre] = useState<Filtre>('tout');
  const [ouverts, setOuverts] = useState<string[]>([]);

  const couverture = useRequete(() => couvertureDe(classe!), [classe?.id, classe?.cycle], {
    actif: !!classe,
  });

  const liste = couverture.donnees ?? [];
  // Les compétences déléguées à un·e collègue restent dans l'arbre (avec un tag),
  // mais ne comptent pas dans MON avancement : ni au numérateur ni au dénominateur.
  const comptables = liste.filter((c) => !c.delegue);
  const travaillees = comptables.filter((c) => c.seances > 0).length;

  // Regroupé par référentiel puis par domaine, dans l'ordre où la base les rend :
  // c'est l'ordre du document officiel, et le réordonner rendrait l'arbre
  // introuvable pour qui connaît le document.
  const arbre = useMemo(() => {
    const filtree = liste.filter((c) => retenue(c, filtre));
    const parReferentiel = new Map<string, Map<string, Couverture[]>>();
    for (const c of filtree) {
      const domaines = parReferentiel.get(c.referentiel) ?? new Map<string, Couverture[]>();
      const dedans = domaines.get(c.domaine) ?? [];
      dedans.push(c);
      domaines.set(c.domaine, dedans);
      parReferentiel.set(c.referentiel, domaines);
    }
    return [...parReferentiel.entries()];
  }, [liste, filtre]);

  // L'avancement se compte sur la liste entière, indépendamment du filtre : la
  // jauge d'une section doit dire où on en est *vraiment*, pas ce que le filtre
  // courant laisse voir. Clés `referentiel` et `referentiel|domaine`.
  const avancements = useMemo(() => {
    const parReferentiel = new Map<string, Couverture[]>();
    const parDomaine = new Map<string, Couverture[]>();
    // Sur les seules compétences comptables : une déléguée ne doit pas tirer la
    // jauge d'une section vers le bas, elle n'est pas dans ma charge.
    for (const c of liste.filter((x) => !x.delegue)) {
      (parReferentiel.get(c.referentiel) ?? parReferentiel.set(c.referentiel, []).get(c.referentiel)!).push(c);
      const cle = `${c.referentiel}|${c.domaine}`;
      (parDomaine.get(cle) ?? parDomaine.set(cle, []).get(cle)!).push(c);
    }
    const referentiel = new Map<string, Avancement>();
    for (const [k, v] of parReferentiel) referentiel.set(k, comptePour(v));
    const domaine = new Map<string, Avancement>();
    for (const [k, v] of parDomaine) domaine.set(k, comptePour(v));
    return { referentiel, domaine };
  }, [liste]);

  return (
    <SousEcran
      titre={t.competences.titre}
      sousTitre={classe?.nom}
      chargement={couverture.chargement}>
      {couverture.erreur ? <Alerte message={t.competences.erreur} /> : null}

      <Carte>
        <Text style={texte.section}>{t.competences.bilan(travaillees, comptables.length)}</Text>
        <View style={styles.jauge}>
          <View
            style={[
              styles.jaugeRemplie,
              {
                width: comptables.length
                  ? `${Math.round((travaillees / comptables.length) * 100)}%`
                  : '0%',
              },
            ]}
          />
        </View>
      </Carte>

      <Pastilles
        options={FILTRES.map((f) => ({ id: f, libelle: t.competences.filtres[f] }))}
        choisi={filtre}
        onChoisir={(v) => setFiltre((v as Filtre) ?? 'tout')}
      />

      {liste.length === 0 && !couverture.chargement ? (
        <Carte>
          <Text style={texte.discret}>{t.competences.vide}</Text>
        </Carte>
      ) : null}

      {liste.length > 0 && arbre.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.competences.filtreVide}</Text>
        </Carte>
      ) : null}

      {arbre.map(([referentiel, domaines]) => (
        <View key={referentiel} style={styles.bloc}>
          <EnteteSection titre={referentiel} />
          {avancements.referentiel.has(referentiel) ? (
            <BarreAvancement a={avancements.referentiel.get(referentiel)!} styles={styles} surEcran />
          ) : null}
          {[...domaines.entries()].map(([domaine, competences]) => {
            const cle = `${referentiel}|${domaine}`;
            const ouvert = ouverts.includes(cle);
            const avancement = avancements.domaine.get(cle);
            return (
              <View key={cle} style={styles.bloc}>
                <Pressable
                  accessibilityRole="button"
                  accessibilityState={{ expanded: ouvert }}
                  accessibilityLabel={`${domaine}, ${t.competences.domaine(competences.length)}${
                    avancement
                      ? `, ${t.competences.bilan(avancement.travaillees, avancement.total)}${
                          avancement.enCours > 0
                            ? `, ${niveauxMaitrise.in_progress} ${avancement.enCours}`
                            : ''
                        }`
                      : ''
                  }`}
                  onPress={() =>
                    setOuverts((l) => (ouvert ? l.filter((x) => x !== cle) : [...l, cle]))
                  }>
                  <Carte compacte>
                    <View style={styles.ligne}>
                      <View style={styles.corps}>
                        <Text style={texte.corps}>{domaine}</Text>
                        <Text style={texte.discret}>
                          {t.competences.domaine(competences.length)}
                        </Text>
                        {avancement ? <BarreAvancement a={avancement} styles={styles} /> : null}
                      </View>
                      <Feather
                        name={ouvert ? 'chevron-down' : 'chevron-right'}
                        size={20}
                        color={couleurs.nonRattache}
                      />
                    </View>
                  </Carte>
                </Pressable>

                {ouvert
                  ? competences.map((c) => (
                      <Pressable
                        key={c.competenceId}
                        accessibilityRole="button"
                        accessibilityLabel={
                          c.delegue
                            ? `${c.competence}, ${TAG_COLLEGUE}`
                            : `${c.competence}, ${t.competences.seances(c.seances)}, ${t.lecon.generer}`
                        }
                        onPress={() =>
                          router.push({
                            pathname: '/lecon/[competence]',
                            params: {
                              competence: c.competenceId,
                              nom: c.competence,
                              // Les deux chiffres ne partent que si la
                              // compétence résiste vraiment : sinon on
                              // demanderait « autrement » sans qu'il y ait eu
                              // un « avant ».
                              ...(c.seances >= SEUIL_RESISTE &&
                              c.evalues > 0 &&
                              c.acquis / c.evalues < 0.5
                                ? {
                                    seances: String(c.seances),
                                    acquis: String(c.acquis),
                                    evalues: String(c.evalues),
                                  }
                                : {}),
                            },
                          })
                        }
                        style={styles.decale}>
                        <Carte compacte>
                          <View style={styles.ligne}>
                            <TuileEtat c={c} />
                            <View style={styles.corps}>
                              <Text style={texte.corps}>{c.competence}</Text>
                              {c.delegue ? (
                                <View style={styles.tagCollegue}>
                                  <Feather name="users" size={12} color={couleurs.encreDouce} />
                                  <Text style={styles.tagCollegueTexte}>{TAG_COLLEGUE}</Text>
                                </View>
                              ) : (
                                <Text style={texte.discret}>
                                  {t.competences.seances(c.seances)}
                                  {c.seances > 0 ? ` · ${t.competences.acquis(c.acquis, c.evalues)}` : ''}
                                </Text>
                              )}
                            </View>
                            <Feather name="chevron-right" size={18} color={couleurs.nonRattache} />
                          </View>
                        </Carte>
                      </Pressable>
                    ))
                  : null}
              </View>
            );
          })}
        </View>
      ))}
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  bloc: { gap: espace.sm },
  ligne: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
  corps: { flex: 1, gap: espace.xs },
  decale: { paddingLeft: espace.md },
  jauge: { height: 8, borderRadius: 4, backgroundColor: c.fond, overflow: 'hidden' },
  jaugeRemplie: { height: 8, borderRadius: 4, backgroundColor: c.action[0] },
  // Variante fine de la jauge, pour une section. Sur une carte (surface), le
  // creux reprend `fond` comme la jauge du haut ; posée sur le fond d'écran
  // (niveau référentiel), il passerait inaperçu, donc on prend `bord`.
  avancement: { gap: espace.xs, marginTop: espace.xs },
  jaugeSection: { height: 6, borderRadius: 3, backgroundColor: c.fond, overflow: 'hidden' },
  jaugeSectionEcran: { height: 6, borderRadius: 3, backgroundColor: c.bord, overflow: 'hidden' },
  jaugeSectionRemplie: { height: 6, borderRadius: 3, backgroundColor: c.action[0] },
  // Le jaune du « ça résiste », le même que la tuile trending-up : on relie ce
  // compte au signal que l'enseignant·e connaît déjà.
  enCours: { fontSize: 12, fontWeight: '600', color: c.moment.ateliers },
  // Le tag discret « suivi par un·e collègue » : neutre, jamais alarmant, il dit
  // un relais et non un manque.
  tagCollegue: { flexDirection: 'row', alignItems: 'center', gap: espace.xs },
  tagCollegueTexte: { fontSize: 12, color: c.encreDouce },
});
