import AsyncStorage from '@react-native-async-storage/async-storage';

/**
 * Le tour de démarrage « Prends l'app en main » (retour Valentin 24/08).
 *
 * C'est un TUNNEL, pas une checklist : il se lance tout seul à la première
 * session, se fait d'un coup du début à la fin (fond ombré, fenêtre claire), et
 * ne revient plus. On ne mémorise donc qu'une chose : est-ce qu'il a déjà été
 * vu.
 *
 * 🔑 Le drapeau est PAR COMPTE, pas par appareil (retour Valentin 24/08 : un
 * nouveau compte n'avait pas d'onboarding). Deux enseignantes qui partagent une
 * tablette, ou un même appareil qui sert à plusieurs comptes de test, voient
 * chacune le tour une fois. La clé porte l'identifiant du compte.
 *
 * Fail-open : sans identifiant connu, ou si la lecture échoue, on considère le
 * tour comme vu (`true`) — on ne piège JAMAIS quelqu'un dans le tour à chaque
 * ouverture, et on n'ouvre rien tant qu'on ne sait pas à qui c'est.
 */
const PREFIXE = 'educooo:guide-vu';

function cle(userId: string): string {
  return `${PREFIXE}:${userId}`;
}

/** Vrai si ce compte a déjà vu le tour (ou si on ne peut pas le savoir). */
export async function aVuGuide(userId: string | null | undefined): Promise<boolean> {
  if (!userId) return true;
  try {
    return (await AsyncStorage.getItem(cle(userId))) === '1';
  } catch {
    return true;
  }
}

/** Marque le tour comme vu pour ce compte : il ne se relancera plus tout seul. */
export async function marquerGuideVu(userId: string | null | undefined): Promise<void> {
  if (!userId) return;
  try {
    await AsyncStorage.setItem(cle(userId), '1');
  } catch {
    // L'échec d'écriture n'est pas bloquant : au pire le tour se remontre une fois.
  }
}
