import { router } from 'expo-router';
import { useMemo, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import { Carte } from '@/components/ecran';
import { Alerte, BoutonPrincipal, Pastilles } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import { dupliquerProgramme } from '@/lib/donnees';
import { espace, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * Dupliquer un programme d'une classe vers une autre, sans les dates.
 *
 * Deux usages, une seule fonctionnalité : la personne qui enseigne la gym et
 * rejoue le même plan dans ses six classes, et la rentrée où l'on repart du
 * programme de l'an dernier. La cible est n'importe quelle classe qu'on possède,
 * ce qui couvre déjà les deux cas dès que la classe de l'an prochain existe.
 *
 * Rien de faux : le seul geste copie vraiment la matière (titre, préparation,
 * attendus et leur rôle) sans l'ancrage (dates, créneaux, adaptations). On le
 * dit dans le récap avant de lancer, puis on annonce le compte réel copié.
 */
export default function DupliquerEcran() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classes, classe, choisir } = useClasse();

  // Le départ par défaut est la classe active : le cas le plus courant est d'y
  // rejouer son programme ailleurs. L'arrivée reste à choisir, jamais devinée.
  const [sourceId, setSourceId] = useState<string | null>(classe?.id ?? null);
  const [cibleId, setCibleId] = useState<string | null>(null);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);
  const [copiees, setCopiees] = useState<number | null>(null);

  // L'année scolaire distingue deux classes de même nom (celle de l'an dernier
  // et la neuve), sinon on ne saurait pas laquelle on choisit à la rentrée.
  const options = useMemo(
    () => classes.map((cl) => ({ id: cl.id, libelle: `${cl.nom} · ${cl.anneeScolaire}` })),
    [classes],
  );
  const nomDe = (id: string | null) => classes.find((cl) => cl.id === id)?.nom ?? '';
  const pret = !!sourceId && !!cibleId;

  async function lancer() {
    if (!sourceId || !cibleId) return;
    setOccupe(true);
    setErreur(null);
    try {
      const { copiees: n } = await dupliquerProgramme({
        sourceClasseId: sourceId,
        cibleClasseId: cibleId,
      });
      setCopiees(n);
    } catch {
      setErreur(t.dupliquer.erreur);
    } finally {
      setOccupe(false);
    }
  }

  // Une classe au moins est nécessaire : sans elle, il n'y a ni départ ni
  // arrivée. Le cas « une seule classe » reste permis, source et cible pouvant
  // être la même (une seconde copie du programme dans la même classe).
  if (!classes.length) {
    return (
      <SousEcran titre={t.dupliquer.titre}>
        <Carte>
          <Text style={texte.corps}>{t.dupliquer.besoinClasses}</Text>
        </Carte>
      </SousEcran>
    );
  }

  // Après coup : on ne remontre pas les sélecteurs, on annonce le résultat réel
  // et on propose d'aller replanifier dans la classe d'arrivée.
  if (copiees !== null) {
    return (
      <SousEcran titre={t.dupliquer.titre}>
        <Carte>
          <View style={styles.hero}>
            <Cloudy pose="joie" taille={64} />
            <View style={styles.heroTexte}>
              <Text style={texte.section}>{t.dupliquer.succesTitre}</Text>
              <Text style={texte.corps}>{t.dupliquer.succes(copiees)}</Text>
            </View>
          </View>
          {copiees > 0 && cibleId ? (
            <BoutonPrincipal
              libelle={t.dupliquer.ouvrirCible}
              onPress={() => {
                choisir(cibleId);
                router.push('/classe');
              }}
            />
          ) : null}
        </Carte>
      </SousEcran>
    );
  }

  return (
    <SousEcran titre={t.dupliquer.titre}>
      <Carte>
        <Text style={texte.corps}>{t.dupliquer.intro}</Text>
      </Carte>

      <Carte>
        <Pastilles
          etiquette={t.dupliquer.source}
          options={options}
          choisi={sourceId}
          onChoisir={setSourceId}
        />
        <Pastilles
          etiquette={t.dupliquer.cible}
          options={options}
          choisi={cibleId}
          onChoisir={setCibleId}
        />
      </Carte>

      <Carte compacte>
        <Text style={texte.discret}>
          {pret ? t.dupliquer.resume(nomDe(sourceId), nomDe(cibleId)) : t.dupliquer.resumeIncomplet}
        </Text>
      </Carte>

      {erreur ? <Alerte message={erreur} /> : null}

      <BoutonPrincipal
        libelle={t.dupliquer.bouton}
        onPress={() => void lancer()}
        inactif={!pret}
        occupe={occupe}
      />
    </SousEcran>
  );
}

const creerStyles = (_c: Couleurs) =>
  StyleSheet.create({
    hero: { flexDirection: 'row', alignItems: 'center', gap: espace.md },
    heroTexte: { flex: 1, gap: espace.sm },
  });
