/**
 * « À replanifier » : les activités qu'une absence a récupérées et qui attendent
 * une nouvelle date.
 *
 * 🔑 On replanifie SUR PLACE. Au tap sur une activité, un petit sélecteur se
 * déplie juste sous elle : choisir un jour de la semaine (navigable) et un moment
 * libre (un créneau, ou « sans moment précis »), puis « Replanifier ici ».
 * L'activité quitte alors le vivier et disparaît de la liste, sans jamais changer
 * d'écran. Un seul sélecteur ouvert à la fois.
 *
 * Ces activités ont perdu leur date au report : elles ne portent que leur titre
 * et de quoi les reposer. Vide, c'est un état calme (rien ne traîne), pas une
 * erreur.
 */

const JOURS = [0, 1, 2, 3, 4];

const ICONE_MOMENT: Record<Moment, keyof typeof Feather.glyphMap> = {
  accueil: 'sunrise',
  ateliers: 'grid',
  dirigees: 'edit-2',
  recreation: 'coffee',
  sortie: 'map-pin',
  social: 'users',
};

const L = {
  titre: 'À replanifier',
  sousTitre: (n: number) =>
    n === 0 ? 'Rien en attente' : n === 1 ? '1 activité en attente' : `${n} activités en attente`,
  vide: 'Rien à replanifier',
  videAide: "Les activités récupérées après une absence apparaissent ici, prêtes à reposer.",
  atelier: 'Atelier',
  sansAttendu: 'sans attendu',
  erreur: 'La liste ne se charge pas. Réessaie.',
  erreurReposer: "La replanification n'a pas abouti. Réessaie.",
  choisirJour: 'Quel jour ?',
  choisirMoment: 'À quel moment ?',
  sansMoment: 'Sans moment précis',
  sansCreneau: "Pas d'horaire ce jour-là. Tu peux la poser sans moment précis.",
  aujourdhui: "Cette semaine",
  semaine: 'Semaine',
  precedente: 'Semaine précédente',
  suivante: 'Semaine suivante',
  reposer: 'Replanifier ici',
};

/** 1 = lundi … 7 = dimanche, à partir d'une date ISO locale. */
function dowDe(iso: string): number {
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  const jour = new Date(a, m - 1, j).getDay();
  return jour === 0 ? 7 : jour;
}

/** L'abrégé d'un jour : { jj: 'LUN', num: '24' }. */
function jourCourt(iso: string): { jj: string; num: string } {
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  const d = new Date(a, m - 1, j);
  const jj = d.toLocaleDateString(localeDate(), { weekday: 'short' }).replace('.', '').slice(0, 3);
  return { jj: jj.toLocaleUpperCase('fr'), num: String(j) };
}

/** Le libellé « 3 mars » d'un lundi de semaine, pour la barre de navigation. */
function libelleSemaine(iso: string): string {
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  return new Date(a, m - 1, j).toLocaleDateString(localeDate(), { day: 'numeric', month: 'short' });
}

export default function Replanifier() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  const liste = useRequete(() => activitesAReplanifier(classeId!), [classeId], { actif: !!classeId });

  // Au retour, la liste se rafraîchit : ce qu'on vient de reposer disparaît.
  useFocusEffect(
    useCallback(() => {
      if (classeId) liste.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId]),
  );

  const activites = liste.donnees ?? [];

  return (
    <SousEcran titre={L.titre} sousTitre={L.sousTitre(activites.length)} chargement={liste.chargement}>
      {liste.erreur ? <Alerte message={L.erreur} /> : null}

      {activites.length === 0 && !liste.erreur ? (
        <View style={styles.vide}>
          <Tuile icone="calendar" moment="recreation" taille={48} />
          <Text style={styles.videTitre}>{L.vide}</Text>
          <Text style={styles.videAide}>{L.videAide}</Text>
        </View>
      ) : (
        activites.map((a) => {
          const detail = [
            a.type === 'workshop' ? L.atelier : null,
            a.attendus === 0 ? L.sansAttendu : null,
          ]
            .filter(Boolean)
            .join(' · ');
          return (
            <LigneReplanifier
              key={a.id}
              activiteId={a.id}
              titre={a.titre}
              detail={detail}
              classeId={classeId}
              onReplanifie={() => liste.recharger()}
            />
          );
        })
      )}
    </SousEcran>
  );
}

/**
 * Une activité à replanifier : sa ligne, et sous elle le sélecteur déplié quand
 * on la tape. Chaque ligne porte son propre état (semaine, jour, moment) : elles
 * ne se marchent pas dessus.
 */
function LigneReplanifier({
  activiteId,
  titre,
  detail,
  classeId,
  onReplanifie,
}: {
  activiteId: string;
  titre: string;
  detail: string;
  classeId: string | null;
  onReplanifie: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);

  const [ouvert, setOuvert] = useState(false);
  const [semaine, setSemaine] = useState(0);
  const [date, setDate] = useState<string | null>(null);
  // `null` = rien de choisi ; sinon le créneau retenu (ou `{ creneauId: null }`
  // pour « sans moment précis », un choix explicite et valable).
  const [choix, setChoix] = useState<{ creneauId: string | null } | null>(null);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState(false);

  const lundiISO = useMemo(() => decalerISO(lundiISOLocal(), semaine * 7), [semaine]);
  const jours = useMemo(() => JOURS.map((i) => decalerISO(lundiISO, i)), [lundiISO]);

  // Les créneaux ne se chargent qu'une fois le sélecteur ouvert, et par semaine.
  const creneaux = useRequete(() => creneauxDe(classeId!, lundiISO), [classeId, lundiISO], {
    actif: ouvert && !!classeId,
  });

  const creneauxDuJour = useMemo(
    () =>
      date
        ? (creneaux.donnees ?? [])
            .filter((cr) => cr.jour === dowDe(date))
            .sort((x, y) => x.debut.localeCompare(y.debut))
        : [],
    [creneaux.donnees, date],
  );

  function basculer() {
    setErreur(false);
    setOuvert((v) => !v);
  }

  function choisirJour(iso: string) {
    setDate(iso);
    // Un moment appartient à un jour : changer de jour efface le choix.
    setChoix(null);
  }

  const estChoisi = (creneauId: string | null) => choix !== null && choix.creneauId === creneauId;

  async function reposer() {
    if (!date || !choix || occupe) return;
    setErreur(false);
    setOccupe(true);
    try {
      await replanifierActivite({ activiteId, date, creneauId: choix.creneauId });
      // L'activité quitte le vivier : on referme et on laisse la liste se
      // rafraîchir, ce qui la fait disparaître d'ici.
      setOuvert(false);
      onReplanifie();
    } catch {
      setErreur(true);
      setOccupe(false);
    }
  }

  return (
    <Carte compacte>
      <Pressable
        accessibilityRole="button"
        accessibilityState={{ expanded: ouvert }}
        accessibilityLabel={`${titre}${detail ? `, ${detail}` : ''}, replanifier`}
        onPress={basculer}>
        <View style={styles.ligne}>
          <Tuile icone="rotate-ccw" moment="sortie" />
          <View style={styles.corps}>
            <Text style={texte.corps}>{titre}</Text>
            {detail ? <Text style={texte.discret}>{detail}</Text> : null}
          </View>
          <Feather name={ouvert ? 'chevron-down' : 'chevron-right'} size={20} color={c.nonRattache} />
        </View>
      </Pressable>

      {ouvert ? (
        <View style={styles.selecteur}>
          {erreur ? <Alerte message={L.erreurReposer} /> : null}

          {/* Le jour. */}
          <Text style={styles.label}>{L.choisirJour}</Text>
          <View style={styles.navSemaine}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={L.precedente}
              onPress={() => {
                setSemaine((s) => s - 1);
                setDate(null);
                setChoix(null);
              }}
              style={styles.fleche}>
              <Feather name="chevron-left" size={20} color={c.encre} />
            </Pressable>
            <Text style={texte.discret}>
              {semaine === 0 ? L.aujourdhui : `${L.semaine} ${libelleSemaine(lundiISO)}`}
            </Text>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={L.suivante}
              onPress={() => {
                setSemaine((s) => s + 1);
                setDate(null);
                setChoix(null);
              }}
              style={styles.fleche}>
              <Feather name="chevron-right" size={20} color={c.encre} />
            </Pressable>
          </View>
          <View style={styles.pastillesJour}>
            {jours.map((iso) => {
              const { jj, num } = jourCourt(iso);
              const actif = iso === date;
              return (
                <Pressable
                  key={iso}
                  accessibilityRole="button"
                  accessibilityState={{ selected: actif }}
                  accessibilityLabel={`${jj} ${num}`}
                  onPress={() => choisirJour(iso)}
                  style={[styles.pastilleJour, actif && styles.pastilleJourActive]}>
                  <Text style={[styles.pastilleJj, actif && styles.pastilleTexteActif]}>{jj}</Text>
                  <Text style={[styles.pastilleNum, actif && styles.pastilleTexteActif]}>{num}</Text>
                </Pressable>
              );
            })}
          </View>

          {/* Le moment : un créneau du jour, ou sans moment précis. Tant qu'aucun
              jour n'est choisi, on invite d'abord à en choisir un. */}
          {date ? (
            <>
              <Text style={[styles.label, styles.labelMoment]}>{L.choisirMoment}</Text>
              {creneauxDuJour.length === 0 ? (
                <Text style={texte.discret}>{L.sansCreneau}</Text>
              ) : (
                creneauxDuJour.map((cr) => (
                  <MomentRangee
                    key={cr.id}
                    creneau={cr}
                    choisi={estChoisi(cr.id)}
                    onChoisir={() => setChoix({ creneauId: cr.id })}
                  />
                ))
              )}

              {/* « Sans moment précis » : une date sans créneau, toujours possible. */}
              <Pressable
                accessibilityRole="button"
                accessibilityState={{ selected: estChoisi(null) }}
                accessibilityLabel={L.sansMoment}
                onPress={() => setChoix({ creneauId: null })}
                style={[styles.moment, estChoisi(null) && styles.momentChoisi]}>
                <Tuile icone="clock" />
                <Text style={styles.momentTexte}>{L.sansMoment}</Text>
                {estChoisi(null) ? <Feather name="check" size={18} color={c.actif} /> : null}
              </Pressable>
            </>
          ) : null}

          <View style={styles.action}>
            <BoutonPrincipal
              libelle={L.reposer}
              onPress={() => void reposer()}
              occupe={occupe}
              inactif={choix === null || occupe}
            />
          </View>
        </View>
      ) : null}
    </Carte>
  );
}

/** Une rangée de créneau sélectionnable, teintée de son moment. */
function MomentRangee({
  creneau,
  choisi,
  onChoisir,
}: {
  creneau: Creneau;
  choisi: boolean;
  onChoisir: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityState={{ selected: choisi }}
      accessibilityLabel={`${creneau.debut} ${creneau.libelle}`}
      onPress={onChoisir}
      style={[styles.moment, choisi && styles.momentChoisi]}>
      {creneau.moment ? (
        <Tuile icone={ICONE_MOMENT[creneau.moment]} moment={creneau.moment} />
      ) : (
        <Tuile icone="clock" />
      )}
      <View style={styles.momentCorps}>
        <Text style={texte.corps}>{creneau.libelle || creneau.debut}</Text>
        <Text style={texte.discret}>
          {creneau.debut}
          {creneau.fin ? ` à ${creneau.fin}` : ''}
        </Text>
      </View>
      {choisi ? <Feather name="check" size={18} color={c.actif} /> : null}
    </Pressable>
  );
}

