import { Feather } from '@expo/vector-icons';
import { useMemo, useState } from 'react';
import { ActivityIndicator, Modal, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import { LigneAttendu } from '@/components/attendus';
import { Champ } from '@/components/formulaire';
import { t } from '@/i18n';
import {
  attendusDeCompetence,
  couvertureDe,
  type Attendu,
  type Classe,
  type Couverture,
} from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * « Parcourir mon programme » : choisir un attendu en DESCENDANT dans le
 * programme de la classe (référentiel → domaine → compétence → attendus), sans
 * avoir à deviner le bon mot (retour Sophie 24/09 : « Cherche à la main… est-il
 * possible de cliquer sur un lien pour sélectionner un attendu du programme ? »).
 *
 * Le programme vient de `couvertureDe` : exactement le périmètre de la classe
 * (niveaux, réseau, compétences exclues retirées), le même que l'onglet
 * Compétences. Les attendus d'une compétence se chargent à son ouverture.
 * Rien n'est coché d'avance ; la feuille reste ouverte pour en cocher plusieurs.
 */
export function ParcourirProgramme({
  classe,
  choisis,
  onBasculer,
  exclus,
}: {
  classe: Classe;
  choisis: string[];
  onBasculer: (attendu: Attendu) => void;
  exclus?: Set<string>;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [ouvert, setOuvert] = useState(false);

  return (
    <>
      <Pressable
        accessibilityRole="button"
        onPress={() => setOuvert(true)}
        style={styles.lien}>
        <Feather name="book-open" size={16} color={c.action[1]} />
        <Text style={styles.lienTexte}>{t.ranger.parcourir}</Text>
      </Pressable>
      {ouvert ? (
        <Feuille
          classe={classe}
          choisis={choisis}
          onBasculer={onBasculer}
          exclus={exclus}
          onFermer={() => setOuvert(false)}
          styles={styles}
          c={c}
        />
      ) : null}
    </>
  );
}

function Feuille({
  classe,
  choisis,
  onBasculer,
  exclus,
  onFermer,
  styles,
  c,
}: {
  classe: Classe;
  choisis: string[];
  onBasculer: (attendu: Attendu) => void;
  exclus?: Set<string>;
  onFermer: () => void;
  styles: ReturnType<typeof creerStyles>;
  c: Couleurs;
}) {
  const programme = useRequete(() => couvertureDe(classe), [classe.id, classe.cycle]);
  const [filtre, setFiltre] = useState('');
  const [domaineOuvert, setDomaineOuvert] = useState<string | null>(null);
  const [competenceOuverte, setCompetenceOuverte] = useState<string | null>(null);

  // Référentiel → domaine → compétences, dans l'ordre du programme. Le filtre
  // porte sur le nom de la compétence ou du domaine.
  const arbre = useMemo(() => {
    const f = filtre.trim().toLocaleLowerCase('fr');
    const refs = new Map<string, Map<string, Couverture[]>>();
    for (const comp of programme.donnees ?? []) {
      if (
        f &&
        !comp.competence.toLocaleLowerCase('fr').includes(f) &&
        !comp.domaine.toLocaleLowerCase('fr').includes(f)
      ) {
        continue;
      }
      const doms = refs.get(comp.referentiel) ?? new Map<string, Couverture[]>();
      const liste = doms.get(comp.domaine) ?? [];
      liste.push(comp);
      doms.set(comp.domaine, liste);
      refs.set(comp.referentiel, doms);
    }
    return [...refs.entries()];
  }, [programme.donnees, filtre]);
  const filtreActif = filtre.trim().length > 0;

  return (
    <Modal visible transparent animationType="fade" onRequestClose={onFermer}>
      <Pressable style={styles.voile} onPress={onFermer}>
        <Pressable style={styles.feuille} onPress={() => {}}>
          {/* En-tête FIXE (charte : la croix reste visible au défilement). */}
          <View style={styles.tete}>
            <Text style={styles.titre}>{t.ranger.parcourirTitre}</Text>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={t.ranger.parcourirFermer}
              onPress={onFermer}
              hitSlop={8}
              style={styles.fermer}>
              <Feather name="x" size={18} color={c.encreDouce} />
            </Pressable>
          </View>
          <Champ
            value={filtre}
            onChangeText={setFiltre}
            placeholder={t.ranger.parcourirFiltre}
            autoCorrect={false}
          />
          {choisis.length ? (
            <Text style={styles.compte}>{t.ranger.parcourirCompte(choisis.length)}</Text>
          ) : null}
          <ScrollView style={styles.liste} keyboardShouldPersistTaps="handled">
            {programme.chargement ? <ActivityIndicator color={c.encreDouce} /> : null}
            {!programme.chargement && !arbre.length ? (
              <Text style={styles.note}>{t.ranger.parcourirVide}</Text>
            ) : null}
            {arbre.map(([referentiel, domaines]) => (
              <View key={referentiel} style={styles.ref}>
                {arbre.length > 1 || referentiel ? (
                  <Text style={styles.refTitre}>{referentiel}</Text>
                ) : null}
                {[...domaines.entries()].map(([domaine, comps]) => {
                  const cleDom = `${referentiel}|${domaine}`;
                  const domOuvert = filtreActif || domaineOuvert === cleDom;
                  return (
                    <View key={cleDom}>
                      <Pressable
                        accessibilityRole="button"
                        accessibilityState={{ expanded: domOuvert }}
                        onPress={() => setDomaineOuvert(domOuvert ? null : cleDom)}
                        style={styles.domaine}>
                        <Text style={styles.domaineTexte}>{domaine || '—'}</Text>
                        <Text style={styles.nombre}>{comps.length}</Text>
                        <Feather name={domOuvert ? 'chevron-up' : 'chevron-down'} size={18} color={c.encre} />
                      </Pressable>
                      {domOuvert
                        ? comps.map((comp) => (
                            <Competence
                              key={comp.competenceId}
                              comp={comp}
                              ouverte={competenceOuverte === comp.competenceId}
                              onOuvrir={() =>
                                setCompetenceOuverte(
                                  competenceOuverte === comp.competenceId ? null : comp.competenceId,
                                )
                              }
                              choisis={choisis}
                              onBasculer={onBasculer}
                              exclus={exclus}
                              styles={styles}
                              c={c}
                            />
                          ))
                        : null}
                    </View>
                  );
                })}
              </View>
            ))}
          </ScrollView>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

function Competence({
  comp,
  ouverte,
  onOuvrir,
  choisis,
  onBasculer,
  exclus,
  styles,
  c,
}: {
  comp: Couverture;
  ouverte: boolean;
  onOuvrir: () => void;
  choisis: string[];
  onBasculer: (attendu: Attendu) => void;
  exclus?: Set<string>;
  styles: ReturnType<typeof creerStyles>;
  c: Couleurs;
}) {
  const attendus = useRequete(() => attendusDeCompetence(comp.competenceId), [comp.competenceId], {
    actif: ouverte,
  });
  const liste = (attendus.donnees ?? []).filter((a) => !exclus?.has(a.id));
  return (
    <View style={styles.competence}>
      <Pressable
        accessibilityRole="button"
        accessibilityState={{ expanded: ouverte }}
        onPress={onOuvrir}
        style={styles.competenceTete}>
        <Text style={styles.competenceTexte}>{comp.competence}</Text>
        <Feather name={ouverte ? 'minus' : 'plus'} size={16} color={c.encreDouce} />
      </Pressable>
      {ouverte ? (
        <View style={styles.attendus}>
          {attendus.chargement ? <ActivityIndicator color={c.encreDouce} /> : null}
          {!attendus.chargement && !liste.length ? (
            <Text style={styles.note}>{t.ranger.parcourirSansAttendu}</Text>
          ) : null}
          {liste.map((a) => (
            <LigneAttendu
              key={a.id}
              attendu={a}
              choisi={choisis.includes(a.id)}
              onBasculer={() => onBasculer(a)}
            />
          ))}
        </View>
      ) : null}
    </View>
  );
}

