import { router, useFocusEffect } from 'expo-router';
import { useCallback, useMemo, useState } from 'react';
import { Pressable, Share, StyleSheet, Text, View } from 'react-native';
import QRCode from 'react-native-qrcode-svg';

import { Avatar } from '@/components/avatar';
import { AvatarChoisir } from '@/components/avatar-choisir';
import { BoutonParrainage } from '@/components/bouton-parrainage';
import { BoutonRond, Carte, Ecran } from '@/components/ecran';
import { TuilesStats } from '@/components/elements';
import { BoutonDiscret } from '@/components/formulaire';
import { MoiActivites } from '@/components/moi-activites';
import { MoiProgres } from '@/components/moi-progres';
import { Onglets } from '@/components/onglets';
import { t } from '@/i18n';
import { useAvatar } from '@/lib/avatar';
import { monCodeInvitation, monProfil, statsProfil } from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * « Moi » : le profil d'effet maître de l'enseignante, l'analogie du profil
 * Strava (en-tête + Progrès / Activités).
 *
 * 🚨 **Ce n'est plus une liste de réglages.** Tout ce qui se règle est parti
 * dans « Réglages » (l'écrou en haut à droite). Le défaut à éviter est celui de
 * `/plus` dans l'app héritée : un onglet fourre-tout attire tout ce qui n'a pas
 * de maison et devient inutilisable. Ici, « Moi » MONTRE (ce que je porte, ma
 * progression, ce que j'ai créé) et ne compare jamais ; « Réglages » RÈGLE. Deux
 * maisons, deux gestes.
 */
type Sous = 'progres' | 'activites';

export default function Vous() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [sous, setSous] = useState<Sous>('progres');
  const [qrOuvert, setQrOuvert] = useState(false);
  const [choixAvatarOuvert, setChoixAvatarOuvert] = useState(false);

  const profil = useRequete(monProfil, []);
  const stats = useRequete(statsProfil, []);
  const code = useRequete(monCodeInvitation, []);
  const avatarValeur = useAvatar();

  // L'en-tête se rafraîchit au retour sur l'onglet : un élève ajouté, une
  // activité créée, un lien de collègue accepté ailleurs doivent s'y voir.
  useFocusEffect(
    useCallback(() => {
      profil.recharger();
      stats.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []),
  );

  const nom = profil.donnees?.nom ?? t.moi.sansNom;
  const monCode = code.donnees ?? null;

  // Le QR porte `educooo://c/<code>` : l'appareil photo du téléphone l'ouvre
  // sans qu'on embarque de scanner. Au tap, il ouvre le partage natif, pour
  // envoyer le code à distance. Même geste et même flux que dans Groupes.
  async function partager() {
    if (!monCode) return;
    await Share.share({ message: t.groupes.inviteTexte(monCode) }).catch(() => null);
  }

  return (
    <Ecran
      titre={t.vous.titre}
      actions={
        <>
          {/* L'appât de parrainage, à gauche de l'écrou (retour Valentin 24/08). */}
          <BoutonParrainage variant="pastille" />
          <BoutonRond
            icone="settings"
            libelle={t.moi.reglages}
            onPress={() => router.push('/vous/reglages')}
          />
        </>
      }>
      {/* L'en-tête profil : l'avatar, le nom, trois chiffres, et les gestes. */}
      <Carte>
        <View style={styles.enteteProfil}>
          {/* L'avatar est tactile : il ouvre le choix (preset Cloudy ou photo). */}
          <Avatar
            valeur={avatarValeur}
            taille={64}
            onPress={() => setChoixAvatarOuvert(true)}
            libelle={t.moi.avatar.changer}
          />
          <View style={styles.enteteTexte}>
            <Text style={styles.nom} numberOfLines={1}>
              {nom}
            </Text>
            <BoutonDiscret
              libelle={t.moi.avatar.changer}
              onPress={() => setChoixAvatarOuvert(true)}
            />
          </View>
        </View>

        <TuilesStats
          items={[
            { valeur: stats.donnees?.eleves ?? 0, libelle: t.moi.statEleves, moment: 'accueil' },
            {
              valeur: stats.donnees?.activites ?? 0,
              libelle: t.moi.statActivites,
              moment: 'ateliers',
            },
            {
              valeur: stats.donnees?.collegues ?? 0,
              libelle: t.moi.statCollegues,
              moment: 'social',
            },
          ]}
        />

        <View style={styles.actions}>
          <View style={styles.actionMoitie}>
            <BoutonDiscret libelle={t.moi.partagerQr} onPress={() => setQrOuvert((v) => !v)} />
          </View>
          <View style={styles.actionMoitie}>
            <BoutonDiscret libelle={t.moi.modifier} onPress={() => router.push('/vous/reglages')} />
          </View>
        </View>

        {qrOuvert && monCode ? (
          <View style={styles.qr}>
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={t.groupes.qrPartager}
              onPress={() => void partager()}
              style={styles.cadreQr}>
              <QRCode
                value={`educooo://c/${monCode}`}
                size={148}
                color={c.encre}
                backgroundColor={c.surface}
              />
            </Pressable>
            <Text style={styles.code}>{monCode}</Text>
            <Text style={styles.qrAide}>{t.moi.qrAide}</Text>
          </View>
        ) : null}
      </Carte>

      {/* Les deux sous-vues, comme les onglets d'un profil Strava. */}
      <Onglets
        options={[
          { id: 'progres' as Sous, libelle: t.moi.ongletProgres },
          { id: 'activites' as Sous, libelle: t.moi.ongletActivites },
        ]}
        choisi={sous}
        onChoisir={setSous}
      />

      {sous === 'progres' ? <MoiProgres /> : <MoiActivites />}

      {/* Le choix d'avatar : presets Cloudy en grille + « Ma photo ». Plus besoin
          de recharger à la main : les setters d'avatar poussent la nouvelle valeur
          dans le store réactif global, donc l'aperçu ici ET tous les en-têtes se
          rafraîchissent seuls. */}
      <AvatarChoisir
        visible={choixAvatarOuvert}
        valeurActuelle={avatarValeur}
        onFermer={() => setChoixAvatarOuvert(false)}
        onChange={() => {}}
      />
    </Ecran>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    enteteProfil: { flexDirection: 'row', alignItems: 'center', gap: espace.md },
    enteteTexte: { flex: 1, gap: espace.xs },
    nom: { fontFamily: police.titre, fontSize: 22, color: c.encre, letterSpacing: -0.4 },
    actions: { flexDirection: 'row', gap: espace.sm },
    actionMoitie: { flex: 1 },
    qr: { alignItems: 'center', gap: espace.sm, marginTop: espace.xs },
    cadreQr: {
      padding: espace.md,
      borderRadius: rayon.bloc,
      backgroundColor: c.surface,
      borderWidth: 1,
      borderColor: c.bord,
    },
    code: { fontFamily: police.accent, fontSize: 24, letterSpacing: 4, color: c.encre },
    qrAide: {
      fontFamily: police.corps,
      fontSize: 13,
      lineHeight: 19,
      color: c.encreDouce,
      textAlign: 'center',
    },
  });
