import { useMemo } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { espace, police, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Des onglets soulignés, en haut d'un écran.
 *
 * 🔑 POURQUOI PAS DES PASTILLES
 *
 * Les pastilles servent à choisir une valeur dans un formulaire : un niveau, un
 * moment, une modalité. Les onglets servent à changer de contenu. Utiliser les
 * mêmes boutons pour les deux gestes brouille ce que l'app promet quand on
 * tape.
 *
 * Le défaut se voyait dans Groupes : une rangée de pastilles pour choisir la
 * section, puis une deuxième rangée de pastilles à l'intérieur pour choisir
 * dans la section. Deux rangées identiques empilées, dont rien ne disait
 * laquelle commandait l'autre.
 *
 * ⚠️ Un seul niveau d'onglets par écran, jamais deux. Si le contenu d'un onglet
 * a lui-même deux parties, ce sont des sections dans un seul défilement, pas
 * des sous-onglets : « une progression, pas une juxtaposition ».
 */
export function Onglets<T extends string>({
  options,
  choisi,
  onChoisir,
}: {
  options: { id: T; libelle: string }[];
  choisi: T;
  onChoisir: (id: T) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    // Le sélecteur d'onglets prend TOUTE la largeur, colonnes de largeur égale,
    // libellés centrés (retour Valentin 24/08). Plus de défilement horizontal :
    // les onglets se répartissent l'écran à parts égales.
    <View style={styles.barre}>
      {options.map((o) => {
        const actif = o.id === choisi;
        return (
          <Pressable
            key={o.id}
            accessibilityRole="tab"
            accessibilityState={{ selected: actif }}
            accessibilityLabel={o.libelle}
            onPress={() => onChoisir(o.id)}
            style={styles.onglet}>
            {/* Le libellé et son trait sont groupés, centrés dans la colonne : le
                trait épouse la largeur du libellé, pas toute la colonne. */}
            <View style={styles.groupe}>
              <Text style={[styles.libelle, actif && styles.libelleActif]} numberOfLines={1}>
                {o.libelle}
              </Text>
              {/* Le trait est toujours là, transparent quand l'onglet dort :
                  sinon le texte saute d'un pixel au changement d'onglet. */}
              <View style={[styles.trait, actif && styles.traitActif]} />
            </View>
          </Pressable>
        );
      })}
    </View>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  barre: {
    flexDirection: 'row',
    borderBottomWidth: 1,
    borderBottomColor: c.bord,
    marginBottom: espace.sm,
  },
  // Le trait actif se superpose à la ligne grise du bas (retour Valentin 24/08) :
  // plus de paddingBottom qui creusait un écart, et le trait déborde d'un pixel
  // pour couvrir la bordure grise. La barre gagne en hauteur.
  onglet: { flex: 1, alignItems: 'center', paddingTop: espace.sm },
  groupe: { alignItems: 'center', gap: espace.xs },
  libelle: { fontFamily: police.accent, fontSize: 16, color: c.nonRattache },
  libelleActif: { color: c.encre },
  trait: {
    height: 2,
    alignSelf: 'stretch',
    backgroundColor: 'transparent',
    borderRadius: 1,
    marginBottom: -1,
  },
  traitActif: { backgroundColor: c.actif },
});
