import { useCallback, useMemo } from 'react';
import { ScrollView, StyleSheet, Text, View } from 'react-native';
import { useFocusEffect } from 'expo-router';

import { CoachMark } from '@/components/coachmark';
import { Carte, EnteteSection } from '@/components/ecran';
import { Alerte } from '@/components/formulaire';
import { TuilesStats } from '@/components/elements';
import { Trophee } from '@/components/trophee';
import { t } from '@/i18n';
import {
  CANAUX,
  nombreActivitesCompletees,
  repartitionCanaux,
  resumeSemaine,
  type Canal,
  type RepartitionCanaux,
} from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

// Le manifeste, source unique des paliers. Import relatif (comme les assets de
// Cloudy) : le projet n'a pas d'alias Metro pour `assets/`.
import manifest from '../../assets/trophees/manifest.json';

/** Les paliers de trophées, dans l'ordre. Source unique : le manifeste. */
const PALIERS: number[] = manifest.paliers;

/**
 * Le canal dominant et une suggestion pour varier, calculés sur la répartition.
 *
 * 🔑 Le miroir n'est PAS un jugement. Il dit une part et ouvre une porte. Le
 * dominant se cherche parmi les quatre vrais canaux (jamais « non précisé », qui
 * n'est pas une manière d'enseigner). La suggestion est le canal réel le MOINS
 * travaillé, hors dominant : on pousse doucement vers l'équilibre, jamais vers
 * un reproche. `null` quand rien n'a encore été clôturé avec un canal.
 */
function miroirDe(
  r: RepartitionCanaux,
): { pourcent: number; dominant: Canal; suggestion: Canal } | null {
  const total = CANAUX.reduce((s, c) => s + r[c], 0) + r.non_precise;
  const avecCanal = CANAUX.reduce((s, c) => s + r[c], 0);
  if (total === 0 || avecCanal === 0) return null;

  // Le plus travaillé, en gardant l'ordre de CANAUX pour départager les égalités.
  const dominant = CANAUX.reduce((meilleur, c) => (r[c] > r[meilleur] ? c : meilleur), CANAUX[0]);
  // La suggestion : le moins travaillé des autres, même règle de départage.
  const autres = CANAUX.filter((c) => c !== dominant);
  const suggestion = autres.reduce((moins, c) => (r[c] < r[moins] ? c : moins), autres[0]);

  return { pourcent: Math.round((r[dominant] / total) * 100), dominant, suggestion };
}

export function MoiProgres() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);

  const canaux = useRequete(repartitionCanaux, []);
  const completees = useRequete(nombreActivitesCompletees, []);
  const semaine = useRequete(resumeSemaine, []);

  // On rafraîchit au retour sur l'onglet : une activité clôturée entre-temps
  // doit se voir sans quitter l'app.
  useFocusEffect(
    useCallback(() => {
      canaux.recharger();
      completees.recharger();
      semaine.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []),
  );

  const repartition = canaux.donnees;
  const miroir = repartition ? miroirDe(repartition) : null;
  const totalCanaux = repartition
    ? CANAUX.reduce((s, k) => s + repartition[k], 0) + repartition.non_precise
    : 0;
  const maxCanal = repartition
    ? Math.max(1, ...CANAUX.map((k) => repartition[k]), repartition.non_precise)
    : 1;
  const faites = completees.donnees ?? 0;

  return (
    <>
      {/* Le mot d'aide, une seule fois : le miroir aide à varier, il ne classe pas. */}
      <CoachMark id="progres" message={t.coach.progres} pose="serenite" />

      {/* Ta semaine : une lecture calme de ce qui a été clôturé. */}
      <EnteteSection titre={t.moi.semaineTitre} />
      <Carte>
        {semaine.erreur ? (
          <Alerte message={semaine.erreur} />
        ) : (semaine.donnees?.seances ?? 0) === 0 ? (
          <Text style={texte.discret}>{t.moi.semaineVide}</Text>
        ) : (
          <TuilesStats
            items={[
              {
                valeur: semaine.donnees?.seances ?? 0,
                libelle: t.moi.semaineSeances(semaine.donnees?.seances ?? 0),
                moment: 'recreation',
              },
              {
                valeur: semaine.donnees?.competences ?? 0,
                libelle: t.moi.semaineCompetences(semaine.donnees?.competences ?? 0),
                moment: 'dirigees',
              },
            ]}
          />
        )}
      </Carte>

      {/* La répartition des canaux, puis le miroir. */}
      <EnteteSection titre={t.moi.canauxTitre} />
      <Carte>
        {canaux.erreur ? (
          <Alerte message={canaux.erreur} />
        ) : totalCanaux === 0 ? (
          <Text style={texte.discret}>{t.moi.canauxVide}</Text>
        ) : (
          <>
            <View style={styles.barres}>
              {[...CANAUX, 'non_precise' as const].map((cle) => {
                const valeur = repartition ? repartition[cle] : 0;
                const part = valeur / maxCanal;
                const gris = cle === 'non_precise';
                return (
                  <View key={cle} style={styles.ligneBarre}>
                    <Text style={styles.barreLibelle} numberOfLines={1}>
                      {t.canaux[cle]}
                    </Text>
                    <View style={styles.piste}>
                      <View
                        style={[
                          styles.remplissage,
                          {
                            width: `${Math.max(part * 100, valeur > 0 ? 4 : 0)}%`,
                            backgroundColor: gris ? c.nonRattache : c.action[0],
                          },
                        ]}
                      />
                    </View>
                    <Text style={styles.barreValeur}>{valeur}</Text>
                  </View>
                );
              })}
            </View>

            {miroir ? (
              <View style={styles.miroir}>
                <Text style={styles.miroirTexte}>
                  {t.moi.miroir(
                    miroir.pourcent,
                    t.moi.canalFragment[miroir.dominant],
                    t.moi.canalFragment[miroir.suggestion],
                  )}
                </Text>
              </View>
            ) : null}
          </>
        )}
      </Carte>

      {/* La collection de trophées d'étape. */}
      <EnteteSection titre={t.moi.tropheesTitre} />
      <Carte>
        <Text style={texte.discret}>{t.moi.tropheesSousTitre(faites)}</Text>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.trophees}>
          {PALIERS.map((palier) => (
            <View key={palier} style={styles.trophee}>
              <Trophee palier={palier} obtenu={faites >= palier} taille={82} />
            </View>
          ))}
        </ScrollView>
      </Carte>
    </>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    barres: { gap: espace.sm },
    ligneBarre: { flexDirection: 'row', alignItems: 'center', gap: espace.sm },
    barreLibelle: { fontFamily: police.accent, fontSize: 13, color: c.encreDouce, width: 96 },
    piste: {
      flex: 1,
      height: 10,
      borderRadius: 5,
      backgroundColor: c.fond,
      overflow: 'hidden',
    },
    remplissage: { height: 10, borderRadius: 5 },
    barreValeur: {
      fontFamily: police.titre,
      fontSize: 14,
      color: c.encre,
      width: 28,
      textAlign: 'right',
    },
    miroir: {
      marginTop: espace.md,
      padding: espace.md,
      borderRadius: rayon.bloc,
      backgroundColor: c.actionTeinte,
    },
    miroirTexte: { fontFamily: police.accent, fontSize: 15, lineHeight: 22, color: c.encre },
    trophees: { gap: espace.sm, paddingVertical: espace.sm, paddingRight: espace.md },
    trophee: { alignItems: 'center' },
  });
