import AsyncStorage from '@react-native-async-storage/async-storage';

/**
 * La file d'attente durable des observations captées hors-ligne.
 *
 * Périmètre volontairement étroit : le filet minimal avant lancement. On ne
 * range pas, on ne supprime pas, on ne synchronise pas le reste. On garantit une
 * seule chose, mais complètement : **une observation captée sans réseau n'est
 * jamais perdue**. Elle attend ici, dans le stockage, et repart au premier
 * retour du réseau.
 *
 * Un simple tableau JSON persisté suffit largement au volume (quelques
 * observations par jour de classe, jamais des milliers). Pas de base locale, pas
 * d'ORM : ce fichier ne fait QUE persister et rendre. L'insertion réelle reste
 * dans `donnees.ts`, seule couche autorisée à parler à Supabase.
 */

const CLE = 'educooo:file:observations';

/**
 * La ligne exacte à insérer dans `observations`, en noms de base (snake_case)
 * pour que le rejeu soit un `insert` direct sans retraduction. L'`id` est généré
 * côté client : c'est lui qui rend le rejeu **idempotent** (même id → conflit de
 * clé primaire ignoré si l'observation a déjà été insérée).
 */
export type ObservationEnAttente = {
  id: string;
  classroom_id: string;
  author_id: string;
  type: 'observation';
  raw_text: string;
  status: 'pending';
  linked_student_id: string | null;
  linked_activity_id: string | null;
  /** Instant de capture (horloge client), pas de rejeu : c'est le moment vrai. */
  created_at: string;
};

/**
 * Un UUID v4 généré côté client. `Math.random` suffit ici : l'identifiant n'a
 * pas besoin d'être cryptographiquement imprévisible, seulement d'être unique
 * pour servir de clé d'idempotence. La probabilité de collision est négligeable
 * au volume d'une classe, et ça évite d'ajouter une dépendance native de crypto.
 */
export function genererUuid(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

/**
 * Toute mutation passe par cette chaîne de promesses, pour qu'un `enfiler` et un
 * `retirer` concurrents (capture pendant un rejeu, par exemple) ne s'écrasent pas
 * l'un l'autre en relisant tous les deux la même version d'avant. Simple, mais
 * suffisant pour un seul appareil.
 */
let verrou: Promise<unknown> = Promise.resolve();
function enSerie<T>(action: () => Promise<T>): Promise<T> {
  const suivant = verrou.then(action, action);
  // On garde la chaîne vivante même si une action échoue, sans propager le rejet.
  verrou = suivant.catch(() => undefined);
  return suivant;
}

/** Le contenu de la file, dans l'ordre de capture. Tolère un stockage corrompu. */
export async function lireFileObservations(): Promise<ObservationEnAttente[]> {
  try {
    const brut = await AsyncStorage.getItem(CLE);
    if (!brut) return [];
    const parse = JSON.parse(brut);
    return Array.isArray(parse) ? (parse as ObservationEnAttente[]) : [];
  } catch {
    // Un JSON illisible ne doit pas faire tomber l'app : on repart d'une file
    // vide plutôt que de propager une erreur de parsing au chemin de capture.
    return [];
  }
}

/** Ajoute une observation en fin de file. */
export async function enfilerObservation(obs: ObservationEnAttente): Promise<void> {
  await enSerie(async () => {
    const file = await lireFileObservations();
    file.push(obs);
    await AsyncStorage.setItem(CLE, JSON.stringify(file));
  });
}

/** Retire une observation de la file par son id (au succès du rejeu). */
export async function retirerDeFile(id: string): Promise<void> {
  await enSerie(async () => {
    const file = await lireFileObservations();
    const restant = file.filter((o) => o.id !== id);
    if (restant.length !== file.length) await AsyncStorage.setItem(CLE, JSON.stringify(restant));
  });
}

/** Le nombre d'observations en attente d'envoi. */
export async function tailleFile(): Promise<number> {
  return (await lireFileObservations()).length;
}
