import { Feather } from '@expo/vector-icons';
import { router, useFocusEffect, useLocalSearchParams } from 'expo-router';
import { useCallback, useMemo, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { Carte } from '@/components/ecran';
import { type Moment, Tuile } from '@/components/elements';
import { Alerte } from '@/components/formulaire';
import { Onglets } from '@/components/onglets';
import { SousEcran } from '@/components/sous-ecran';
import { VignettesMedias } from '@/components/vignettes-medias';
import { t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import {
  brouillonsDe,
  listeActivites,
  observationsDe,
  projetsDe,
  type ActiviteListe,
  type Observation,
  type Projet,
} from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * La boîte de réception, en écran à TROIS onglets (retour Valentin 24/08) :
 * Leçons, Observations, Projets. Elle remplace le petit menu à deux lignes.
 *
 * 🔑 Un seul niveau d'onglets soulignés (la charte) : le sous-découpage de deux
 * onglets (Observations = à ranger / historique ; Projets = projets / brouillons)
 * se fait avec un petit sélecteur segmenté, visuellement différent, pour qu'on ne
 * confonde pas les deux niveaux.
 *
 * Le « + » de l'en-tête est contextuel : il crée une leçon sur l'onglet Leçons,
 * une observation sur l'onglet Observations, et disparaît sur Projets (on y crée
 * un projet depuis l'écran projet dédié).
 */
type Onglet = 'lecons' | 'observations' | 'projets';

export default function Boite() {
  const { tab } = useLocalSearchParams<{ tab?: string }>();
  const depart: Onglet =
    tab === 'lecons' || tab === 'observations' || tab === 'projets' ? tab : 'observations';
  const [onglet, setOnglet] = useState<Onglet>(depart);

  return (
    <SousEcran
      titre={t.boite.titre}
      actions={
        onglet === 'lecons' ? (
          <BoutonPlus
            libelle={t.boite.nouvelleLecon}
            moment="dirigees"
            onPress={() => router.push('/activite/nouvelle')}
          />
        ) : onglet === 'observations' ? (
          <BoutonPlus
            libelle={t.boite.nouvelleObservation}
            moment="accueil"
            onPress={() => router.push('/capter-vite')}
          />
        ) : (
          <BoutonPlus
            libelle={t.projet.ajouter}
            moment="ateliers"
            onPress={() => router.push('/projet')}
          />
        )
      }>
      <Onglets
        options={[
          { id: 'lecons' as Onglet, libelle: t.boite.ongletLecons },
          { id: 'observations' as Onglet, libelle: t.boite.ongletObservations },
          { id: 'projets' as Onglet, libelle: t.boite.ongletProjets },
        ]}
        choisi={onglet}
        onChoisir={setOnglet}
      />

      {onglet === 'lecons' ? <PanneauLecons /> : null}
      {onglet === 'observations' ? <PanneauObservations /> : null}
      {onglet === 'projets' ? <PanneauProjets /> : null}
    </SousEcran>
  );
}

/**
 * Le « + » d'en-tête : une pastille ronde COLORÉE selon l'action (retour Valentin
 * 24/08). Chaque action principale a sa couleur, pour que l'enseignante crée son
 * automatisme : leçon = violet (dirigées), observation = bleu (accueil), projet =
 * jaune (ateliers). La même couleur habille les lignes d'action ailleurs.
 */
function BoutonPlus({
  libelle,
  moment,
  onPress,
}: {
  libelle: string;
  moment: Moment;
  onPress: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={libelle}
      onPress={onPress}
      style={[styles.plus, { backgroundColor: c.moment[moment] }]}>
      <Feather name="plus" size={20} color={c.surface} />
    </Pressable>
  );
}

/** Le sélecteur de sous-vue (2 options), différent des onglets soulignés. */
function SousSegment<T extends string>({
  options,
  choisi,
  onChoisir,
}: {
  options: { id: T; libelle: string }[];
  choisi: T;
  onChoisir: (id: T) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.segments}>
      {options.map((o) => {
        const actif = o.id === choisi;
        return (
          <Pressable
            key={o.id}
            accessibilityRole="button"
            accessibilityState={{ selected: actif }}
            accessibilityLabel={o.libelle}
            onPress={() => onChoisir(o.id)}
            style={[styles.segment, actif && styles.segmentActif]}>
            <Text style={[styles.segmentTexte, actif && styles.segmentTexteActif]}>{o.libelle}</Text>
          </Pressable>
        );
      })}
    </View>
  );
}

/** Onglet Leçons : toutes les leçons de la classe, filtrables à faire / fait. */
function PanneauLecons() {
  const texte = useTexte();
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;
  const [filtre, setFiltre] = useState<'toutes' | 'afaire' | 'fait'>('toutes');
  const lecons = useRequete(() => listeActivites({ classeId: classeId!, limite: 200 }), [classeId], {
    actif: !!classeId,
  });
  useFocusEffect(
    useCallback(() => {
      if (classeId) lecons.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId]),
  );

  const toutes = lecons.donnees ?? [];
  // « À faire » = tout ce qui n'est pas clôturé ; « Fait » = clôturé.
  const liste =
    filtre === 'afaire'
      ? toutes.filter((a) => a.statut !== 'completed')
      : filtre === 'fait'
        ? toutes.filter((a) => a.statut === 'completed')
        : toutes;

  return (
    <>
      <SousSegment
        options={[
          { id: 'toutes' as const, libelle: t.boite.filtreToutes },
          { id: 'afaire' as const, libelle: t.boite.filtreAFaire },
          { id: 'fait' as const, libelle: t.boite.filtreFait },
        ]}
        choisi={filtre}
        onChoisir={setFiltre}
      />
      {lecons.erreur ? <Alerte message={t.journal.erreur} /> : null}
      {liste.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{t.boite.leconsVide}</Text>
        </Carte>
      ) : (
        liste.map((a) => <LigneLecon key={a.id} lecon={a} />)
      )}
    </>
  );
}

function LigneLecon({ lecon }: { lecon: ActiviteListe }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const faite = lecon.statut === 'completed';
  const detail = [
    faite ? t.activite.faite : t.activite.aFaire,
    lecon.type === 'workshop' ? t.activite.atelier : null,
    lecon.attendus === 0 ? t.activite.sansAttendu : null,
  ]
    .filter(Boolean)
    .join(' · ');
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${lecon.titre}, ${detail}`}
      onPress={() => router.push({ pathname: '/activite/[id]', params: { id: lecon.id } })}>
      <Carte compacte>
        <View style={styles.ligne}>
          <Tuile icone={faite ? 'check' : 'book'} moment={faite ? 'recreation' : 'dirigees'} />
          <View style={styles.corps}>
            <Text style={texte.corps}>{lecon.titre}</Text>
            <Text style={texte.discret}>{detail}</Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>
    </Pressable>
  );
}

/** Onglet Observations : à ranger / historique. */
function PanneauObservations() {
  const texte = useTexte();
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;
  const [sous, setSous] = useState<'ranger' | 'historique'>('ranger');
  const obs = useRequete(() => observationsDe(classeId!, 200), [classeId], { actif: !!classeId });
  useFocusEffect(
    useCallback(() => {
      if (classeId) obs.recharger();
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId]),
  );

  const toutes = obs.donnees ?? [];
  const aRanger = toutes.filter((o) => o.statut === 'pending');
  const historique = toutes.filter((o) => o.statut !== 'pending');
  const liste = sous === 'ranger' ? aRanger : historique;

  return (
    <>
      <SousSegment
        options={[
          { id: 'ranger' as const, libelle: t.boite.sousARanger },
          { id: 'historique' as const, libelle: t.boite.sousHistorique },
        ]}
        choisi={sous}
        onChoisir={setSous}
      />
      {obs.erreur ? <Alerte message={t.journal.erreur} /> : null}
      {liste.length === 0 ? (
        <Carte>
          <Text style={texte.discret}>{sous === 'ranger' ? t.boite.vide : t.boite.historiqueVide}</Text>
        </Carte>
      ) : (
        liste.map((o) => <LigneObservation key={o.id} observation={o} />)
      )}
    </>
  );
}

function LigneObservation({ observation: o }: { observation: Observation }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const range = o.statut !== 'pending';
  const etat = o.suivi ? t.ranger.suivi : range ? t.boite.rangee : t.etat.nonRattache;
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={o.texte || etat}
      onPress={() => router.push({ pathname: '/ranger/[id]', params: { id: o.id } })}>
      <Carte compacte>
        <View style={styles.ligne}>
          <Tuile
            icone={o.suivi ? 'bookmark' : range ? 'check' : 'edit-3'}
            moment={o.suivi ? 'sortie' : range ? 'recreation' : undefined}
          />
          <View style={styles.corps}>
            {o.texte ? (
              <Text style={texte.corps} numberOfLines={2}>
                {o.texte}
              </Text>
            ) : null}
            <VignettesMedias observationId={o.id} taille={48} />
            <Text style={texte.discret}>{etat}</Text>
          </View>
          {!range ? <Feather name="chevron-right" size={20} color={c.nonRattache} /> : null}
        </View>
      </Carte>
    </Pressable>
  );
}

/** Onglet Projets : projets / brouillons. */
function PanneauProjets() {
  const texte = useTexte();
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;
  const [sous, setSous] = useState<'projets' | 'brouillons'>('projets');
  const projets = useRequete(() => projetsDe(classeId!), [classeId], { actif: !!classeId });
  const brouillons = useRequete(() => brouillonsDe(classeId!), [classeId], { actif: !!classeId });
  useFocusEffect(
    useCallback(() => {
      if (classeId) {
        projets.recharger();
        brouillons.recharger();
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [classeId]),
  );

  const listeProjets = projets.donnees ?? [];
  const draftsActivites = brouillons.donnees?.activites ?? [];
  const draftsObs = brouillons.donnees?.observations ?? [];
  const brouillonsVides = draftsActivites.length === 0 && draftsObs.length === 0;

  return (
    <>
      <SousSegment
        options={[
          { id: 'projets' as const, libelle: t.boite.sousProjets },
          { id: 'brouillons' as const, libelle: t.boite.sousBrouillons },
        ]}
        choisi={sous}
        onChoisir={setSous}
      />
      {sous === 'projets' ? (
        listeProjets.length === 0 ? (
          <Carte>
            <Text style={texte.discret}>{t.boite.projetsVide}</Text>
          </Carte>
        ) : (
          listeProjets.map((p) => <LigneProjet key={p.id} projet={p} />)
        )
      ) : brouillonsVides ? (
        <Carte>
          <Text style={texte.discret}>{t.boite.brouillonsVide}</Text>
        </Carte>
      ) : (
        <>
          {draftsActivites.map((a) => (
            <LigneLecon key={a.id} lecon={a} />
          ))}
          {draftsObs.map((o) => (
            <LigneObservation key={o.id} observation={o} />
          ))}
        </>
      )}
    </>
  );
}

function LigneProjet({ projet }: { projet: Projet }) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const detail = [t.projet.etats[projet.statut], t.projet.avancement(projet.faites, projet.activites)]
    .filter(Boolean)
    .join(' · ');
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={`${projet.titre}, ${detail}`}
      onPress={() => router.push({ pathname: '/projet/[id]', params: { id: projet.id } })}>
      <Carte compacte>
        <View style={styles.ligne}>
          {projet.activites > 0 && projet.faites === projet.activites ? (
            <Tuile icone="check" moment="recreation" />
          ) : projet.activites > 0 ? (
            <Tuile icone="folder" moment="ateliers" />
          ) : (
            <Tuile icone="folder" />
          )}
          <View style={styles.corps}>
            <Text style={texte.corps}>{projet.titre}</Text>
            <Text style={texte.discret}>{detail}</Text>
          </View>
          <Feather name="chevron-right" size={20} color={c.nonRattache} />
        </View>
      </Carte>
    </Pressable>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    plus: {
      width: 38,
      height: 38,
      borderRadius: 19,
      backgroundColor: c.action[1],
      alignItems: 'center',
      justifyContent: 'center',
    },
    segments: { flexDirection: 'row', gap: espace.xs, marginBottom: espace.sm },
    segment: {
      paddingVertical: 6,
      paddingHorizontal: espace.md,
      borderRadius: rayon.pastille,
      borderWidth: 1,
      borderColor: c.bord,
    },
    segmentActif: { backgroundColor: c.encre, borderColor: c.encre },
    segmentTexte: { fontFamily: police.accent, fontSize: 14, color: c.encreDouce },
    segmentTexteActif: { color: c.surface },
    ligne: { flexDirection: 'row', gap: espace.md, alignItems: 'center' },
    corps: { flex: 1, gap: espace.xs },
  });
