import { Feather } from '@expo/vector-icons';
import { router } from 'expo-router';
import { useMemo } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Carte } from '@/components/ecran';
import { Presse } from '@/components/presse';
import { t } from '@/i18n';
import { espace, ombre, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * L'appât de parrainage : un bouton cadeau « Obtiens 10 € » (retour Valentin
 * 24/08, par analogie à un concurrent). Il mène toujours au même endroit —
 * l'onglet Parrainage de Groupes — et se place là où le geste est pertinent :
 * en tête de l'onglet Collègues (variante `carte`) et dans l'en-tête de « Moi »,
 * à gauche de l'écrou (variante `pastille`).
 *
 * Une seule maison pour le parrainage : ce bouton n'affiche rien lui-même, il
 * ouvre le panneau complet (voir `parrainage-panneau`).
 */
function versParrainage() {
  router.push({ pathname: '/groupes', params: { tab: 'parrainage' } });
}

/**
 * L'appât mène par défaut à l'onglet Parrainage de Groupes par navigation. Mais
 * depuis Groupes lui-même, cette navigation vers la route DÉJÀ affichée est un
 * non-évènement : expo-router ne rejoue pas l'onglet courant, le paramètre `tab`
 * ne se propage pas, et le bouton « ne fait rien ». C'est pourquoi Groupes passe
 * son PROPRE `onPress` (bascule d'onglet locale) : le geste marche à coup sûr,
 * sans dépendre d'une navigation vers soi-même.
 */
export function BoutonParrainage({
  variant,
  onPress,
}: {
  variant: 'pastille' | 'carte';
  onPress?: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const action = onPress ?? versParrainage;

  if (variant === 'pastille') {
    return (
      <Presse
        accessibilityRole="button"
        accessibilityLabel={t.parrainage.appat}
        onPress={action}
        style={styles.pastille}>
        <Feather name="gift" size={16} color={c.action[1]} />
        <Text style={styles.pastilleTexte}>{t.parrainage.appat}</Text>
      </Presse>
    );
  }

  return (
    <Carte onPress={action}>
      <View style={styles.carte}>
        <View style={styles.icone}>
          <Feather name="gift" size={20} color={c.action[1]} />
        </View>
        <View style={styles.corps}>
          <Text style={styles.titre}>{t.parrainage.appatCarte}</Text>
          <Text style={styles.aide}>{t.parrainage.appatCarteAide}</Text>
        </View>
        <Feather name="chevron-right" size={20} color={c.nonRattache} />
      </View>
    </Carte>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    // La pastille d'en-tête : compacte, fond miel clair, à côté de l'écrou.
    pastille: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: espace.xs,
      height: 38,
      paddingHorizontal: espace.sm,
      borderRadius: rayon.pastille,
      backgroundColor: c.actionTeinte,
    },
    pastilleTexte: { fontFamily: police.accent, fontSize: 14, color: c.action[1] },
    // La carte : une tuile cadeau, le gain, un chevron.
    carte: { flexDirection: 'row', alignItems: 'center', gap: espace.md },
    icone: {
      width: 38,
      height: 38,
      borderRadius: rayon.tuile,
      backgroundColor: c.actionTeinte,
      alignItems: 'center',
      justifyContent: 'center',
      ...ombre.carte,
    },
    corps: { flex: 1, gap: 2 },
    titre: { fontFamily: police.corps, fontSize: 16, color: c.encre },
    aide: { fontFamily: police.corps, fontSize: 13, color: c.encreDouce },
  });
