import { supabase } from './supabase';

/**
 * Les photos « preuve » d'une activité clôturée : une trace privée pour la
 * direction, montrant que la séance a bien eu lieu. Deux au maximum, dans le
 * même seau privé que les médias d'observation, jamais en public.
 *
 * On reprend TELLE QUELLE la mécanique éprouvée de `media.ts`, parce que le
 * contrat de stockage est identique :
 *  - le chemin commence TOUJOURS par l'uid de la session, relu juste avant
 *    l'upload : c'est la seule source que la protection par ligne ne peut pas
 *    contredire (le seau refuse tout chemin dont le premier segment n'est pas
 *    `auth.uid()`) ;
 *  - l'upload passe par un `ArrayBuffer` et non un `Blob`, parce que le `Blob`
 *    remonte parfois à zéro octet sur React Native et l'upload « réussit » en
 *    écrivant un fichier vide ;
 *  - un horodatage dans le nom de fichier évite d'écraser une photo précédente.
 *
 * Le seau étant privé, on ne stocke jamais d'URL : on signe à la lecture, car
 * une URL signée expire et un lien périmé en base serait mort.
 *
 * Le picker (`choisirPhoto` / `prendrePhoto`) et le type `ImageChoisie` ne sont
 * pas redéfinis ici : on les importe de `media.ts`, pour qu'il n'existe qu'un
 * seul chemin de sélection d'image dans l'app.
 */

import { type ImageChoisie } from './media';

export { choisirPhoto, prendrePhoto, type ImageChoisie } from './media';

const SEAU = 'observation-media';

/** Une photo est-elle celle de la préparation, ou de l'activité réalisée ? */
export type KindMedia = 'preparation' | 'realise';

/** Une ligne de la table `activity_media`, traduite côté app, URL signée incluse. */
export type ActivityMedia = {
  id: string;
  activiteId: string;
  /** Chemin dans le seau, ex. `uid/activity/<id>/photo-1234.jpg`. Sert à signer et à supprimer. */
  storagePath: string;
  /** URL signée à durée limitée, prête à afficher. */
  url: string;
  /** Préparation (jointe à la création) ou réalisé (ajoutée ensuite). */
  kind: KindMedia;
  creeeLe: string;
};

/**
 * L'uid de la session, ou une erreur claire s'il n'y en a pas.
 *
 * On le relit à chaque upload plutôt que de le recevoir en paramètre : c'est la
 * seule source qui ne peut pas mentir, et c'est exactement ce que la protection
 * par ligne vérifiera.
 */
async function uidSession(): Promise<string> {
  const { data, error } = await supabase.auth.getUser();
  if (error) throw error;
  const uid = data.user?.id;
  if (!uid) {
    throw new Error("Tu n'es plus connecté·e : reconnecte-toi pour joindre une photo.");
  }
  return uid;
}

/** Devine l'extension de fichier depuis le MIME ou l'URI. */
function extensionDe(mime: string | null, uri: string, defaut: string): string {
  const parMime: Record<string, string> = {
    'image/jpeg': 'jpg',
    'image/jpg': 'jpg',
    'image/png': 'png',
    'image/webp': 'webp',
    'image/heic': 'heic',
  };
  if (mime && parMime[mime]) return parMime[mime];
  const propre = uri.split('?')[0];
  const point = propre.lastIndexOf('.');
  if (point !== -1 && point > propre.lastIndexOf('/')) {
    const ext = propre.slice(point + 1).toLowerCase();
    if (ext && ext.length <= 5) return ext;
  }
  return defaut;
}

/**
 * Lit un fichier local en `ArrayBuffer`.
 *
 * 🚨 On n'envoie PAS un `Blob` : sur React Native il remonte régulièrement à
 * zéro octet et l'upload « réussit » en écrivant un fichier vide.
 */
async function lireFichier(uri: string): Promise<ArrayBuffer> {
  const reponse = await fetch(uri);
  const donnees = await reponse.arrayBuffer();
  if (!donnees.byteLength) {
    throw new Error("Le fichier est vide : rien n'a été joint.");
  }
  return donnees;
}

const COLONNES = 'id, activity_id, media_type, storage_path, kind, created_at';

type LigneActivityMedia = {
  id: string;
  activity_id: string;
  media_type: string;
  storage_path: string;
  kind: string | null;
  created_at: string;
};

/** Reconnaît un kind connu, 'realise' par défaut (lignes d'avant la colonne). */
function estKind(v: unknown): v is KindMedia {
  return v === 'preparation' || v === 'realise';
}

/** Signe le chemin d'une ligne, ou null si la signature échoue. */
async function signer(
  ligne: LigneActivityMedia,
  dureeSignature: number,
): Promise<ActivityMedia | null> {
  const { data } = await supabase.storage
    .from(SEAU)
    .createSignedUrl(ligne.storage_path, dureeSignature);
  const url = data?.signedUrl;
  if (!url) return null;
  return {
    id: ligne.id,
    activiteId: ligne.activity_id,
    storagePath: ligne.storage_path,
    url,
    kind: estKind(ligne.kind) ? ligne.kind : 'realise',
    creeeLe: ligne.created_at,
  };
}

/**
 * Joint une photo à une activité : upload dans le seau puis ligne en base.
 *
 * L'ordre compte, et il est le même que `joindrePhoto` : on uploade le fichier
 * d'abord ; si l'écriture de la ligne échoue ensuite, on retire le fichier
 * orphelin pour ne pas laisser de déchet. L'inverse laisserait une ligne qui
 * pointe vers rien.
 *
 * Le plafond de deux est tenu par un déclencheur en base : si une troisième
 * photo est tentée, l'insertion échoue et on remonte l'erreur, après avoir
 * retiré le fichier déjà uploadé.
 */
export async function joindrePhotoActivite(
  activiteId: string,
  image: ImageChoisie,
  kind: KindMedia = 'realise',
): Promise<ActivityMedia> {
  const uid = await uidSession();
  const ext = extensionDe(image.mime, image.uri, 'jpg');
  const chemin = `${uid}/activity/${activiteId}/photo-${Date.now()}.${ext}`;

  const donnees = await lireFichier(image.uri);
  const { error: erreurUpload } = await supabase.storage
    .from(SEAU)
    .upload(chemin, donnees, { contentType: image.mime ?? 'image/jpeg', upsert: false });
  if (erreurUpload) throw erreurUpload;

  const { data, error } = await supabase
    .from('activity_media')
    .insert({ activity_id: activiteId, media_type: 'photo', storage_path: chemin, kind })
    .select(COLONNES)
    .single();
  if (error) {
    // La ligne n'a pas pu être écrite (plafond atteint, droits, réseau) : on ne
    // garde pas un fichier fantôme dans le seau.
    await supabase.storage
      .from(SEAU)
      .remove([chemin])
      .catch(() => {});
    throw error;
  }

  const signe = await signer(data, 3600);
  if (signe) return signe;
  // La ligne existe, seule la signature a manqué : on renvoie l'essentiel, la
  // relecture resignera. On ne perd rien, la photo est bien en base.
  return {
    id: data.id,
    activiteId: data.activity_id,
    storagePath: data.storage_path,
    url: '',
    kind: estKind(data.kind) ? data.kind : kind,
    creeeLe: data.created_at,
  };
}

/**
 * Les photos d'une activité, chacune avec une URL signée prête à afficher.
 *
 * Une photo dont la signature échoue est ignorée plutôt que de faire tomber
 * toute la liste : mieux vaut en afficher une sur deux qu'un écran d'erreur.
 */
export async function listerMediasActivite(
  activiteId: string,
  dureeSignature = 3600,
): Promise<ActivityMedia[]> {
  const { data, error } = await supabase
    .from('activity_media')
    .select(COLONNES)
    .eq('activity_id', activiteId)
    .order('created_at', { ascending: true });
  if (error) throw error;

  const signes = await Promise.all((data ?? []).map((ligne) => signer(ligne, dureeSignature)));
  return signes.filter((m): m is ActivityMedia => m !== null);
}

/**
 * Retire une photo : la ligne en base, et le fichier du seau UNIQUEMENT s'il
 * n'est plus référencé par personne.
 *
 * 🔑 Les copies de préparation (copier vers, dupliquer jour/semaine) réutilisent
 * VOLONTAIREMENT le même `storage_path` sans re-téléverser le fichier : une photo
 * de prépa peut donc être pointée par plusieurs lignes. Effacer l'objet du seau
 * dès qu'on retire UNE ligne casserait toutes les autres copies (fichier disparu,
 * `signer()` renvoie null, la photo s'évapore en silence). On compte donc les
 * autres références d'abord, et on ne touche au fichier qu'à la dernière.
 *
 * Quand on efface bien le fichier, on le fait AVANT la ligne : un fichier sans
 * ligne est un déchet invisible, une ligne sans fichier reste réparable.
 */
export async function retirerMediaActivite(media: ActivityMedia): Promise<void> {
  const { count, error: erreurCompte } = await supabase
    .from('activity_media')
    .select('id', { count: 'exact', head: true })
    .eq('storage_path', media.storagePath)
    .neq('id', media.id);
  if (erreurCompte) throw erreurCompte;
  const dernierePlace = !count || count === 0;

  if (dernierePlace) {
    const { error: erreurFichier } = await supabase.storage.from(SEAU).remove([media.storagePath]);
    if (erreurFichier) throw erreurFichier;
  }

  const { error } = await supabase.from('activity_media').delete().eq('id', media.id);
  if (error) throw error;
}
