import { Image } from 'expo-image';
import { router } from 'expo-router';
import { useMemo } from 'react';
import { StyleSheet, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import { Presse } from '@/components/presse';
import { t } from '@/i18n';
import { resoudreAvatar, useAvatar } from '@/lib/avatar';
import { useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * L'avatar de l'enseignant·e, rendu à partir de la valeur brute de son profil.
 *
 * Trois cas, résolus par `resoudreAvatar` :
 *   - une photo perso → l'image, ronde et recadrée au centre ;
 *   - un preset → la pose de Cloudy choisie, dans sa pastille teintée ;
 *   - rien → Cloudy neutre (le même avatar par défaut que l'en-tête d'origine).
 *
 * Avec `onPress`, l'avatar devient un bouton (il ouvre l'espace « Moi »). Sans,
 * c'est un simple élément décoratif (l'aperçu dans l'espace « Moi »).
 */
export function Avatar({
  valeur,
  taille = 38,
  onPress,
  libelle,
}: {
  /** La valeur brute de `profiles.avatar` (`preset:…`, une URL, ou null). */
  valeur: string | null | undefined;
  taille?: number;
  /** Rend l'avatar tactile (bouton). Le libellé décrit alors l'action. */
  onPress?: () => void;
  libelle?: string;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const resolu = resoudreAvatar(valeur);

  const contenu =
    resolu.type === 'photo' ? (
      <Image
        source={{ uri: resolu.url }}
        style={[styles.photo, { width: taille, height: taille, borderRadius: taille / 2 }]}
        contentFit="cover"
        // La photo décore l'en-tête ; l'écran a déjà son titre, et le bouton
        // porte son propre libellé. On ne double pas la voix du lecteur d'écran.
        accessibilityElementsHidden
        importantForAccessibility="no-hide-descendants"
      />
    ) : (
      <Cloudy pose={resolu.type === 'preset' ? resolu.pose : 'neutre'} taille={taille} cercle respire={false} />
    );

  if (!onPress) return contenu;
  return (
    <Presse
      accessibilityRole="button"
      accessibilityLabel={libelle ?? t.moi.ouvrir}
      onPress={onPress}
      style={styles.bouton}>
      {contenu}
    </Presse>
  );
}

/**
 * L'avatar de navigation posé à gauche du titre des écrans d'onglets quand le
 * drapeau `NAV_AVATAR` est ON. Il charge l'avatar courant et, au toucher, ouvre
 * l'espace « Moi/Toi » (`/vous`, route existante — aucune route neuve, donc le
 * type-check `typedRoutes` reste vert).
 *
 * Il suit le store réactif `useAvatar()` : un avatar changé dans « Moi » se voit
 * aussitôt sur TOUS les écrans, pas seulement sur celui d'où on l'a changé.
 */
export function AvatarNav() {
  const valeur = useAvatar();
  return (
    <Avatar
      valeur={valeur}
      taille={38}
      onPress={() => router.push('/vous')}
      libelle={t.moi.ouvrir}
    />
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    bouton: { borderRadius: 999 },
    photo: { backgroundColor: c.actionTeinte },
  });
