/**
 * LA GRILLE DU SEMAINIER : la semaine en grille, distincte du fil du journal.
 *
 * Composant PUR : il reçoit les créneaux, les activités et le lundi de la
 * semaine (le journal les charge déjà et fournit la navigation de semaine). Il
 * ne pousse aucun écran : il vit à l'intérieur de l'onglet Journal, en bascule
 * avec le fil.
 *
 * 📐 Responsive, mesuré au layout : au-delà d'une largeur utile (web plein, ou
 * tablette) la grille jours × créneaux ; en dessous (téléphone) une vue JOUR
 * avec un sélecteur de jour.
 *
 * 🧭 Les LIGNES sont groupées par HEURE de début (pas par libellé) : deux jours
 * peuvent avoir une activité différente à 13:30 sans dédoubler la ligne. Chaque
 * cellule (jour × heure) prend la couleur du moment de SON créneau. Les moments
 * de pause (récré, midi) se posent en bande qui traverse la semaine.
 *
 * 🎯 « Prévu → fait » : `statut === 'completed'` = fait. En tête, un bilan
 * compact d'une ligne.
 */

const JOURS = [1, 2, 3, 4, 5];
const SEUIL_GRILLE = 480;

const ICONE_MOMENT: Record<Moment, keyof typeof Feather.glyphMap> = {
  accueil: 'sunrise',
  ateliers: 'grid',
  dirigees: 'edit-2',
  recreation: 'coffee',
  sortie: 'map-pin',
  social: 'users',
};

/** Les libellés du semainier, bilingues (le cœur visible de la grille était FR pur). */
const STR: Record<Langue, {
  bilanTitre: string;
  bilanVide: string;
  fait: string;
  ajouter: string;
  sansHeure: string;
  aria: {
    fait: (titre: string) => string;
    prevu: (titre: string) => string;
    libre: (jour: string, heure: string) => string;
  };
}> = {
  fr: {
    bilanTitre: 'Prévu → fait',
    bilanVide: 'Rien de prévu',
    fait: 'Fait',
    ajouter: 'Ajouter',
    sansHeure: 'Sans heure',
    aria: {
      fait: (titre) => `${titre}, fait`,
      prevu: (titre) => `${titre}, prévu`,
      libre: (jour, heure) => `${jour}, ${heure}, ajouter une activité`,
    },
  },
  nl: {
    bilanTitre: 'Gepland → gedaan',
    bilanVide: 'Niets gepland',
    fait: 'Gedaan',
    ajouter: 'Toevoegen',
    sansHeure: 'Zonder tijd',
    aria: {
      fait: (titre) => `${titre}, gedaan`,
      prevu: (titre) => `${titre}, gepland`,
      libre: (jour, heure) => `${jour}, ${heure}, een activiteit toevoegen`,
    },
  },
};
const S = STR[langue];

/** Un moment de pause traverse la semaine en bande (récré, midi/repas). */
function estBande(moment: Moment | null, libelle: string): boolean {
  if (moment === 'recreation') return true;
  return /midi|repas|d[îi]ner|d[éeè]jeuner/i.test(libelle);
}

/** L'abrégé d'un jour : { jj: 'LUN', num: '24' }. */
function jourCourt(iso: string): { jj: string; num: string } {
  const [a, m, j] = iso.split('-').map((n) => parseInt(n, 10));
  const d = new Date(a, m - 1, j);
  const loc = langue === 'nl' ? 'nl-BE' : 'fr-BE';
  const jj = d.toLocaleDateString(loc, { weekday: 'short' }).replace('.', '').slice(0, 3);
  return { jj: jj.toLocaleUpperCase(langue), num: String(j) };
}

/** Une ligne de la grille : une HEURE de début, et le créneau de chaque jour. */
type Ligne = {
  debut: string;
  fin: string;
  bande: boolean;
  libelleBande: string;
  momentBande: Moment | null;
  parJour: (Creneau | null)[];
  /**
   * Pour chaque jour, le créneau d'une ligne PRÉCÉDENTE qui déborde sur cette
   * heure (un créneau long comme « Psychomotricité 08:40 → 10:10 »). La case le
   * rend en continuation teintée, pour que le bloc occupe toute sa durée au lieu
   * de laisser un vide sous sa seule ligne de début.
   */
  couvert: (Creneau | null)[];
};

/* ── Déplacer une séance (drag & drop) ── */

/** La clé d'une case déposable : `${date}|${creneauId}`. */
function cleCase(date: string, creneauId: string): string {
  return `${date}|${creneauId}`;
}

type Rect = { x: number; y: number; w: number; h: number };

type Deplacement = {
  /** Enregistre (ou retire) la case déposable sous sa clé, pour la retrouver au dépôt. */
  enregistrer: (cle: string, noeud: View | null) => void;
  /** Prend une photo de la position à l'écran de toutes les cases (au début d'un glissé). */
  mesurer: () => void;
  /** Dépose la séance là où le doigt la lâche, si c'est une autre case. */
  deposer: (absX: number, absY: number, activiteId: string, cleSource: string) => void;
};

const ContexteDeplacement = createContext<Deplacement | null>(null);
const useDeplacement = () => useContext(ContexteDeplacement);

/* ── Vue multi-classes (lecture seule) ── */

/** Une classe telle qu'affichée sur un bloc en vue agrégée : pastille + libellé. */
export type InfoClasseBloc = { abrege: string; couleur: string };

/**
 * La classe d'origine de chaque séance, indexée par `activite.id`. Sert à poser
 * une pastille de distinction sur chaque bloc quand on agrège plusieurs classes.
 * `null` en mono-classe (le défaut), où aucune pastille ne s'affiche : le rendu
 * ne change pas d'un pixel tant qu'on ne fournit pas cette carte.
 */
const ContexteClasses = createContext<Map<string, InfoClasseBloc> | null>(null);
const useClasseBloc = (activiteId: string): InfoClasseBloc | null => {
  const classes = useContext(ContexteClasses);
  return classes?.get(activiteId) ?? null;
};

/**
 * La taxonomie des types d'apprentissage (`ref_learning_types`), fournie une fois
 * par le journal et lue par chaque bloc pour son étiquette. `null` (le défaut) :
 * l'étiquette retombe sur la liste embarquée, elle s'affiche quand même.
 */
const ContexteTypes = createContext<TypeApprentissage[] | undefined>(undefined);
const useTypes = () => useContext(ContexteTypes);

/**
 * Le socle du drag & drop de la grille : il garde une référence vers chaque case
 * déposable, sait les mesurer à l'écran au début d'un glissé, et résout la case
 * visée quand on lâche. Purement additif — sans `onDeplacer`, il ne s'installe
 * pas et la grille reste en simple tap.
 */
function FournisseurDeplacement({
  onDeplacer,
  children,
}: {
  onDeplacer: (activiteId: string, date: string, creneauId: string | null) => void;
  children: React.ReactNode;
}) {
  const refs = useRef(new Map<string, View>());
  const rects = useRef(new Map<string, Rect>());

  const valeur = useMemo<Deplacement>(
    () => ({
      enregistrer: (cle, noeud) => {
        if (noeud) refs.current.set(cle, noeud);
        else {
          refs.current.delete(cle);
          rects.current.delete(cle);
        }
      },
      mesurer: () => {
        refs.current.forEach((noeud, cle) => {
          // measureInWindow rend la position À L'ÉCRAN : robuste au scroll, qu'on
          // relève à chaque début de glissé plutôt que de se fier au layout figé.
          noeud.measureInWindow((x, y, w, h) => {
            if (w > 0 && h > 0) rects.current.set(cle, { x, y, w, h });
          });
        });
      },
      deposer: (absX, absY, activiteId, cleSource) => {
        for (const [cle, r] of rects.current) {
          if (cle === cleSource) continue;
          if (absX >= r.x && absX <= r.x + r.w && absY >= r.y && absY <= r.y + r.h) {
            const [date, creneauId] = cle.split('|');
            onDeplacer(activiteId, date, creneauId || null);
            return;
          }
        }
      },
    }),
    [onDeplacer],
  );

  return (
    <GestureHandlerRootView style={styles_racineGeste}>
      <ContexteDeplacement.Provider value={valeur}>{children}</ContexteDeplacement.Provider>
    </GestureHandlerRootView>
  );
}

const styles_racineGeste = { flex: 0 } as const;

export function GrilleSemaine({
  creneaux,
  activites,
  lundiISO,
  onDeplacer,
  classes,
  types,
  absences = [],
}: {
  creneaux: Creneau[];
  activites: ActiviteListe[];
  lundiISO: string;
  /** Les absences de la prof sur la semaine, affichées sur l'en-tête du jour. */
  absences?: AbsenceProf[];
  /** Déplacer une séance vers une autre case (glisser-déposer, grande grille). */
  onDeplacer?: (activiteId: string, date: string, creneauId: string | null) => void;
  /**
   * Vue MULTI-CLASSES (lecture seule) : `activite.id` → sa classe d'origine, pour
   * poser une pastille de distinction sur chaque bloc. Absent en mono-classe.
   */
  classes?: Map<string, InfoClasseBloc>;
  /**
   * La taxonomie des types d'apprentissage, pour l'étiquette de type des séances
   * de séquence. Absente = repli sur la liste embarquée (l'étiquette s'affiche
   * quand même).
   */
  types?: TypeApprentissage[];
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);

  const [largeur, setLargeur] = useState(0);
  const surLayout = useCallback((e: LayoutChangeEvent) => setLargeur(e.nativeEvent.layout.width), []);
  const grille = largeur >= SEUIL_GRILLE;

  const [jourActif, setJourActif] = useState<number>(() => {
    const d = new Date().getDay();
    return d >= 1 && d <= 5 ? d : 1;
  });

  const dates = useMemo(() => JOURS.map((_, i) => decalerISO(lundiISO, i)), [lundiISO]);

  // Les lignes, groupées par heure de début. Le premier créneau d'un jour à une
  // heure donnée gagne la case (les doublons de la semaine type sont rares).
  const lignes = useMemo<Ligne[]>(() => {
    const parHeure = new Map<string, (Creneau | null)[]>();
    for (const cr of creneaux) {
      let jours = parHeure.get(cr.debut);
      if (!jours) {
        jours = [null, null, null, null, null];
        parHeure.set(cr.debut, jours);
      }
      const idx = cr.jour - 1;
      if (idx >= 0 && idx < 5 && !jours[idx]) jours[idx] = cr;
    }
    const rows: Ligne[] = [];
    for (const [debut, parJour] of parHeure) {
      const presents = parJour.filter(Boolean) as Creneau[];
      if (!presents.length) continue;
      const rep = presents[0];
      rows.push({
        debut,
        fin: rep.fin,
        bande: presents.every((cr) => estBande(cr.moment, cr.libelle)),
        libelleBande: rep.libelle,
        momentBande: rep.moment,
        parJour,
        couvert: [null, null, null, null, null],
      });
    }
    rows.sort((a, b) => a.debut.localeCompare(b.debut));

    // Débordement : pour chaque jour, on suit le créneau en cours et on marque
    // les lignes qu'il traverse (jusqu'à SON heure de fin). Les heures sont en
    // « HH:MM » zéro-padées, donc la comparaison de chaînes vaut celle des
    // horaires. Un créneau à durée nulle ou incohérente ne déborde pas.
    for (let d = 0; d < 5; d++) {
      let actif: Creneau | null = null;
      for (const row of rows) {
        const cell = row.parJour[d];
        if (cell) {
          actif = cell.fin && cell.debut && cell.fin > cell.debut ? cell : null;
        } else if (actif && actif.fin > row.debut) {
          row.couvert[d] = actif;
        } else {
          actif = null;
        }
      }
    }

    return rows;
  }, [creneaux]);

  const actsParCase = useMemo(() => {
    const m = new Map<string, ActiviteListe[]>();
    // Filet : une séance dont le créneau n'est pas dans l'horaire affiché (créneau
    // supprimé, autre semaine, autre parité) remonte « sans heure » au lieu de
    // disparaître. Une leçon en base reste toujours visible.
    const connus = new Set(creneaux.map((c) => c.id));
    for (const a of activites) {
      if (!a.date) continue;
      const k =
        a.creneauId && connus.has(a.creneauId) ? `${a.date}|${a.creneauId}` : `${a.date}|sans`;
      const arr = m.get(k);
      if (arr) arr.push(a);
      else m.set(k, [a]);
    }
    return m;
  }, [activites, creneaux]);

  const aSansHeure = useMemo(() => dates.some((d) => actsParCase.has(`${d}|sans`)), [dates, actsParCase]);

  const bilan = useMemo(() => {
    let total = 0;
    let fait = 0;
    for (const a of activites) {
      if (!a.date) continue;
      // Les activités logistiques (piscine, sortie, visite médicale…) restent
      // affichées dans la grille mais ne comptent pas dans le ratio : le bilan
      // « prévu → fait » ne parle que des leçons.
      if (a.sansCompetences) continue;
      total += 1;
      if (a.statut === 'completed') fait += 1;
    }
    return { total, fait };
  }, [activites]);

  return (
    <ContexteTypes.Provider value={types}>
    <ContexteClasses.Provider value={classes ?? null}>
    <View style={styles.racine}>
      <BilanCompact total={bilan.total} fait={bilan.fait} />

      <View onLayout={surLayout}>
        {largeur === 0 ? null : grille ? (
          // Le glisser-déposer ne s'installe que sur la GRANDE grille (web/tablette),
          // là où déplacer une séance d'une case à l'autre a du sens. Sans
          // `onDeplacer`, la grille reste en simple tap.
          onDeplacer ? (
            <View style={styles.avecCoach}>
              <CoachMark id="grille" message={t.coach.grille} pose="salut" />
              <FournisseurDeplacement onDeplacer={onDeplacer}>
                <Grille lignes={lignes} dates={dates} actsParCase={actsParCase} aSansHeure={aSansHeure} absences={absences} />
              </FournisseurDeplacement>
            </View>
          ) : (
            <Grille lignes={lignes} dates={dates} actsParCase={actsParCase} aSansHeure={aSansHeure} absences={absences} />
          )
        ) : (
          <VueJour
            lignes={lignes}
            dates={dates}
            actsParCase={actsParCase}
            jourActif={jourActif}
            onJour={setJourActif}
            absences={absences}
          />
        )}
      </View>
    </View>
    </ContexteClasses.Provider>
    </ContexteTypes.Provider>
  );
}

/* ── Bilan compact (une ligne) ── */

function BilanCompact({ total, fait }: { total: number; fait: number }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const ratio = total > 0 ? fait / total : 0;
  const toutFait = total > 0 && fait === total;
  return (
    <View style={styles.bilan}>
      <Feather
        name={toutFait ? 'check-circle' : 'target'}
        size={16}
        color={toutFait ? c.moment.recreation : c.action[1]}
      />
      <Text style={styles.bilanTitre}>{S.bilanTitre}</Text>
      {total > 0 ? (
        <View style={styles.jauge}>
          <View style={[styles.jaugeRempli, { width: `${Math.round(ratio * 100)}%`, backgroundColor: c.moment.recreation }]} />
        </View>
      ) : null}
      <Text style={styles.bilanChiffre}>{total > 0 ? `${fait}/${total}` : S.bilanVide}</Text>
    </View>
  );
}

/* ── La grille (large) ── */

function Grille({
  lignes,
  dates,
  actsParCase,
  aSansHeure,
  absences,
}: {
  lignes: Ligne[];
  dates: string[];
  actsParCase: Map<string, ActiviteListe[]>;
  aSansHeure: boolean;
  absences: AbsenceProf[];
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.grille}>
      <View style={styles.grilleTete}>
        <View style={styles.gouttiere} />
        {dates.map((d) => {
          const { jj, num } = jourCourt(d);
          return (
            <View key={d} style={styles.colTete}>
              <Text style={styles.colJour}>{jj}</Text>
              <Text style={styles.colNum}>{num}</Text>
              <BadgeAbsence absences={absencesDuJour(absences, d)} compact />
            </View>
          );
        })}
      </View>

      {aSansHeure ? <RangeeSansHeure dates={dates} actsParCase={actsParCase} /> : null}

      {lignes.map((ligne) =>
        ligne.bande ? (
          <BandeLigne key={ligne.debut} ligne={ligne} />
        ) : (
          <RangeeLigne key={ligne.debut} ligne={ligne} dates={dates} actsParCase={actsParCase} />
        ),
      )}
    </View>
  );
}

function BandeLigne({ ligne }: { ligne: Ligne }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const teinte = ligne.momentBande ? c.teinte[ligne.momentBande] : c.fond;
  const trait = ligne.momentBande ? c.moment[ligne.momentBande] : c.bord;
  return (
    <View style={[styles.bande, { backgroundColor: teinte }]}>
      {ligne.momentBande ? <Feather name={ICONE_MOMENT[ligne.momentBande]} size={13} color={trait} /> : null}
      <Text style={styles.bandeTexte} numberOfLines={1}>
        {ligne.libelleBande || '·'}
      </Text>
      <Text style={styles.bandeHeure}>
        {ligne.debut}
        {ligne.fin ? ` → ${ligne.fin}` : ''}
      </Text>
    </View>
  );
}

function RangeeLigne({
  ligne,
  dates,
  actsParCase,
}: {
  ligne: Ligne;
  dates: string[];
  actsParCase: Map<string, ActiviteListe[]>;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  // Quand un bloc de CETTE rangée est glissé, on la hisse au-dessus des autres :
  // les rangées suivantes se peignent après et masqueraient sinon le bloc en vol.
  const [glisse, setGlisse] = useState(false);
  return (
    <View style={[styles.rangee, glisse && styles.rangeeGlisse]}>
      <View style={styles.gouttiere}>
        <Text style={styles.gouttiereHeure}>{ligne.debut}</Text>
      </View>
      {dates.map((d, i) => {
        const cr = ligne.parJour[i];
        // Pas de créneau qui démarre ici, mais un plus long le couvre : on tient
        // la couleur du bloc plutôt que de laisser un trou sous son début.
        const couvrant = cr ? null : ligne.couvert[i];
        const acts = cr ? (actsParCase.get(`${d}|${cr.id}`) ?? []) : [];
        return (
          <Cellule
            key={d}
            moment={cr?.moment ?? couvrant?.moment ?? null}
            present={!!cr}
            continuation={!!couvrant}
            acts={acts}
            date={d}
            creneauId={cr?.id}
            libelle={cr?.libelle ?? ''}
            jourLabel={jourCourt(d).jj}
            heure={ligne.debut}
            onDrag={setGlisse}
          />
        );
      })}
    </View>
  );
}

function RangeeSansHeure({
  dates,
  actsParCase,
}: {
  dates: string[];
  actsParCase: Map<string, ActiviteListe[]>;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  // Une séance « sans heure » (créée sans moment, ou copiée vers un jour qui n'a
  // pas ce créneau) doit pouvoir se GLISSER sur son créneau, comme n'importe
  // quelle case. Sans ça, elle restait coincée en haut, non rattachable — c'est
  // ce qui donnait « je ne sais pas glisser mon vendredi » quand ses séances y
  // avaient atterri (retour Sophie). La clé source `${d}|sans` n'est pas une
  // cible enregistrée : on ne dépose donc jamais DANS cette rangée, on en sort.
  const drag = useDeplacement();
  const [glisse, setGlisse] = useState(false);
  return (
    <View style={[styles.rangee, glisse && styles.rangeeGlisse]}>
      <View style={styles.gouttiere}>
        <Feather name="clock" size={12} color={c.nonRattache} />
      </View>
      {dates.map((d) => {
        const acts = actsParCase.get(`${d}|sans`) ?? [];
        return (
          <View key={d} style={styles.cellule}>
            {acts.map((a) =>
              drag ? (
                <SeanceBlocDeplacable
                  key={a.id}
                  activite={a}
                  cleSource={`${d}|sans`}
                  drag={drag}
                  onDrag={setGlisse}
                />
              ) : (
                <SeanceBloc key={a.id} activite={a} />
              ),
            )}
            {acts.length === 0 ? <View style={styles.celluleVide} /> : null}
          </View>
        );
      })}
    </View>
  );
}

function Cellule({
  moment,
  present,
  continuation = false,
  acts,
  date,
  creneauId,
  libelle,
  jourLabel,
  heure,
  onDrag,
}: {
  moment: Moment | null;
  present: boolean;
  /** La case prolonge un créneau plus long démarré au-dessus (même jour). */
  continuation?: boolean;
  acts: ActiviteListe[];
  date: string;
  creneauId: string | undefined;
  libelle: string;
  jourLabel: string;
  heure: string;
  /** Remonte à la rangée qu'un glissé est en cours dans cette case. */
  onDrag?: (actif: boolean) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const drag = useDeplacement();
  // La clé de la case, stable pour cette position : c'est elle qu'on enregistre
  // comme cible de dépôt et qu'un bloc porte comme source.
  const cle = present && creneauId ? cleCase(date, creneauId) : null;
  const refCase = useCallback(
    (n: View | null) => {
      if (cle) drag?.enregistrer(cle, n);
    },
    [drag, cle],
  );

  if (!present) {
    // Prolongement d'un créneau long : on garde sa teinte, sans libellé ni « + »,
    // pour que le bloc se lise d'un bloc de son début à sa fin.
    if (continuation) {
      const teinteSuite = moment ? c.teinte[moment] : c.surface;
      return <View style={[styles.cellule, styles.celluleSuite, { backgroundColor: teinteSuite }]} />;
    }
    return <View style={[styles.cellule, styles.celluleAbsente]} />;
  }

  const teinte = moment ? c.teinte[moment] : c.surface;

  if (acts.length === 0) {
    // Case sans activité : on affiche quand même le LIBELLÉ du créneau (« Psycho-
    // motricité », « Accueil »…) pour que la journée se lise même vide, plus le
    // « + » d'ajout. Sans ça, un créneau sans séance n'était qu'un « + » muet.
    return (
      <Pressable
        ref={refCase}
        accessibilityRole="button"
        accessibilityLabel={libelle ? `${libelle}, ${jourLabel}, ${heure}` : S.aria.libre(jourLabel, heure)}
        onPress={() => router.push({ pathname: '/activite/type', params: { date, creneau: creneauId ?? '' } })}
        style={[styles.cellule, styles.celluleLibre, { backgroundColor: teinte }]}>
        {libelle ? (
          <Text style={styles.libelleLibre} numberOfLines={2}>
            {libelle}
          </Text>
        ) : null}
        <Feather name="plus" size={15} color={c.nonRattache} />
      </Pressable>
    );
  }

  return (
    <View ref={refCase} style={[styles.cellule, { backgroundColor: teinte }]}>
      {acts.map((a) =>
        drag && cle ? (
          <SeanceBlocDeplacable key={a.id} activite={a} cleSource={cle} drag={drag} onDrag={onDrag} />
        ) : (
          <SeanceBloc key={a.id} activite={a} />
        ),
      )}
    </View>
  );
}

/**
 * Une séance qu'on peut GLISSER vers une autre case. On la « lève » après un
 * appui prolongé (pour ne pas voler le tap ni le scroll), on la fait suivre le
 * doigt, et au relâcher on résout la case sous le doigt : si c'est une autre
 * case, on déplace. Le tap simple continue d'ouvrir la séance.
 */
function SeanceBlocDeplacable({
  activite,
  cleSource,
  drag,
  onDrag,
}: {
  activite: ActiviteListe;
  cleSource: string;
  drag: Deplacement;
  /** Prévient la rangée qu'un glissé est en cours (pour la faire passer au-dessus). */
  onDrag?: (actif: boolean) => void;
}) {
  const tx = useSharedValue(0);
  const ty = useSharedValue(0);
  const leve = useSharedValue(0);

  const ouvrir = () =>
    router.push({ pathname: '/activite/[id]', params: { id: activite.id } });

  // Le geste est (re)construit à chaque rendu : GestureDetector le réconcilie, et
  // les shared values sont des références stables. On ne le met pas en useMemo
  // pour ne pas y capturer les shared values comme dépendances (elles ne sont
  // pas des valeurs immuables).
  const pan = Gesture.Pan()
    .activateAfterLongPress(180)
    .onStart(() => {
      leve.value = 1;
      if (onDrag) runOnJS(onDrag)(true);
      runOnJS(drag.mesurer)();
    })
    .onUpdate((e) => {
      tx.value = e.translationX;
      ty.value = e.translationY;
    })
    .onEnd((e) => {
      runOnJS(drag.deposer)(e.absoluteX, e.absoluteY, activite.id, cleSource);
    })
    .onFinalize(() => {
      // Quoi qu'il arrive (dépôt réussi ou annulé), la séance revient à sa place :
      // la mise à jour des données la re-rendra dans la bonne case.
      tx.value = withSpring(0);
      ty.value = withSpring(0);
      leve.value = 0;
      if (onDrag) runOnJS(onDrag)(false);
    });

  // Ouvrir la leçon est un TAP franc, exclusif du glissé : après un drop, on ne
  // veut PAS que la fiche s'ouvre toute seule (retour Valentin). Le Pan a la
  // priorité (il s'arme au long-press) ; le Tap ne gagne que sur un appui court.
  const tap = Gesture.Tap()
    .maxDuration(250)
    .onEnd((_e, reussi) => {
      if (reussi) runOnJS(ouvrir)();
    });
  const geste = Gesture.Exclusive(pan, tap);

  const style = useAnimatedStyle(() => ({
    transform: [{ translateX: tx.value }, { translateY: ty.value }, { scale: leve.value ? 1.06 : 1 }],
    // Très au-dessus de tout pendant le glissé : sinon la case passe SOUS les
    // blocs des rangées voisines (qui se peignent après). La rangée elle-même se
    // hisse aussi (voir RangeeLigne), pour franchir les rangées d'en dessous.
    zIndex: leve.value ? 999 : 0,
    elevation: leve.value ? 12 : 0,
    opacity: leve.value ? 0.96 : 1,
  }));

  return (
    <GestureDetector gesture={geste}>
      <Animated.View style={style}>
        <SeanceBloc activite={activite} interactif={false} />
      </Animated.View>
    </GestureDetector>
  );
}

function SeanceBloc({
  activite,
  interactif = true,
}: {
  activite: ActiviteListe;
  /** Faux quand un geste parent (drag) gère l'ouverture : on ne double pas le tap. */
  interactif?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const faite = activite.statut === 'completed';
  const emoji = activite.sansCompetences ? emojiActivite(activite.titre) : null;
  // En vue multi-classes, la classe d'origine du bloc, pour la distinguer.
  const infoClasse = useClasseBloc(activite.id);
  // La taxonomie des types (pour l'étiquette d'une séance de séquence).
  const types = useTypes();
  // Une séquence multi-étapes : k/N + type. Une leçon mono-étape (total 1) n'en
  // affiche rien (rétro-compat visuelle).
  const estSequence = activite.sequenceTotal > 1;
  // Marqueur en CASE À COCHER corail (jeton `actif` de la charte, jamais un
  // moment — fini le vert qui se confondait avec la Récréation). Fait = case
  // PLEINE corail + coche blanche ; à faire = case CLAIRE + coche corail (même
  // forme, remplissage inversé). Une activité logistique garde son emoji.
  const contenu = (
    <>
      {infoClasse ? (
        // La pastille de classe, en tête du bloc : un point de sa couleur et son
        // abrégé, pour lire d'un coup à quelle classe appartient la séance.
        <View style={styles.pastilleClasse}>
          <View style={[styles.pastillePoint, { backgroundColor: infoClasse.couleur }]} />
          <Text style={[styles.pastilleTexte, { color: infoClasse.couleur }]} numberOfLines={1}>
            {infoClasse.abrege}
          </Text>
        </View>
      ) : null}
      <View style={styles.blocTete}>
      {faite ? (
        <View style={[styles.coche, styles.cocheFaite]}>
          <Feather name="check" size={9} color={c.surface} />
        </View>
      ) : emoji ? (
        <Text style={styles.blocEmoji}>{emoji}</Text>
      ) : (
        <View style={[styles.coche, styles.cochePrevue]}>
          <Feather name="check" size={9} color={c.actif} />
        </View>
      )}
      <Text style={styles.blocTitre} numberOfLines={2}>
        {activite.titre}
      </Text>
      </View>
      {estSequence ? (
        <View style={styles.blocSeq}>
          {activite.stepOrder ? (
            <Text style={styles.blocEtape}>
              {texteEtape(activite.stepOrder, activite.sequenceTotal)}
            </Text>
          ) : null}
          <EtiquetteType code={activite.learningType} types={types} compacte />
        </View>
      ) : null}
    </>
  );
  if (!interactif) return <View style={styles.bloc}>{contenu}</View>;
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={faite ? S.aria.fait(activite.titre) : S.aria.prevu(activite.titre)}
      onPress={() => router.push({ pathname: '/activite/[id]', params: { id: activite.id } })}
      style={styles.bloc}>
      {contenu}
    </Pressable>
  );
}

/* ── La vue jour (étroit) ── */

function VueJour({
  lignes,
  dates,
  actsParCase,
  jourActif,
  onJour,
  absences,
}: {
  lignes: Ligne[];
  dates: string[];
  actsParCase: Map<string, ActiviteListe[]>;
  jourActif: number;
  onJour: (jour: number) => void;
  absences: AbsenceProf[];
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const idx = jourActif - 1;
  const date = dates[idx];
  const sans = actsParCase.get(`${date}|sans`) ?? [];

  return (
    <View style={styles.vueJour}>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.pilules}>
        {JOURS.map((jour, i) => {
          const { jj, num } = jourCourt(dates[i]);
          const actif = jour === jourActif;
          return (
            <Pressable
              key={jour}
              accessibilityRole="button"
              accessibilityState={{ selected: actif }}
              accessibilityLabel={`${jj} ${num}`}
              onPress={() => onJour(jour)}
              style={[styles.pilule, actif && styles.piluleActive]}>
              <Text style={[styles.piluleJour, actif && styles.piluleTexteActif]}>{jj}</Text>
              <Text style={[styles.piluleNum, actif && styles.piluleTexteActif]}>{num}</Text>
            </Pressable>
          );
        })}
      </ScrollView>

      <BadgeAbsence absences={absencesDuJour(absences, date)} />

      {sans.map((a) => (
        <LigneJour key={a.id} titre={S.sansHeure} moment={null} debut="" fin="" acts={[a]} date={date} creneauId={undefined} />
      ))}

      {lignes.map((ligne) => {
        const cr = ligne.parJour[idx];
        if (!cr) return null;
        const acts = actsParCase.get(`${date}|${cr.id}`) ?? [];
        return (
          <LigneJour
            key={ligne.debut}
            titre={cr.libelle || ligne.debut}
            moment={cr.moment}
            debut={ligne.debut}
            fin={cr.fin}
            acts={acts}
            date={date}
            creneauId={cr.id}
          />
        );
      })}
    </View>
  );
}

function LigneJour({
  titre,
  moment,
  debut,
  fin,
  acts,
  date,
  creneauId,
}: {
  titre: string;
  moment: Moment | null;
  debut: string;
  fin: string;
  acts: ActiviteListe[];
  date: string;
  creneauId: string | undefined;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const teinte = moment ? c.teinte[moment] : c.surface;
  const trait = moment ? c.moment[moment] : c.bord;
  return (
    <View style={[styles.ligneJour, { backgroundColor: teinte, borderLeftColor: trait }]}>
      <View style={styles.ligneJourTete}>
        {moment ? <Tuile icone={ICONE_MOMENT[moment]} moment={moment} /> : <Tuile icone="clock" />}
        <View style={styles.ligneJourTexte}>
          <Text style={styles.ligneJourTitre} numberOfLines={1}>
            {titre}
          </Text>
          {debut ? (
            <Text style={texte.discret}>
              {debut}
              {fin ? ` à ${fin}` : ''}
            </Text>
          ) : null}
        </View>
      </View>
      {acts.length ? (
        <View style={styles.ligneJourSeances}>
          {acts.map((a) => (
            <SeanceBloc key={a.id} activite={a} />
          ))}
        </View>
      ) : creneauId ? (
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={S.ajouter}
          onPress={() => router.push({ pathname: '/activite/type', params: { date, creneau: creneauId } })}
          style={styles.ligneJourLibre}>
          <Feather name="plus" size={15} color={c.action[1]} />
          <Text style={styles.ligneJourAjouter}>{S.ajouter}</Text>
        </Pressable>
      ) : null}
    </View>
  );
}

