import { Feather } from '@expo/vector-icons';
import { useEffect, useMemo, useState } from 'react';
import { StyleSheet, Text, View } from 'react-native';

import { Cloudy, type Pose } from '@/components/cloudy';
import { Presse } from '@/components/presse';
import { t } from '@/i18n';
import { aVuCoach, marquerCoachVu, type IdCoach } from '@/lib/coachmarks';
import { espace, ombre, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/**
 * Une bulle de Cloudy : un mot d'aide qui dit le geste possible, une seule fois
 * par écran, puis plus jamais. C'est le lever d'adoption le plus léger qui soit —
 * pas un tour, pas une modale, juste une phrase calme qui s'efface d'un « Compris ».
 *
 * 🔑 Trois états, jamais deux. Tant qu'on ne SAIT pas si le mark a été vu
 * (`inconnu`), on ne rend rien : afficher la bulle puis la retirer dès la lecture
 * revenue ferait clignoter l'écran. On ne la montre (`montrer`) que sur une
 * réponse claire « pas encore vu ». Le « Compris » la range (`cache`) et pose le
 * drapeau. La lecture est fail-open (voir `coachmarks.ts`) : au moindre doute, on
 * ne montre rien, la bulle n'est jamais une porte devant le contenu.
 *
 * 🎨 La bulle porte la teinte miel de l'action, comme le mot de Cloudy compagnon
 * sur l'accueil : c'est la mascotte qui parle, pas une notification système. Elle
 * tient sur les deux thèmes (`actionTeinte` existe clair et sombre). Cloudy entre
 * d'un pop discret, coupé sous « réduire les animations » par le composant lui-même.
 */
export function CoachMark({
  id,
  message,
  pose = 'salut',
}: {
  id: IdCoach;
  message: string;
  /** La pose de Cloudy dans la bulle. Toujours positive, jamais tournée en reproche. */
  pose?: Pose;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [etat, setEtat] = useState<'inconnu' | 'montrer' | 'cache'>('inconnu');

  useEffect(() => {
    let vivant = true;
    aVuCoach(id).then((vu) => {
      if (vivant) setEtat(vu ? 'cache' : 'montrer');
    });
    return () => {
      vivant = false;
    };
  }, [id]);

  if (etat !== 'montrer') return null;

  const fermer = () => {
    // On range d'abord (retour immédiat), on pose le drapeau ensuite. Même si
    // l'écriture échoue, la bulle est partie pour cette session, et au pire elle
    // reviendra une fois — jamais un blocage.
    setEtat('cache');
    void marquerCoachVu(id);
  };

  return (
    <View
      accessibilityRole="alert"
      style={styles.bulle}>
      <Cloudy pose={pose} taille={44} anime />
      <View style={styles.corps}>
        <Text style={styles.message}>{message}</Text>
        {/* Le « J'ai compris » : une vraie puce tactile (fond plein, coche,
            ombre douce) plutôt qu'un mot discret. On n'était pas sûr de pouvoir
            cliquer dessus (retour Valentin 24/08) : l'icône et le relief disent
            « touche-moi ». */}
        <Presse
          accessibilityRole="button"
          accessibilityLabel={t.coach.compris}
          onPress={fermer}
          style={styles.bouton}>
          <Feather name="check" size={16} color={c.action[1]} />
          <Text style={styles.boutonTexte}>{t.coach.compris}</Text>
        </Presse>
      </View>
    </View>
  );
}

const creerStyles = (c: Couleurs) =>
  StyleSheet.create({
    bulle: {
      flexDirection: 'row',
      gap: espace.md,
      alignItems: 'center',
      backgroundColor: c.actionTeinte,
      borderRadius: rayon.carte,
      padding: espace.md,
    },
    corps: { flex: 1, gap: espace.sm },
    message: { fontFamily: police.corps, fontSize: 15, lineHeight: 21, color: c.encre },
    // Le « J'ai compris » : une puce blanche à ombre douce, coche à gauche, qui
    // se lit comme un bouton. Alignée à gauche, elle reste modeste mais tactile.
    bouton: {
      flexDirection: 'row',
      alignItems: 'center',
      gap: espace.xs,
      alignSelf: 'flex-start',
      paddingVertical: espace.xs,
      paddingHorizontal: espace.md,
      borderRadius: rayon.pastille,
      backgroundColor: c.surface,
      ...ombre.carte,
    },
    boutonTexte: { fontFamily: police.accent, fontSize: 14, color: c.action[1] },
  });
