import { router } from 'expo-router';
import { useEffect, useMemo, useState } from 'react';
import { Pressable, StyleSheet, Switch, Text, View } from 'react-native';

import { Cloudy } from '@/components/cloudy';
import { Carte } from '@/components/ecran';
import { Alerte, BoutonSecondaire, Champ } from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { t } from '@/i18n';
import {
  definirRituel,
  demanderPermissionRituel,
  desactiverRituel,
  HEURE_DEFAUT,
  HEURES_PROPOSEES,
  lireRituel,
  permissionRituel,
} from '@/lib/rituel';
import { espace, ombre, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

/** `09:00`, et rien d'autre. Même contrôle que la semaine type. */
function heureValide(v: string): boolean {
  const m = v.match(/^(\d{2}):(\d{2})$/);
  if (!m) return false;
  return parseInt(m[1], 10) <= 23 && parseInt(m[2], 10) <= 59;
}

/** Force le format pendant la frappe : les deux points se posent tout seuls. */
function formaterHeure(v: string): string {
  const chiffres = v.replace(/[^0-9]/g, '').slice(0, 4);
  if (chiffres.length <= 2) return chiffres;
  return `${chiffres.slice(0, 2)}:${chiffres.slice(2)}`;
}

/**
 * Le réglage du rituel du soir : actif ou non, et à quelle heure.
 *
 * 🔑 L'heure est CHOISIE ici, c'est l'exigence du produit. Plutôt qu'une grille
 * de pastilles qui faisait fouilli, un sélecteur SEGMENTÉ compact façon
 * interrupteur iOS : une rangée d'options de largeur égale, plus « Autre » qui
 * révèle un champ 'HH:MM' pour le reste. Aucune dépendance native ajoutée :
 * pas de sélecteur de date à embarquer, donc pas de rebuild.
 *
 * 🔑 L'autorisation se demande au moment où l'on active, jamais avant. Refusée,
 * l'interrupteur reste éteint et on le dit sans détour : le rappel ne peut pas
 * sonner. Mais le rituel lui-même reste ouvrable à la main, ici même, en bas :
 * on ne ferme aucune porte, on ne fait que taire un réveil.
 *
 * 🌥️ Une seule Cloudy sur l'écran, pose 'serenite' : le rituel du soir est un
 * moment calme, la mascotte porte cette émotion en tête de l'écran.
 */
export default function RituelReglage() {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const [actif, setActif] = useState(false);
  const [heure, setHeure] = useState<string>(HEURE_DEFAUT);
  const [perso, setPerso] = useState(false);
  const [occupe, setOccupe] = useState(false);
  const [refus, setRefus] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  // Au montage : on lit le réglage et l'autorisation courante, pour afficher la
  // vérité sans attendre le moindre geste.
  useEffect(() => {
    let vivant = true;
    lireRituel().then((r) => {
      if (!vivant) return;
      setActif(r.actif);
      setHeure(r.heure);
      // Une heure hors des préréglés bascule d'office le champ personnalisé.
      setPerso(!HEURES_PROPOSEES.includes(r.heure as (typeof HEURES_PROPOSEES)[number]));
    });
    permissionRituel().then((p) => {
      if (vivant) setRefus(p === 'refusee');
    });
    return () => {
      vivant = false;
    };
  }, []);

  // Basculer l'interrupteur. À l'activation, l'autorisation d'abord : sans elle,
  // programmer un rappel ne rappellerait rien, donc on ne prétend pas l'avoir
  // fait et l'interrupteur reste éteint.
  async function basculer(vers: boolean) {
    setErreur(null);
    setOccupe(true);
    try {
      if (!vers) {
        await desactiverRituel();
        setActif(false);
        return;
      }
      const ok = await demanderPermissionRituel();
      setRefus(!ok);
      if (!ok) return;
      const choix = heureValide(heure) ? heure : HEURE_DEFAUT;
      await definirRituel(choix);
      setHeure(choix);
      setActif(true);
    } catch {
      setErreur(t.rituel.erreur);
    } finally {
      setOccupe(false);
    }
  }

  // Choisir une heure. Si le rituel est déjà actif, on le reprogramme aussitôt ;
  // sinon on ne fait que retenir le choix pour la prochaine activation.
  async function choisirHeure(h: string) {
    if (!heureValide(h)) {
      setHeure(h);
      return;
    }
    setHeure(h);
    if (!actif) return;
    setErreur(null);
    setOccupe(true);
    try {
      await definirRituel(h);
    } catch {
      setErreur(t.rituel.erreur);
    } finally {
      setOccupe(false);
    }
  }

  return (
    <SousEcran titre={t.rituel.reglageTitre}>
      <Carte>
        <View style={styles.hero}>
          {/* Une seule Cloudy par écran, purement décorative et fixe : elle pose
              l'émotion calme du rituel, le lecteur d'écran l'ignore. */}
          <Cloudy pose="serenite" taille={76} respire={false} />
          <Text style={styles.intro}>{t.rituel.reglageIntro}</Text>
        </View>
      </Carte>

      <Carte>
        <View style={styles.ligne}>
          <Text style={styles.titreCarte}>{t.rituel.rappelTitre}</Text>
          <Switch
            accessibilityLabel={t.rituel.rappelTitre}
            value={actif}
            onValueChange={basculer}
            disabled={occupe}
            trackColor={{ false: c.bord, true: c.actif }}
            thumbColor={c.surface}
            ios_backgroundColor={c.bord}
          />
        </View>
        <Text style={styles.aide}>{t.rituel.rappelAide}</Text>

        {refus ? <Alerte message={t.rituel.refus} /> : null}

        {/* Le choix de l'heure n'apparaît que quand le rituel est actif : régler
            une heure pour un rappel éteint n'aurait pas de sens. */}
        {actif ? (
          <View style={styles.heures}>
            <Text style={styles.etiquette}>{t.rituel.aQuelleHeure}</Text>

            {/* Sélecteur segmenté : une rangée de segments de largeur égale, le
                choix courant surligné comme un interrupteur iOS. Plus net que la
                grille de pastilles d'avant, et sans sélecteur natif à embarquer. */}
            <View style={styles.segmente}>
              {HEURES_PROPOSEES.map((h) => {
                const choisi = !perso && heure === h;
                return (
                  <Pressable
                    key={h}
                    accessibilityRole="button"
                    accessibilityLabel={`${t.rituel.aQuelleHeure} ${h}`}
                    accessibilityState={{ selected: choisi }}
                    disabled={occupe}
                    onPress={() => {
                      setPerso(false);
                      void choisirHeure(h);
                    }}
                    style={[styles.segment, choisi && styles.segmentActif]}>
                    <Text style={[styles.texteSegment, choisi && styles.texteSegmentActif]}>
                      {h}
                    </Text>
                  </Pressable>
                );
              })}
              <Pressable
                accessibilityRole="button"
                accessibilityLabel={t.rituel.personnalise}
                accessibilityState={{ selected: perso }}
                disabled={occupe}
                onPress={() => setPerso(true)}
                style={[styles.segment, perso && styles.segmentActif]}>
                <Text style={[styles.texteSegment, perso && styles.texteSegmentActif]}>
                  {t.rituel.personnalise}
                </Text>
              </Pressable>
            </View>

            {perso ? (
              <Champ
                etiquette={t.rituel.heureLibre}
                value={heure}
                onChangeText={(v) => void choisirHeure(formaterHeure(v))}
                placeholder="19:00"
                keyboardType="number-pad"
                editable={!occupe}
              />
            ) : null}

            <Text style={styles.aide}>{t.rituel.rappelHeureAide}</Text>
          </View>
        ) : null}
      </Carte>

      {/* Toujours là, quelle que soit l'autorisation : le rituel s'ouvre à la
          main. Un rappel refusé ne prend pas le rituel en otage. */}
      <BoutonSecondaire libelle={t.rituel.ouvrirMaintenant} onPress={() => router.push('/soir')} />

      {erreur ? <Alerte message={erreur} /> : null}
    </SousEcran>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  hero: { alignItems: 'center', gap: espace.sm },
  intro: {
    fontFamily: police.corps,
    fontSize: 15,
    lineHeight: 22,
    color: c.encreDouce,
    textAlign: 'center',
  },
  ligne: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: espace.md,
  },
  titreCarte: { flex: 1, fontFamily: police.accent, fontSize: 16, color: c.encre },
  aide: { fontFamily: police.corps, fontSize: 14, lineHeight: 21, color: c.encreDouce },
  etiquette: { fontFamily: police.accent, fontSize: 14, color: c.encreDouce },
  heures: { gap: espace.sm, marginTop: espace.xs },
  // La piste du segmenté : un bandeau neutre arrondi, un mince liseré, et 3 px
  // de marge intérieure pour que le segment surligné respire.
  segmente: {
    flexDirection: 'row',
    backgroundColor: c.fond,
    borderRadius: rayon.pastille,
    borderWidth: 1,
    borderColor: c.bord,
    padding: 3,
    gap: 3,
  },
  // Chaque option prend la même largeur : `flex: 1` répartit la rangée à parts
  // égales, l'allure « interrupteur » vient de là.
  segment: {
    flex: 1,
    borderRadius: rayon.pastille - 3,
    paddingVertical: espace.sm,
    alignItems: 'center',
    justifyContent: 'center',
  },
  // Le segment choisi se détache en pastille blanche à ombre douce, comme le
  // segmented control d'iOS. Pas d'aplat de couleur : c'est du blanc sur neutre.
  segmentActif: { backgroundColor: c.surface, ...ombre.carte },
  texteSegment: { fontFamily: police.accent, fontSize: 13, color: c.encreDouce },
  texteSegmentActif: { color: c.encre },
});
