import AsyncStorage from '@react-native-async-storage/async-storage';
import { getLocales } from 'expo-localization';
import * as Updates from 'expo-updates';

import { fr } from './fr';
import { nl } from './nl';
import { lexique, maitrise, type CleLexique } from './lexique';

/**
 * Élargit les chaînes littérales de `fr` (figées par son `as const`) en `string`
 * SANS toucher aux fonctions ni à la forme. Sans ça, `typeof fr` imposerait à
 * chaque traduction la *valeur* française exacte de chaque libellé (« Accueil »
 * et rien d'autre), ce qui rend toute traduction impossible à compiler. Le
 * détecteur voulu porte sur la STRUCTURE, pas sur le texte : une clé manquante,
 * une clé en trop, une fonction de mauvaise signature. C'est exactement ce que
 * garde ce type une fois les feuilles `string` élargies (vérifié : clé manquante
 * et clé en trop restent des erreurs `tsc`). Les signatures de fonction et les
 * tuples (jours, departRaisons) sont préservés à l'identique.
 */
type Traduisible<T> = T extends (...args: infer A) => infer R
  ? (...args: A) => Traduisible<R>
  : T extends readonly unknown[]
    ? { readonly [K in keyof T]: Traduisible<T[K]> }
    : T extends object
      ? { readonly [K in keyof T]: Traduisible<T[K]> }
      : T extends string
        ? string
        : T;

/**
 * Le catalogue, c'est la forme du français. Chaque nouvelle langue se déclare
 * `Catalogue`, donc `tsc --noEmit` refuse une clé manquante, une clé en trop, ou
 * une fonction de mauvaise signature. Le détecteur de complétude d'une
 * traduction, c'est le compilateur lui-même : pas besoin d'un outil séparé qui
 * pourrait passer au vert en ne regardant rien.
 */
export type Catalogue = Traduisible<typeof fr>;

/**
 * Les langues qui ont un catalogue **complet et relu**. On n'ajoute une entrée
 * ici que quand le fichier existe et que `tsc` passe : une demi-traduction ne
 * doit jamais être proposée à une enseignante. Le français est la langue de
 * lancement ; le néerlandais et l'allemand (langues belges) puis l'anglais
 * (vitrine App Store) viendront s'y brancher un fichier à la fois.
 */
const catalogues = { fr, nl } as const;
export type Langue = keyof typeof catalogues;

/**
 * Ce que le sélecteur de « Vous » propose. Même liste que les catalogues, mais
 * avec le nom à afficher, et **chaque langue nommée dans sa propre langue**
 * (une personne qui cherche le néerlandais ne lit pas « Néerlandais »).
 */
export const LANGUES: { code: Langue; nom: string }[] = [
  { code: 'fr', nom: 'Français' },
  { code: 'nl', nom: 'Nederlands' },
];

const CLE_STOCKAGE = 'educooo.langue';

/** La langue de l'appareil, si on sait la servir. Sinon le français. */
const langueAppareil = (): Langue => {
  const code = getLocales()[0]?.languageCode;
  return code && code in catalogues ? (code as Langue) : 'fr';
};

// Ces trois valeurs sont réassignées, jamais recréées : elles sont importées en
// dur dans 672 endroits (`import { t } from '@/i18n'`), qui les lisent au rendu,
// donc après le gate de démarrage. La langue de l'appareil sert de valeur de
// départ ; le choix mémorisé la remplace avant le premier écran (voir
// `chargerLangue`, appelée derrière le splash dans `_layout`).
let langueActive: Langue = langueAppareil();

/** La langue courante. */
export let langue: Langue = langueActive;
/** Les libellés d'écran de la langue courante. */
export let t: Catalogue = catalogues[langueActive];
/** Les trois états de maîtrise, nommés une seule fois pour toute l'app. */
export let niveauxMaitrise = maitrise[langueActive] ?? maitrise.fr;

function appliquer(l: Langue) {
  langueActive = l;
  langue = l;
  t = catalogues[l];
  niveauxMaitrise = maitrise[l] ?? maitrise.fr;
}

/**
 * Appelée une seule fois, derrière le splash, avant que le premier écran se
 * rende. Lit le choix mémorisé et l'applique. Invisible : le splash est déjà
 * tenu pour le chargement des polices et de la session.
 */
export async function chargerLangue(): Promise<void> {
  try {
    const memorise = await AsyncStorage.getItem(CLE_STOCKAGE);
    if (memorise && memorise in catalogues) appliquer(memorise as Langue);
  } catch {
    // Stockage illisible : on garde la langue de l'appareil, déjà en place. Une
    // app à moitié dans une langue serait pire qu'une app cohérente en français.
  }
}

/**
 * Depuis « Vous ». Mémorise le choix puis **recharge l'app**. Une bascule de
 * langue est un geste rare et volontaire ; le rechargement rafraîchit d'un coup
 * tous les écrans déjà montés, ce qu'une simple réassignation ne ferait pas (un
 * onglet en arrière-plan resterait dans l'ancienne langue). Le choix étant
 * mémorisé avant le rechargement, l'app repart directement dans la bonne langue.
 */
export async function definirLangue(l: Langue): Promise<void> {
  if (l === langueActive) return;
  await AsyncStorage.setItem(CLE_STOCKAGE, l);
  appliquer(l);
  try {
    await Updates.reloadAsync();
  } catch {
    // En développement (rechargement indisponible), le prochain démarrage lira
    // le choix mémorisé. Le geste n'est pas perdu, il est juste différé.
  }
}

/** Un mot du métier dans la langue courante, avec repli sur le français. */
export const mot = (cle: CleLexique) => lexique[langueActive]?.[cle] ?? lexique.fr[cle];
