import { Feather } from '@expo/vector-icons';
import { ReactNode, useEffect, useMemo } from 'react';
import { StyleSheet, Text, View } from 'react-native';
import Animated, {
  FadeInDown,
  ReduceMotion,
  useAnimatedProps,
  useReducedMotion,
  useSharedValue,
  withClamp,
  withDelay,
  withSpring,
} from 'react-native-reanimated';
import Svg, { Circle } from 'react-native-svg';

import { espace, motion, police, rayon, useCouleurs, type Couleurs } from '@/theme/tokens';

const CercleAnime = Animated.createAnimatedComponent(Circle);

/** Les moments de la journée, seule dimension que la couleur code. */
export type Moment = keyof Couleurs['moment'];

/**
 * L'anneau de progression de la carte héro.
 *
 * On lit une proportion d'un coup d'œil, on ne lit pas « 62 % » d'un coup
 * d'œil : le chiffre est au centre, mais c'est l'arc qui informe. Miel de
 * l'action sur une piste lavande, une seule couleur, jamais criard.
 */
export function Anneau({
  valeur,
  taille = 76,
  epaisseur = 9,
}: {
  /** Entre 0 et 1. */
  valeur: number;
  taille?: number;
  epaisseur?: number;
}) {
  const couleurs = useCouleurs();
  const styles = useMemo(() => creerStyles(couleurs), [couleurs]);
  const v = Math.max(0, Math.min(1, valeur));
  const r = (taille - epaisseur) / 2;
  const circonference = 2 * Math.PI * r;
  const c = taille / 2;

  // L'arc se remplit de 0 jusqu'à sa valeur à l'apparition : on VOIT la
  // progression se poser, on ne la trouve pas déjà là. Ressort doux, ~600 ms,
  // avec une brève retenue pour que l'œil arrive avant le mouvement. On anime le
  // décalage du pointillé (dashoffset) plutôt que sa longueur : un seul nombre
  // suffit et l'arc ne se déforme jamais.
  const progression = useSharedValue(0);
  const reduire = useReducedMotion();
  useEffect(() => {
    if (reduire) {
      progression.value = v;
      return;
    }
    progression.value = 0;
    // withClamp borne le ressort à [0, v] : même si le ressort dépasse, l'arc ne
    // repart jamais au-delà de sa valeur (pas d'enroulement à 100 %).
    progression.value = withDelay(
      Math.round(motion.duree.rapide / 3),
      withClamp(
        { min: 0, max: v },
        // Ressort décrit par sa durée et son amortissement : ~600 ms, à peine de
        // rebond (0.9). Plus lisible ici que des constantes de raideur.
        withSpring(v, { duration: motion.duree.lent, dampingRatio: 0.9, reduceMotion: ReduceMotion.System }),
      ),
    );
  }, [v, reduire, progression]);

  const propsArc = useAnimatedProps(() => ({
    strokeDashoffset: circonference * (1 - progression.value),
  }));

  return (
    <View style={{ width: taille, height: taille }}>
      <Svg width={taille} height={taille}>
        <Circle cx={c} cy={c} r={r} stroke={couleurs.bord} strokeWidth={epaisseur} fill="none" />
        <CercleAnime
          cx={c}
          cy={c}
          r={r}
          stroke={couleurs.action[0]}
          strokeWidth={epaisseur}
          fill="none"
          strokeLinecap="round"
          strokeDasharray={circonference}
          animatedProps={propsArc}
          // Partir du haut plutôt que de trois heures : l'arc se lit comme une
          // horloge, pas comme un camembert renversé.
          transform={`rotate(-90 ${c} ${c})`}
        />
      </Svg>
      <View style={styles.anneauCentre}>
        <Text style={styles.anneauChiffre}>{Math.round(v * 100)}%</Text>
      </View>
    </View>
  );
}

/**
 * Rangée de trois tuiles de stats teintées. C'est ici que la couleur vit, sur
 * de petites surfaces, jamais sur un aplat plein écran.
 */
export function TuilesStats({
  items,
  anime = false,
}: {
  items: { valeur: string | number; libelle: string; moment: Moment }[];
  /**
   * Fait entrer les tuiles en cascade (une après l'autre, décalées). Réservé aux
   * moments forts — la célébration — où l'on veut que les chiffres se posent un
   * à un. Ailleurs les tuiles apparaissent d'un coup, comme avant. Sous « réduire
   * les animations », l'entrée est neutralisée.
   */
  anime?: boolean;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.tuiles}>
      {items.map((it, i) => {
        const fond = { backgroundColor: c.teinte[it.moment] };
        if (!anime) {
          return (
            <View key={i} style={[styles.tuileStat, fond]}>
              <Text style={styles.tuileStatValeur}>{it.valeur}</Text>
              <Text style={styles.tuileStatLibelle}>{it.libelle}</Text>
            </View>
          );
        }
        return (
          <Animated.View
            key={i}
            entering={FadeInDown.duration(motion.duree.normal)
              .delay(120 + i * 90)
              .reduceMotion(ReduceMotion.System)}
            style={[styles.tuileStat, fond]}>
            <Text style={styles.tuileStatValeur}>{it.valeur}</Text>
            <Text style={styles.tuileStatLibelle}>{it.libelle}</Text>
          </Animated.View>
        );
      })}
    </View>
  );
}

/**
 * Tuile d'icône teintée. Le fond prend la teinte claire du moment, l'icône sa
 * couleur pleine. Remplace la tuile grise qui traînait dans les écrans : le gris
 * veut dire « pas encore rattaché », il ne doit pas se retrouver sous une icône
 * de section.
 */
export function Tuile({
  icone,
  moment,
  fond,
  trait,
  taille = 38,
}: {
  icone: keyof typeof Feather.glyphMap;
  /** Le moment donne fond (teinte claire) et trait (couleur pleine). */
  moment?: Moment;
  /** Surcharges pour une tuile hors « moment » (ex. l'identité de capture). */
  fond?: string;
  trait?: string;
  taille?: number;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const bg = fond ?? (moment ? c.teinte[moment] : c.fond);
  const ic = trait ?? (moment ? c.moment[moment] : c.nonRattache);
  return (
    <View style={[styles.tuile, { width: taille, height: taille, backgroundColor: bg }]}>
      <Feather name={icone} size={taille * 0.5} color={ic} />
    </View>
  );
}

/**
 * Bande de moment : un bandeau teinté, arrondi, pour marquer un moment de la
 * journée dans le journal (récréation, sortie…). Titre à gauche, heure ou
 * précision à droite.
 */
export function Bande({
  moment,
  titre,
  extra,
  gauche,
}: {
  moment: Moment;
  titre: string;
  extra?: string;
  gauche?: ReactNode;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={[styles.bande, { backgroundColor: c.teinte[moment] }]}>
      {gauche}
      <Text style={styles.bandeTitre}>{titre}</Text>
      {extra ? <Text style={styles.bandeExtra}>{extra}</Text> : null}
    </View>
  );
}

const creerStyles = (c: Couleurs) => StyleSheet.create({
  anneauCentre: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    alignItems: 'center',
    justifyContent: 'center',
  },
  anneauChiffre: { fontFamily: police.titre, fontSize: 18, color: c.encre, letterSpacing: -0.5 },
  tuiles: { flexDirection: 'row', gap: espace.sm },
  tuileStat: {
    flex: 1,
    borderRadius: rayon.bloc,
    paddingVertical: espace.md,
    paddingHorizontal: espace.sm,
    alignItems: 'center',
  },
  tuileStatValeur: { fontFamily: police.titre, fontSize: 20, color: c.encre, letterSpacing: -0.5 },
  tuileStatLibelle: {
    fontFamily: police.accent,
    fontSize: 11,
    color: c.encreDouce,
    marginTop: 2,
    textAlign: 'center',
  },
  tuile: { borderRadius: rayon.tuile, alignItems: 'center', justifyContent: 'center' },
  bande: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: espace.sm,
    borderRadius: rayon.carte,
    paddingVertical: espace.md,
    paddingHorizontal: espace.md,
  },
  bandeTitre: { fontFamily: police.titre, fontSize: 15, color: c.encre, flex: 1, letterSpacing: -0.3 },
  bandeExtra: { fontFamily: police.accent, fontSize: 12, color: c.encreDouce },
});
