import AsyncStorage from '@react-native-async-storage/async-storage';
import Constants from 'expo-constants';
import * as Device from 'expo-device';
import * as Notifications from 'expo-notifications';
import { router } from 'expo-router';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { Platform } from 'react-native';

import { useMoi } from './session';
import { supabase } from './supabase';

/**
 * Le handler de premier plan doit être posé une seule fois pour tout le process,
 * avant même que quoi que ce soit ne s'affiche. Sans lui, une notif reçue app
 * ouverte reste silencieuse : le système la garde pour lui. On le met donc au
 * niveau du module, pas dans un effet, pour qu'il soit prêt dès l'import.
 *
 * On garde les deux nouveaux drapeaux (`shouldShowBanner` / `shouldShowList`) :
 * `shouldShowAlert` est déprécié dans cette version d'expo-notifications, et
 * l'omettre ici éviterait un avertissement à chaque notif.
 */
Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldShowBanner: true,
    shouldShowList: true,
    shouldPlaySound: true,
    shouldSetBadge: false,
  }),
});

/**
 * La clé AsyncStorage où l'on garde l'état des rappels quotidiens. On persiste
 * aussi les identifiants planifiés, pas seulement les heures : c'est le seul
 * moyen d'annuler proprement NOS rappels sans toucher à d'éventuelles autres
 * notifications locales, et de les retrouver après un redémarrage de l'app.
 */
const CLE_RAPPELS = 'educooo.rappels';

/** Le canal Android par défaut. Sur iOS il est ignoré, ça ne coûte rien. */
const CANAL_DEFAUT = 'default';

/**
 * L'état des rappels tel qu'on le stocke sur le disque. On ne réexpose que
 * `actif` et `heures` à l'extérieur ; `ids` reste un détail interne d'annulation.
 */
type RappelsStockes = {
  actif: boolean;
  heures: string[];
  ids: string[];
};

type EtatNotifications = {
  /** L'état d'autorisation, traduit dans le vocabulaire de l'app. */
  autorisation: 'accordee' | 'refusee' | 'indeterminee';
  /** Ouvre la demande système. Renvoie vrai si c'est accordé au sortir. */
  demanderAutorisation: () => Promise<boolean>;
  /** Les rappels quotidiens actifs, avec leurs heures locales au format 'HH:mm'. */
  rappels: { actif: boolean; heures: string[] };
  /** Active et (re)planifie un rappel quotidien répété pour chaque heure donnée. */
  definirRappels: (heures: string[]) => Promise<void>;
  /** Annule tous les rappels quotidiens et repasse à l'état inactif. */
  desactiverRappels: () => Promise<void>;
};

const Contexte = createContext<EtatNotifications | null>(null);

/** Traduit la réponse de permission d'expo dans les trois états de l'app. */
function traduireAutorisation(
  reponse: Notifications.NotificationPermissionsStatus,
): EtatNotifications['autorisation'] {
  if (reponse.granted) return 'accordee';
  // `undetermined` = on n'a jamais demandé (ou l'utilisateur·rice peut encore
  // dire oui). Tout le reste (refus, restreint) se range dans « refusée » :
  // dans les deux cas on ne peut pas notifier tant qu'il n'y a pas de geste.
  if (reponse.status === 'undetermined') return 'indeterminee';
  return 'refusee';
}

/** Lit l'état des rappels sur le disque, en tolérant l'absence ou la casse. */
async function lireRappelsStockes(): Promise<RappelsStockes> {
  try {
    const brut = await AsyncStorage.getItem(CLE_RAPPELS);
    if (!brut) return { actif: false, heures: [], ids: [] };
    const parse = JSON.parse(brut) as Partial<RappelsStockes>;
    return {
      actif: !!parse.actif,
      heures: Array.isArray(parse.heures) ? parse.heures : [],
      ids: Array.isArray(parse.ids) ? parse.ids : [],
    };
  } catch {
    // Un JSON corrompu ne doit pas empêcher l'app de démarrer : on repart d'un
    // état vide plutôt que de propager l'erreur jusqu'à l'écran.
    return { actif: false, heures: [], ids: [] };
  }
}

/** Écrit l'état des rappels sur le disque. */
async function ecrireRappelsStockes(etat: RappelsStockes): Promise<void> {
  await AsyncStorage.setItem(CLE_RAPPELS, JSON.stringify(etat));
}

/** Découpe une heure 'HH:mm' en nombres, ou null si le format ne colle pas. */
function decouperHeure(heure: string): { hour: number; minute: number } | null {
  const m = /^(\d{1,2}):(\d{2})$/.exec(heure.trim());
  if (!m) return null;
  const hour = Number(m[1]);
  const minute = Number(m[2]);
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;
  return { hour, minute };
}

/**
 * La brique unique des notifications. On la pose sous le fournisseur de session
 * parce qu'elle en dépend : l'enregistrement du token push n'a de sens qu'une
 * fois qu'on sait à qui l'attribuer.
 *
 * Deux responsabilités distinctes vivent ici :
 *   1. rediriger l'enseignant·e vers le bon écran quand elle·il tape une notif ;
 *   2. tenir les rappels quotidiens « observations en attente », locaux, que
 *      l'écran de réglages allume et éteint.
 * Le token push, lui, n'est enregistré que si l'autorisation est déjà donnée :
 * on ne force jamais la permission au démarrage, elle se demande depuis les
 * réglages, pour ne pas accueillir l'utilisateur·rice par une pop-up système.
 */
export function FournisseurNotifications({ children }: { children: ReactNode }) {
  const moi = useMoi();
  const [autorisation, setAutorisation] = useState<EtatNotifications['autorisation']>('indeterminee');
  const [rappels, setRappels] = useState<{ actif: boolean; heures: string[] }>({
    actif: false,
    heures: [],
  });

  // On garde les identifiants planifiés dans une ref plutôt que dans l'état :
  // ils ne servent qu'à l'annulation, l'écran n'a pas à les connaître ni à se
  // re-rendre quand ils changent.
  const idsRef = useRef<string[]>([]);

  // Au montage : on réhydrate l'état des rappels depuis le disque et on lit
  // l'autorisation courante, pour que l'écran de réglages affiche la vérité
  // sans attendre le moindre geste.
  useEffect(() => {
    let vivant = true;

    lireRappelsStockes().then((stocke) => {
      if (!vivant) return;
      idsRef.current = stocke.ids;
      setRappels({ actif: stocke.actif, heures: stocke.heures });
    });

    Notifications.getPermissionsAsync()
      .then((reponse) => {
        if (vivant) setAutorisation(traduireAutorisation(reponse));
      })
      .catch(() => {
        // Une lecture ratée n'est pas grave : on reste sur « indéterminée » et
        // l'écran de réglages proposera de demander l'autorisation.
      });

    return () => {
      vivant = false;
    };
  }, []);

  // 🧹 Nettoyage des anciens rappels QUOTIDIENS. Une version antérieure
  // programmait le rappel du soir en DAILY (type `observations`), qui sonne
  // chaque jour sans distinction de jour de semaine. Le rituel du soir
  // (`rituel.ts`) l'a remplacé par un rappel HEBDOMADAIRE par jour actif — mais
  // les vieux DAILY restaient plantés dans le planificateur du système et
  // continuaient de sonner les jours éteints (le samedi, notamment). On les
  // annule une fois au démarrage, sans toucher aux rappels du rituel (type
  // `rituel`), qui, eux, sont gérés jour par jour.
  useEffect(() => {
    Notifications.getAllScheduledNotificationsAsync()
      .then((liste) =>
        Promise.all(
          liste
            .filter((n) => n.content?.data?.type === 'observations')
            .map((n) =>
              Notifications.cancelScheduledNotificationAsync(n.identifier).catch(() => {}),
            ),
        ),
      )
      .catch(() => {
        // Un planificateur illisible n'est pas un incident : au pire un vieux
        // rappel survit, jamais un crash au démarrage.
      });
  }, []);

  // Le listener de tap : quand quelqu'un touche une notif, on ouvre l'écran qui
  // correspond au champ `data.type` posé à l'envoi. Le journal des observations
  // à ranger est la destination par défaut ; la deep-link fine d'une leçon
  // viendra plus tard du backend, donc pour l'instant elle atterrit là aussi.
  useEffect(() => {
    const abonnement = Notifications.addNotificationResponseReceivedListener((reponse) => {
      const type = reponse.notification.request.content.data?.type;
      switch (type) {
        case 'observations':
          router.push('/journal');
          break;
        case 'lecon':
          router.push('/journal');
          break;
        // Le rappel du rituel du soir (programmé dans `rituel.ts`) ouvre le
        // rituel lui-même : c'est là que le tap doit mener, pas au journal brut.
        case 'rituel':
          router.push('/soir');
          break;
        default:
          // Une notif sans type connu ne redirige nulle part : on préfère ne
          // rien faire plutôt que d'ouvrir un écran au hasard.
          break;
      }
    });

    return () => abonnement.remove();
  }, []);

  // Enregistrement du token push. On ne le demande que si l'autorisation est
  // déjà accordée ET qu'il y a une session : sinon on n'a ni le droit de
  // notifier, ni de compte à qui rattacher le token. Tout le bloc est tolérant
  // à l'échec, parce que la table `push_tokens` peut ne pas encore exister côté
  // backend : dans ce cas on veut un avertissement en console, pas un crash.
  useEffect(() => {
    if (!moi || autorisation !== 'accordee') return;

    // Un simulateur ne reçoit pas de token push : inutile d'appeler le service
    // d'Expo pour rien, il rejetterait la demande.
    if (!Device.isDevice) return;

    let vivant = true;

    (async () => {
      try {
        // Le projectId vient de la config EAS. Sans lui, le service d'Expo ne
        // peut pas attribuer le token, donc on abandonne sans bruit.
        const projectId = Constants.expoConfig?.extra?.eas?.projectId as string | undefined;
        if (!projectId) {
          console.warn('Notifications : projectId EAS absent, token push non demandé.');
          return;
        }

        const { data: token } = await Notifications.getExpoPushTokenAsync({ projectId });
        if (!vivant) return;

        // On upsert sur (user_id, token) : un même compte peut avoir plusieurs
        // appareils, mais on ne veut pas dupliquer le même token deux fois.
        const { error } = await supabase.from('push_tokens').upsert(
          {
            user_id: moi,
            token,
            platform: Platform.OS,
            updated_at: new Date().toISOString(),
          },
          { onConflict: 'user_id,token' },
        );
        if (error) throw error;
      } catch (e) {
        console.warn('Notifications : enregistrement du token push impossible', e);
      }
    })();

    return () => {
      vivant = false;
    };
  }, [moi, autorisation]);

  const demanderAutorisation = useCallback(async () => {
    const reponse = await Notifications.requestPermissionsAsync();
    const etat = traduireAutorisation(reponse);
    setAutorisation(etat);

    // Sur Android, un canal est nécessaire pour que les notifications aient une
    // importance et un son définis. On le crée au moment où l'on obtient le
    // droit de notifier ; l'opération est idempotente, la refaire ne nuit pas.
    if (etat === 'accordee' && Platform.OS === 'android') {
      await Notifications.setNotificationChannelAsync(CANAL_DEFAUT, {
        name: 'Rappels EducooO',
        importance: Notifications.AndroidImportance.DEFAULT,
      });
    }

    return etat === 'accordee';
  }, []);

  const definirRappels = useCallback(async (heures: string[]) => {
    // On repart toujours d'une table rase : on annule les rappels déjà en place
    // avant d'en reposer, pour ne pas empiler les doublons à chaque réglage.
    await Promise.all(
      idsRef.current.map((id) =>
        Notifications.cancelScheduledNotificationAsync(id).catch(() => {
          // Un identifiant déjà expiré ou inconnu n'est pas une erreur qui doit
          // arrêter la (re)planification des autres.
        }),
      ),
    );

    const nouveauxIds: string[] = [];
    const heuresValides: string[] = [];

    for (const heure of heures) {
      const decoupe = decouperHeure(heure);
      // On ignore silencieusement une heure mal formée plutôt que de planter :
      // l'écran de réglages est censé n'envoyer que du 'HH:mm', mais on ne veut
      // pas qu'une valeur bancale casse les rappels valides d'à côté.
      if (!decoupe) continue;

      const id = await Notifications.scheduleNotificationAsync({
        content: {
          title: 'Un moment pour ranger ?',
          body: 'Tu as peut-être des observations en attente.',
          data: { type: 'observations' },
        },
        // Le déclencheur quotidien répète tout seul chaque jour à cette heure :
        // dans cette version d'expo-notifications, le type DAILY n'a pas de
        // champ `repeats`, la répétition est implicite (contrairement à
        // TIME_INTERVAL). On lui passe donc juste l'heure et la minute.
        trigger: {
          type: Notifications.SchedulableTriggerInputTypes.DAILY,
          hour: decoupe.hour,
          minute: decoupe.minute,
          channelId: CANAL_DEFAUT,
        },
      });

      nouveauxIds.push(id);
      heuresValides.push(heure);
    }

    idsRef.current = nouveauxIds;
    const actif = nouveauxIds.length > 0;
    await ecrireRappelsStockes({ actif, heures: heuresValides, ids: nouveauxIds });
    setRappels({ actif, heures: heuresValides });
  }, []);

  const desactiverRappels = useCallback(async () => {
    await Promise.all(
      idsRef.current.map((id) =>
        Notifications.cancelScheduledNotificationAsync(id).catch(() => {}),
      ),
    );
    idsRef.current = [];
    await ecrireRappelsStockes({ actif: false, heures: [], ids: [] });
    setRappels({ actif: false, heures: [] });
  }, []);

  const valeur = useMemo<EtatNotifications>(
    () => ({
      autorisation,
      demanderAutorisation,
      rappels,
      definirRappels,
      desactiverRappels,
    }),
    [autorisation, demanderAutorisation, rappels, definirRappels, desactiverRappels],
  );

  return <Contexte.Provider value={valeur}>{children}</Contexte.Provider>;
}

export function useNotifications(): EtatNotifications {
  const valeur = useContext(Contexte);
  if (!valeur) {
    throw new Error('useNotifications doit être appelé sous FournisseurNotifications.');
  }
  return valeur;
}
