import { Feather } from '@expo/vector-icons';
import { useMemo, useState } from 'react';
import { Pressable, StyleSheet, Switch, Text, View } from 'react-native';

import { Carte } from '@/components/ecran';
import { Tuile } from '@/components/elements';
import {
  Alerte,
  BoutonDiscret,
  BoutonPrincipal,
  BoutonSecondaire,
  Champ,
  Pastilles,
} from '@/components/formulaire';
import { SousEcran } from '@/components/sous-ecran';
import { langue, t } from '@/i18n';
import { useClasse } from '@/lib/classe';
import {
  ajouterCreneaux,
  creneauxDe,
  decalerISO,
  formaterDuree,
  lundiISOLocal,
  modifierCreneau,
  MOMENTS,
  paramsSemaineAB,
  pariteSemaine,
  reglerSemaineAB,
  supprimerCreneau,
  volumeHoraireSemaine,
  type Creneau,
  type Moment,
  type VolumeHoraire,
} from '@/lib/donnees';
import { useRequete } from '@/lib/requete';
import { espace, police, rayon, useCouleurs, useTexte, type Couleurs } from '@/theme/tokens';

/**
 * La semaine type : les moments des journées.
 *
 * 🔑 Ce n'est pas un confort de présentation. Sans créneaux, une activité n'a
 * qu'une date, donc **la couleur de la charte ne code rien** : elle est censée
 * dire le moment de la journée, et le moment vient d'ici. Le compte de
 * démonstration a un modèle « Ma semaine » sans aucun créneau, et c'est pour ça
 * que toutes ses activités sont grises.
 *
 * Le libellé reste libre. Les semaines réellement saisies en base disent
 * « Accueil », « Ateliers », « Activités dirigées », « Récréation »,
 * « Motricité / Éveil », « Regroupement », mais aussi « Collation, enfiler son
 * manteau » et « Préparation pour le dîner » : chacune nomme sa journée avec ses
 * mots, et un menu fermé les lui retirerait. Le **moment**, lui, est un choix
 * fermé, parce que c'est lui qui porte la couleur.
 *
 * 🔑 TROIS GESTES, D'APRÈS LES RETOURS TESTFLIGHT.
 *   1. **Modifier ne détruit pas.** Corriger un créneau est un `UPDATE` sur place
 *      (`modifierCreneau`), jamais un supprimer-recréer : l'`id` ne bouge pas,
 *      donc les activités déjà planifiées dessus gardent leur rattachement, leur
 *      moment et leur couleur.
 *   2. **Un moment sur plusieurs jours.** On coche les jours voulus et le même
 *      créneau se pose sur chacun d'un seul geste (`ajouterCreneaux`).
 *   3. **Toute l'année, ou une semaine.** Le défaut, c'est le modèle récurrent :
 *      les horaires changent rarement. On peut passer sur une semaine précise
 *      pour l'ajuster juste cette fois-là, sans toucher au fond.
 */

/** Cinq jours : l'école fondamentale belge ne siège pas le week-end. */
const JOURS = [1, 2, 3, 4, 5];

/** L'icône d'un moment de la journée, pour sa tuile teintée. */
const ICONE_MOMENT: Record<Moment, keyof typeof Feather.glyphMap> = {
  accueil: 'sunrise',
  ateliers: 'grid',
  dirigees: 'edit-2',
  recreation: 'coffee',
  sortie: 'map-pin',
  social: 'users',
};

/** `09:00`, et rien d'autre. Deux chiffres, deux points, deux chiffres. */
function heureValide(v: string): boolean {
  const m = v.match(/^(\d{2}):(\d{2})$/);
  if (!m) return false;
  return parseInt(m[1], 10) <= 23 && parseInt(m[2], 10) <= 59;
}

/** Force le format pendant la frappe : on pose les deux points tout seul. */
function formaterHeure(v: string): string {
  const chiffres = v.replace(/[^0-9]/g, '').slice(0, 4);
  if (chiffres.length <= 2) return chiffres;
  return `${chiffres.slice(0, 2)}:${chiffres.slice(2)}`;
}

/** `2026-08-24` → `24/08`, pour l'étiquette « Semaine du … ». Locale-neutre. */
function jourMois(lundiISO: string): string {
  const [, m, j] = lundiISO.split('-');
  return `${j}/${m}`;
}

type Portee = 'annee' | 'semaine';

/**
 * Libellés locaux (hors catalogue i18n partagé, édité en parallèle par un·e
 * autre agent·e). On les garde ici, comme le fait `vignettes-activite.tsx`.
 * Seul le nom du créneau devient explicitement optionnel : le moment porte la
 * couleur, le nom n'est qu'un confort.
 */
const L: Record<'fr' | 'nl', { libelleOptionnel: string }> = {
  fr: { libelleOptionnel: 'Tu l’appelles comment ? (optionnel)' },
  nl: { libelleOptionnel: 'Hoe noem je het? (optioneel)' },
};

export default function Semaine() {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  const l = L[langue] ?? L.fr;
  const { classe } = useClasse();
  const classeId = classe?.id ?? null;

  // La vue : le modèle de fond (toute l'année) ou une semaine précise. Le fond
  // est le défaut, parce qu'un horaire de classe change rarement.
  const [vue, setVue] = useState<Portee>('annee');
  const [lundi, setLundi] = useState<string>(() => lundiISOLocal());
  const semaineParam = vue === 'semaine' ? lundi : null;

  const creneaux = useRequete(() => creneauxDe(classeId!, semaineParam), [classeId, semaineParam], {
    actif: !!classeId,
  });

  // Le formulaire, partagé entre l'ajout et la modification. `editId` distingue
  // les deux : null = on ajoute, sinon on modifie ce créneau-là.
  const [ouvert, setOuvert] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [joursSel, setJoursSel] = useState<number[]>([1]);
  const [debut, setDebut] = useState('');
  const [fin, setFin] = useState('');
  const [libelle, setLibelle] = useState('');
  const [moment, setMoment] = useState<Moment | null>(null);
  const [portee, setPortee] = useState<Portee>('annee');
  // Semaine A/B : la parité du créneau en cours d'édition ('A'/'B'/null = toutes).
  const [parite, setParite] = useState<'A' | 'B' | null>(null);
  const [occupe, setOccupe] = useState(false);
  const [erreur, setErreur] = useState<string | null>(null);

  // L'état de l'alternance A/B du modèle de la classe.
  const ab = useRequete(() => paramsSemaineAB(classeId!), [classeId], { actif: !!classeId });
  const abActive = ab.donnees?.active ?? false;

  const liste = creneaux.donnees ?? [];
  const volume = useMemo(() => volumeHoraireSemaine(liste), [liste]);

  function fermer() {
    setOuvert(false);
    setEditId(null);
    setErreur(null);
  }

  function ouvrirAjout() {
    setEditId(null);
    setJoursSel([1]);
    setDebut('');
    setFin('');
    setLibelle('');
    setMoment(null);
    setParite(null);
    // En vue « une semaine », un ajout vise cette semaine par défaut ; sinon le
    // fond. On ne montre le choix que quand une semaine est à l'écran.
    setPortee(vue);
    setErreur(null);
    setOuvert(true);
  }

  function ouvrirModif(cr: Creneau) {
    setEditId(cr.id);
    setJoursSel([cr.jour]);
    setDebut(cr.debut);
    setFin(cr.fin);
    setLibelle(cr.libelle);
    setMoment(cr.moment);
    setParite(cr.parite);
    setPortee(cr.specifique ? 'semaine' : 'annee');
    setErreur(null);
    setOuvert(true);
  }

  function changerVue(v: Portee) {
    setVue(v);
    if (v === 'semaine') setLundi(lundiISOLocal());
    fermer();
  }

  async function basculerAB(actif: boolean) {
    if (!classeId) return;
    setErreur(null);
    try {
      await reglerSemaineAB(classeId, actif, lundiISOLocal());
      ab.recharger();
      creneaux.recharger();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.semaine.erreurAjout);
    }
  }

  // La parité de la semaine affichée (vue « une semaine »), si l'A/B est actif.
  const pariteVue =
    abActive && ab.donnees?.ancre && vue === 'semaine'
      ? pariteSemaine(ab.donnees.ancre, lundi)
      : null;

  async function enregistrer() {
    if (!classeId) return;
    if (!heureValide(debut) || !heureValide(fin)) {
      setErreur(t.semaine.heureInvalide);
      return;
    }
    if (fin <= debut) {
      setErreur(t.semaine.ordreInvalide);
      return;
    }
    if (!joursSel.length) return;
    setErreur(null);
    setOccupe(true);
    const semaineCible = portee === 'semaine' ? lundi : null;
    // La parité ne vaut que pour un créneau récurrent quand l'A/B est actif : un
    // créneau propre à une semaine cible déjà cette semaine-là, la parité est muette.
    const pariteCible = portee === 'annee' && abActive ? parite : null;
    try {
      if (editId) {
        await modifierCreneau(editId, {
          jour: joursSel[0],
          debut,
          fin,
          libelle,
          moment,
          semaine: semaineCible,
          parite: pariteCible,
        });
        creneaux.recharger();
        fermer();
      } else {
        await ajouterCreneaux({
          classeId,
          jours: joursSel,
          debut,
          fin,
          libelle,
          moment,
          semaine: semaineCible,
          parite: pariteCible,
        });
        creneaux.recharger();
        // On garde les jours, le moment et la portée : une enseignante pose
        // souvent des créneaux voisins d'affilée. On ne vide que les heures et
        // le nom, propres à chaque créneau.
        setDebut('');
        setFin('');
        setLibelle('');
      }
    } catch (e) {
      setErreur(
        e instanceof Error
          ? e.message
          : editId
            ? t.semaine.erreurModif
            : t.semaine.erreurAjout,
      );
    } finally {
      setOccupe(false);
    }
  }

  async function retirer(id: string) {
    setErreur(null);
    setOccupe(true);
    try {
      await supprimerCreneau(id);
      creneaux.recharger();
      if (editId === id) fermer();
    } catch (e) {
      setErreur(e instanceof Error ? e.message : t.semaine.erreurAjout);
    } finally {
      setOccupe(false);
    }
  }

  const vide = liste.length === 0;

  return (
    // Le spinner plein écran ne vaut QUE pour le tout premier chargement (aucune
    // donnée encore). Après un ajout de créneau, `recharger()` rebascule
    // `chargement` à vrai : gater dessus masquait tout l'éditeur derrière un
    // spinner, et « ajouter un 2e créneau ne marchait plus » tant qu'on n'était
    // pas ressorti puis revenu (retour Sophie, vidéo). Les données précédentes
    // restant en place, on garde l'éditeur visible pendant le rafraîchissement.
    <SousEcran titre={t.semaine.titre} chargement={creneaux.chargement && !creneaux.donnees}>
      <Carte>
        <Text style={styles.aide}>{t.semaine.aide}</Text>
      </Carte>

      {/* Semaine A/B : l'alternance sur deux semaines. Un interrupteur ouvre la
          possibilité ; chaque créneau peut alors valoir toutes les semaines, ou
          seulement les A, ou les B. La semaine affichée dit laquelle elle est. */}
      <Carte>
        <View style={styles.abTete}>
          <View style={styles.abTexte}>
            <Text style={styles.titreForm}>{t.semaine.ab.titre}</Text>
            <Text style={styles.aide}>{t.semaine.ab.aide}</Text>
          </View>
          <Switch
            value={abActive}
            onValueChange={basculerAB}
            trackColor={{ false: c.bord, true: c.actif }}
          />
        </View>
        {pariteVue ? (
          <Text style={styles.abCourante}>{t.semaine.ab.courante(pariteVue)}</Text>
        ) : null}
      </Carte>

      {/* Toute l'année ou une semaine. Le fond est le défaut. */}
      <Carte>
        <SegmentPortee
          valeur={vue}
          annee={t.semaine.vueAnnee}
          semaine={t.semaine.vueSemaine}
          onChoisir={changerVue}
        />
        {vue === 'annee' ? (
          <Text style={styles.aide}>{t.semaine.vueAide}</Text>
        ) : (
          <NavigateurSemaine
            lundi={lundi}
            surCetteSemaine={lundi === lundiISOLocal()}
            onPrecedente={() => {
              setLundi((l) => decalerISO(l, -7));
              fermer();
            }}
            onSuivante={() => {
              setLundi((l) => decalerISO(l, 7));
              fermer();
            }}
            onRevenir={() => {
              setLundi(lundiISOLocal());
              fermer();
            }}
          />
        )}
      </Carte>

      {creneaux.erreur ? <Alerte message={t.semaine.erreur} /> : null}
      {erreur ? <Alerte message={erreur} /> : null}

      {!vide && volume.totalMinutes > 0 ? <VolumeCarte volume={volume} /> : null}

      {!ouvert ? (
        <BoutonSecondaire libelle={t.semaine.ajouter} onPress={ouvrirAjout} />
      ) : (
        <Carte>
          {editId ? <Text style={styles.titreForm}>{t.semaine.modifierCreneau}</Text> : null}

          {/* Un ajout coche plusieurs jours d'un coup ; une modification porte
              sur le seul jour du créneau, donc un choix simple. */}
          {editId ? (
            <Pastilles
              etiquette={t.semaine.jour}
              options={JOURS.map((j) => ({ id: String(j), libelle: t.semaine.jours[j - 1] }))}
              choisi={String(joursSel[0])}
              onChoisir={(v) => setJoursSel([v ? parseInt(v, 10) : joursSel[0]])}
            />
          ) : (
            <>
              <SelecteurJours valeur={joursSel} onChanger={setJoursSel} />
              <Text style={styles.aide}>{t.semaine.joursIndice}</Text>
            </>
          )}

          <Text style={styles.etiquette}>{t.semaine.quand}</Text>
          <View style={styles.heures}>
            <View style={styles.moitie}>
              <Champ
                etiquette={t.semaine.debut}
                value={debut}
                onChangeText={(v) => setDebut(formaterHeure(v))}
                placeholder={t.semaine.heureIndice}
                keyboardType="number-pad"
                editable={!occupe}
              />
            </View>
            <View style={styles.moitie}>
              <Champ
                etiquette={t.semaine.fin}
                value={fin}
                onChangeText={(v) => setFin(formaterHeure(v))}
                placeholder={t.semaine.heureIndice}
                keyboardType="number-pad"
                editable={!occupe}
              />
            </View>
          </View>

          {/* Ordre pensé pour enchaîner sans aller-retour (retours Mme Mahé) :
              jours → heures → MOMENT (il porte la couleur, donc il vient tôt et
              reste visible d'un coup, aucune étape cachée) → nom optionnel. */}
          <Pastilles
            etiquette={t.semaine.moment}
            options={MOMENTS.map((m) => ({ id: m, libelle: t.semaine.moments[m] }))}
            choisi={moment}
            onChoisir={(v) => setMoment((v as Moment) ?? null)}
          />
          <Text style={styles.aide}>{t.semaine.momentAide}</Text>

          {/* Le nom n'est qu'un confort : le moment code déjà la couleur, donc on
              le marque optionnel pour ne pas retenir l'enseignant·e. */}
          <Champ
            etiquette={l.libelleOptionnel}
            value={libelle}
            onChangeText={setLibelle}
            placeholder={t.semaine.libelleIndice}
            editable={!occupe}
          />

          {/* Semaine A/B : ce créneau revient toutes les semaines, ou seulement
              les A, ou seulement les B. Muet pour un créneau propre à une semaine. */}
          {abActive && portee === 'annee' ? (
            <Pastilles
              etiquette={t.semaine.ab.parite}
              options={[
                { id: 'toutes', libelle: t.semaine.ab.toutes },
                { id: 'A', libelle: t.semaine.ab.semaineA },
                { id: 'B', libelle: t.semaine.ab.semaineB },
              ]}
              choisi={parite ?? 'toutes'}
              onChoisir={(v) => setParite(v === 'A' ? 'A' : v === 'B' ? 'B' : null)}
            />
          ) : null}

          {/* La portée ne se choisit que quand une semaine est à l'écran : en vue
              « toute l'année », il n'y a pas de semaine cible. */}
          {vue === 'semaine' ? (
            <Pastilles
              etiquette={t.semaine.portee}
              options={[
                { id: 'annee', libelle: t.semaine.porteeAnnee },
                { id: 'semaine', libelle: `${t.semaine.porteeSemaine} (${jourMois(lundi)})` },
              ]}
              choisi={portee}
              onChoisir={(v) => setPortee(v === 'semaine' ? 'semaine' : 'annee')}
            />
          ) : null}

          <BoutonPrincipal
            libelle={editId ? t.semaine.enregistrerModif : t.semaine.enregistrer}
            onPress={enregistrer}
            occupe={occupe}
            inactif={!debut || !fin || !joursSel.length}
          />
          <BoutonDiscret libelle={t.commun.annuler} onPress={fermer} />
        </Carte>
      )}

      {vide ? (
        <Carte>
          <Text style={texte.discret}>
            {vue === 'semaine' ? t.semaine.videSemaine : t.semaine.vide}
          </Text>
        </Carte>
      ) : (
        JOURS.map((j) => {
          const duJour = liste.filter((cr) => cr.jour === j);
          if (!duJour.length) return null;
          return (
            <View key={j} style={styles.jour}>
              <Text style={styles.enteteJour}>{t.semaine.jours[j - 1]}</Text>
              {duJour.map((cr) => (
                <LigneCreneau
                  key={cr.id}
                  creneau={cr}
                  occupe={occupe}
                  montrerBadge={vue === 'semaine'}
                  onModifier={() => ouvrirModif(cr)}
                  onRetirer={() => retirer(cr.id)}
                />
              ))}
            </View>
          );
        })
      )}
    </SousEcran>
  );
}

/** Le bascule « toute l'année » / « une semaine ». */
function SegmentPortee({
  valeur,
  annee,
  semaine,
  onChoisir,
}: {
  valeur: Portee;
  annee: string;
  semaine: string;
  onChoisir: (v: Portee) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const options: { id: Portee; libelle: string }[] = [
    { id: 'annee', libelle: annee },
    { id: 'semaine', libelle: semaine },
  ];
  return (
    <View style={styles.segment}>
      {options.map((o) => {
        const actif = o.id === valeur;
        return (
          <Pressable
            key={o.id}
            accessibilityRole="button"
            accessibilityState={{ selected: actif }}
            accessibilityLabel={o.libelle}
            onPress={() => onChoisir(o.id)}
            style={[styles.segmentBouton, actif && styles.segmentActif]}>
            <Text style={[styles.segmentTexte, actif && styles.segmentTexteActif]}>
              {o.libelle}
            </Text>
          </Pressable>
        );
      })}
    </View>
  );
}

/** Les flèches de navigation d'une semaine à l'autre. */
function NavigateurSemaine({
  lundi,
  surCetteSemaine,
  onPrecedente,
  onSuivante,
  onRevenir,
}: {
  lundi: string;
  surCetteSemaine: boolean;
  onPrecedente: () => void;
  onSuivante: () => void;
  onRevenir: () => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <View style={styles.nav}>
      <View style={styles.navLigne}>
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={t.semaine.semainePrec}
          onPress={onPrecedente}
          style={styles.navFleche}>
          <Feather name="chevron-left" size={22} color={c.encre} />
        </Pressable>
        <Text style={styles.navTexte}>{t.semaine.semaineDu(jourMois(lundi))}</Text>
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={t.semaine.semaineSuiv}
          onPress={onSuivante}
          style={styles.navFleche}>
          <Feather name="chevron-right" size={22} color={c.encre} />
        </Pressable>
      </View>
      {!surCetteSemaine ? (
        <Pressable accessibilityRole="button" onPress={onRevenir}>
          <Text style={styles.navRetour}>{t.semaine.cetteSemaine}</Text>
        </Pressable>
      ) : null}
    </View>
  );
}

/** Le choix multiple des jours, pour poser un même moment sur plusieurs jours. */
function SelecteurJours({
  valeur,
  onChanger,
}: {
  valeur: number[];
  onChanger: (jours: number[]) => void;
}) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  function basculer(j: number) {
    onChanger(valeur.includes(j) ? valeur.filter((x) => x !== j) : [...valeur, j]);
  }
  return (
    <View>
      <Text style={styles.etiquette}>{t.semaine.joursQuels}</Text>
      <View style={styles.chipsJours}>
        {JOURS.map((j) => {
          const actif = valeur.includes(j);
          return (
            <Pressable
              key={j}
              accessibilityRole="button"
              accessibilityState={{ selected: actif }}
              accessibilityLabel={`${t.semaine.joursQuels} ${t.semaine.jours[j - 1]}`}
              onPress={() => basculer(j)}
              style={[styles.chipJour, actif && styles.chipJourActif]}>
              <Text style={[styles.chipTexte, actif && styles.chipTexteActif]}>
                {t.semaine.jours[j - 1].slice(0, 3)}
              </Text>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
}

function LigneCreneau({
  creneau,
  occupe,
  montrerBadge,
  onModifier,
  onRetirer,
}: {
  creneau: Creneau;
  occupe: boolean;
  montrerBadge: boolean;
  onModifier: () => void;
  onRetirer: () => void;
}) {
  const c = useCouleurs();
  const texte = useTexte();
  const styles = useMemo(() => creerStyles(c), [c]);
  return (
    <Carte compacte>
      <View style={styles.ligne}>
        {/* Tap sur le corps pour modifier : on édite sur place, on ne recrée
            jamais, donc les activités posées dessus gardent leur rattachement. */}
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={`${t.semaine.modifierCreneau} ${creneau.libelle} ${creneau.debut}`}
          disabled={occupe}
          onPress={onModifier}
          style={styles.corpsTap}>
          {/* La couleur du moment, celle-là même que porteront les activités
              posées sur ce créneau. Tuile grise quand le moment n'est pas précisé. */}
          {creneau.moment ? (
            <Tuile icone={ICONE_MOMENT[creneau.moment]} moment={creneau.moment} />
          ) : (
            <Tuile icone="clock" />
          )}
          <View style={styles.corps}>
            {/* Un créneau au libellé vide (une récré, un moment posé sans le
                nommer) montrait « Rien ce jour-là » : on retombe sur le NOM de
                son moment (« Récréation »…), qui dit déjà ce que c'est (retour
                Sophie). « Rien » ne reste que pour un créneau vraiment anonyme. */}
            <Text style={texte.corps}>
              {creneau.libelle || (creneau.moment ? t.semaine.moments[creneau.moment] : t.semaine.rien)}
            </Text>
            <Text style={texte.discret}>
              {creneau.debut} à {creneau.fin}
            </Text>
            {montrerBadge ? (
              <Text style={creneau.specifique ? styles.badgeSemaine : styles.badgeAnnee}>
                {creneau.specifique ? t.semaine.badgeSpecifique : t.semaine.badgeAnnee}
              </Text>
            ) : null}
            {creneau.parite ? (
              <Text style={styles.badgeParite}>{t.semaine.ab.badge(creneau.parite)}</Text>
            ) : null}
          </View>
        </Pressable>
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={`${t.semaine.supprimer} ${creneau.libelle} ${creneau.debut}`}
          disabled={occupe}
          onPress={onRetirer}
          style={styles.retirer}>
          <Feather name="x" size={18} color={c.encreDouce} />
        </Pressable>
      </View>
    </Carte>
  );
}

/**
 * Le volume horaire de la semaine type, par moment. Une carte de lecture pure
 * (aucune saisie) : le total en tête, puis une barre par moment, du plus lourd
 * au plus léger. Récréation et pauses sont déjà exclues du calcul.
 */
function VolumeCarte({ volume }: { volume: VolumeHoraire }) {
  const c = useCouleurs();
  const styles = useMemo(() => creerStyles(c), [c]);
  const max = volume.parMoment[0]?.minutes ?? 1;
  return (
    <Carte>
      <View style={styles.volumeTete}>
        <Tuile icone="clock" />
        <View style={styles.corps}>
          <Text style={styles.titreForm}>{t.semaine.volume.titre}</Text>
          <Text style={styles.aide}>{t.semaine.volume.aide}</Text>
        </View>
        <Text style={styles.volumeTotal}>{formaterDuree(volume.totalMinutes)}</Text>
      </View>
      <View style={styles.volumeListe}>
        {volume.parMoment.map(({ moment, minutes }) => {
          const couleur = moment === 'autre' ? c.encreDouce : c.moment[moment];
          const libelle =
            moment === 'autre' ? t.semaine.volume.autre : t.semaine.moments[moment];
          return (
            <View key={moment} style={styles.volumeRangee}>
              <Text style={styles.volumeLabel} numberOfLines={1}>
                {libelle}
              </Text>
              <View style={styles.volumeBarre}>
                <View
                  style={[
                    styles.volumeBarreRemplie,
                    { width: `${Math.round((minutes / max) * 100)}%`, backgroundColor: couleur },
                  ]}
                />
              </View>
              <Text style={styles.volumeDuree}>{formaterDuree(minutes)}</Text>
            </View>
          );
        })}
      </View>
    </Carte>
  );
}

